SELECT 'moj-all-verified-judgments-review-002-chunk-130' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"ef6d7863-d4a0-554a-8291-cfd9446c5d15","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة حقيبة من داخل سيارة مشتملة على أوراق رسمية -حتليل عينة دم املدعى عليه -تطابق أمناط وراثية -محضر انتقال ومعاينة -وجود سوابق على املدعى عليه -عدم تداخل العقوبات -عدم انطباق حكم حد السرقة إذا لم يكن املسروق ماال- كسر زجاج سيارة.","document_number":"3461346","case_number":"33591190","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/14","year":"1434","subject":"سرقة -سرقة حقيبة من داخل سيارة مشتملة على أوراق رسمية -حتليل عينة دم املدعى عليه -تطابق أمناط وراثية -محضر انتقال ومعاينة -وجود سوابق على املدعى عليه -عدم تداخل العقوبات -عدم انطباق حكم حد السرقة إذا لم يكن املسروق ماال- كسر زجاج سيارة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك ‪ 3461346 :‬تاريخه ‪1434/3/14:‬هـ‬\n                          ‫رقم الدعوى ‪33591190 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34353817‬تاريخه ‪1434/11/09 :‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة حقيبــة مــن داخــل ســيارة مشــتملة علــى أوراق رســمية‬\n      ‫‪ -‬حتليــل عينــة دم املدعــى عليــه ‪ -‬تطابــق أمنــاط وراثيــة ‪ -‬محضــر‬\n      ‫انتقــال ومعاينــة ‪ -‬وجــود ســوابق علــى املدعــى عليــه ‪ -‬عــدم تداخــل‬\n      ‫العقوبــات ‪ -‬عــدم انطبــاق حكــم حــد الســرقة إذا لــم يكــن املســروق مــاالً‪-‬‬\n                                                                 ‫كســر زجــاج ســيارة‪.‬‬\n\n\n\n\n               ‫إذا لم يكن املسروق ما ًال فال تنطبق عليه أحكام حد السرقة ‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بكســر زجــاج ســيارة وســرقة‬\n      ‫حقيبــة حتتــوي أوراقـ ًا رســمية وبطاقــات أحــوال ‪ ،‬وطلــب املدعــي العــام‬\n      ‫إثبــات إدانتــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ ،‬قبــض علــى املدعــى عليــه‬\n      ‫بعــد إدانتــه يف قضيــة ســرقة وبتحليــل عينــة مــن دمــه أثبتــت الفحوصــات‬\n      ‫الوراثيــة تطابــق األمنــاط الوراثيــة لعينــة دم املدعــى عليــه ‪ ،‬وقــد أقــر‬\n      ‫املدعــى عليــه بالدعــوى وتبــن وجــود ســوابق قضائيــة علــى املدعــى‬\n      ‫عليــه‪ ،‬ولــم تنطبــق أحــكام حــد الســرقة علــى املســروق إذا لــم يكــن‬\n      ‫مــا ًال ‪ ،‬لــذا حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد ‪،‬‬\n                                ‫ومت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n‫‪145‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33591190‬وتاريخ ‪1433/10/09‬هـ الـمقـي ــدة‬\n‫بالـمـحـكـم ــة بـرق ـ ــم ‪ 331769804‬وتــاري ـ ــخ ‪1433/10/09‬ه ـ فـف ــي‬\n‫يـ ــوم االثـن ــن الـمـواف ــق ‪1434/02/25‬ه ـ افـتـت ـحـ ــت اجلـل ـسـ ــة السـاعـ ــة‬\n‫‪ 01 : 00‬وفيهــا حضــر املدعــي العــام ‪ .....‬وادعــى علــى ‪ 27،........‬عامــا‪،‬‬\n‫ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي رقــم (‪ ).........‬أوقــف بتاريــخ‬\n‫‪1433/2/22‬ه ـ علــى ذمــة قضيــة ســرقة وأحيــل إلــى ســجن امللــز مبوجب‬\n‫أمــر التوقيــف رقــم (‪ )138‬وتاريــخ ‪1433/2/27‬ه ـ اســتناد ًا للبنــد‬\n‫خامسـ ًا مــن القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي‬\n‫علــى املــادة ( ‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة وقيــد ســجين ًا برقــم‬\n‫(‪.)..........‬قائــا يف دعــواه عليــه انــه بتاريــخ ‪1432/2/22‬ه ـ قبــض علــى‬\n‫املدعــى عليــه مــن قبــل إحــدى فــرق الدوريــات األمنيــة التهامــه بالســرقة‬\n‫مــن داخــل ســيارة حتمــل اللوحــة رقــم ( ‪] ).......‬صــدر بحقــه الئحــة دعــوى‬\n‫عامــة وأحيلــت إلــى احملكمــة اجلزئية بالريــاض باخلطاب رقم (‪)46029‬‬\n‫وتاريــخ ‪1433/4/20‬ه ـ [‪ ،‬وبتحليــل عينــة دمــه أثبــت تقريــر الفحــوص‬\n‫الوراثيــة رقــم (‪11-910‬فحــوص وراثيــة لعــام ‪1433‬هــ) تطابــق األمنــاط‬\n‫الوراثيــة لعينــة دم املدعــى عليــه مــع عينــة مســحة دم رفعــت مــن املقعــد‬\n‫اخللفــي األميــن للســيارة حتمــل اللوحــة رقــم (‪ ).... ...‬العائــدة لــ‪ ......‬واملعمــم‬\n‫عــن كســر زجاجهــا وســرقة حقيبــة بداخلهــا عــدد (‪ )3‬جــوازات ســفر‬\n‫إحداهــا عائــد للــ‪ ......‬وعــدد (‪ )3‬بطاقــات أحــوال عائــدة ‪ .....‬ووالدتــه‬\n\n                                                                                             ‫‪146‬‬\n\f      ‫وابنــه وصــورة دفتــر عائلــة ‪ .....‬مطبوعــات رســمية لــ‪ .....‬وأوراق متنوعــة‬\n      ‫تابعــة ملكتــب ‪ ......‬وبســماع أقــوال املبلــغ ‪« .......‬ســوري اجلنســية» مبوجــب‬\n      ‫رخصــة اإلقامــة رقــم (‪ ).......‬يعمــل حتــت كفالــة ‪ .....‬أفــاد أنــه أوقــف‬\n      ‫الســيارة التــي بقيادتــه حتمــل اللوحــة رقــم (‪ ).......‬العائــدة ملكيتهــا‬\n      ‫ل ــ‪ ......‬أمــام شــقته وبعــد نومــه طــرق عليــه جــاره البــاب وأخبــره بــأن‬\n      ‫الســيارة تعرضــت لكســر الزجــاج األميــن اخللفــي واتضــح أنــه ســرق منهــا‬\n      ‫عــدد (‪ )3‬جــوازات ســفر إحداهــا عائــد لــ‪ .....‬وعــدد (‪ )3‬بطاقــات أحــوال‬\n      ‫عائــدة لــ‪ .....‬ووالدتــه وابنــه وصــورة دفتــر عائلــة ‪ .....‬مطبوعــات رســمية‬\n      ‫لــ‪ .....‬وأوراق متنوعــة تابعــة ملكتــب ‪ ......‬وباالنتقــال للموقــع ملعاينــة‬\n      ‫الســيارة حتمــل اللوحــة رقــم (‪ )............‬اتضــح تعــرض الزجــاج اخللفــي‬\n      ‫األميــن للكســر والزجــاج متناثــر علــى املرتبــة ووجــدت بقعــة دم علــى‬\n      ‫املرتبــة وكذلــك الــدرج األمامــي مفتــوح ومت رفــع اآلثــار مــن قبــل األدلــة‬\n      ‫اجلنائيــة‪ .‬وباســتجوابه أقــر أنــه أثنــاء مــروره وبقيادتــه ســيارة مــن نــوع‬\n      ‫بأحــد الشــوارع توقــف بجانــب ســيارته فشــاهد بداخــل الســيارة حقيبــة‬\n      ‫ســوداء فأخــرج مــن ســيارته مفــك العجــات وكســر الزجــاج األميــن‬\n      ‫وســرق احلقيبــة وعثــر بداخلهــا علــى أوراق رســمية عائــدة ل ـ ‪......‬وصــور‬\n      ‫بطاقــات ‪ .....‬ووالدتــه وابنــه وجــواز ســفر وبطاقــة عائلــة ‪.....‬وقــام برميهــا‬\n      ‫يف أحــد أوعيــة النفايــات وصــادق علــى ذلــك شــرع ًا ‪ .‬وقد أســفر التحقيق‬\n      ‫عــن اتهــام املدعــى عليــه بكســر زجــاج ســيارة عائــدة لـ ـ ‪ ......‬وســرقة‬\n      ‫حقيبــة حتــوي أوراق رســمية وبطاقــات أحــوال وجــوازات ســفر ‪ ،‬وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ :‬أوالً‪ :‬مــا جــاء إقــرار املصــدق شــرع ًا املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )15‬مــن ملــف التحقيــق رقــم (‪.)1‬ثانيـ ًا ‪ :‬مــا تضمنــه‬\n      ‫تقريــر الفحــوص الوراثيــة رقــم (‪ /11-910‬فحــوص وراثيــة ‪1433/‬ه ـ )‬\n\n\n‫‪147‬‬\n\f‫واملرفــق علــى اللفــات رقــم (‪.)18-16‬ثالثـاً‪ :‬مــا جــاء يف محضــر االنتقــال‬\n‫واملعاينــة املــدون علــى الصفحتــن رقــم (‪ )3-2‬مــن دفتــر التحقيــق املرفــق‬\n‫لفــة رقــم (‪ .)1‬رابعـاً‪ :‬مــا جــاء يف احملضــر املعــد مــن قبــل الفرقــة املرفــق‬\n‫علــى اللفــة رقــم (‪ .)7‬وببحــث ســوابقه اتضــح وجــود أربــع ســوابق اثنتــان‬\n‫منهــا حيــازة مخــدرات اقترنــت إحداهــا باســتعمال املخــدرات والثالثــة‬\n‫شــرب املســكرات والرابعــة ســرقة ســيارات مســجلة عليــه حتــى تاريخه‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة بليغــة زاجــرة‬\n‫لــه رادعــة لغيــره لقــاء مــا أســند إليــه والتشــديد عليــه مبــا يردعــه لقــاء‬\n‫ذلــك ولعــدم ارتداعــه مــن عقوبــات ســوابقه ((علم ـ ًا بــأن احلــق اخلــاص‬\n‫مــازال قائمـاً)) ‪ .‬وبــاهلل التوفيــق‪ .‬أ ه ـ ‪ .‬وبعــرض دعــوى املدعــي العام على‬\n‫املدعــى عليــه ‪ _ ...........‬ســعودي بالهويــة رقــم ‪ .....‬اجــاب قائــا مــا جــاء‬\n‫يف دعــوى املدعــي العــام كلــه صحيــح فقــد قمــت بكســر زجــاج ســيارة‬\n‫مــن نــوع ‪ .....‬ووجــدت بداخلهــا كيــس بداخلــه اوراق رســمية فأخذتــه‬\n‫وملــا لــم أجــد فيــه مبالــغ ماليــة قمــت برميــه يف برميــل النفايــات والســوابق‬\n‫املذكــورة يف دعــوى املدعــي العــام صحيحــه وقــد نلــت عقابــي عليهــا‬\n‫هكــذا أجــاب‪ .‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وحيــث‬\n‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام وحيــث ان املســروق ليــس‬\n‫مــاال فــا تنطبــق عليــه أحــكام حــد الســرقة وألن مــا قــام بــه املدعــى‬\n‫عليــه جــرم عظيــم يوجــب تعزيــره ‪ .‬فعليــه فقــد ثبــت لــدي قيــام املدعــى‬\n‫عليــه بكســر زجــاج ســيارة واخــذ كيــس بداخلــه أوراق رســمية وقــررت‬\n‫تعزيــره لقــاء ذلــك بســجنه ثــاث ســنوات مــن تاريــخ ايقافــه وجلــده‬\n‫ثالثمائــة جلــده مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــده بــن‬\n\n\n                                                                                         ‫‪148‬‬\n\f      ‫كل دفعــة واخــرى عشــرة ايــام وبذلــك حكمــت ‪ .‬وبعرضــه علــى املدعــي‬\n      ‫العــام قــرر االعتــراض مكتفيــا بالئحــة الدعــوى امــا املدعــى عليــه فقــد‬\n      ‫قــرر القناعــة باحلكــم‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫ويف يــوم األحــد ‪1434/6/11‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫العــام وحضــر حلضــوره املدعــى عليــه ‪ ....‬وقــد عــادت املعاملــة حملكمــة‬\n      ‫االســتئناف وبرفقهــا القــرار رقــم ‪ 34205524‬وتاريــخ ‪1434/5/5‬ه ـ‬\n      ‫ونــص احلاجــة منــه‪ :‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قررنــا إعادتهــا ملالحظــة االتــي‪ :‬جــاء يف دعــوى املدعــي العــام قوله (صدر‬\n      ‫بحقــه) اي بحــق املدعــى عليــه دعــوى عامــة وأحيلــت الــى احملكمــة‬\n      ‫اجلزئيــة بالريــاض باخلطــاب رقــم (‪ )46029‬وتاريــخ ‪1434/4/20‬ه ـ فهــل‬\n      ‫مــا صــدر بحقــه هــو يف نفــس هــذه الدعــوى او غيرهــا علــى فضيلتــه‬\n      ‫التحقــق مــن ذلــك فــإن كانــت هــي نفــس هــذه الدعــوى بوقائعهــا وزمنهــا‬\n      ‫فمــا وجــه تكــرار الدعــوى عليــه ‪.‬أ ه ـ ‪ .‬فعليــه اجيــب اصحــاب الفضيلــة‬\n      ‫بأنــه جــرى الكتابــة إلدارة احملكمــة عــن ذلــك فاتضــح بــأن القضيــة‬\n      ‫املذكــورة يف القــرار احيلــت للمكتــب القضائــي رقــم ‪ 26‬وصــدرت‬\n      ‫حملكمــة االســتئناف برقــم ‪ 33/772795‬يف ‪1433/6/1‬ه ـ وبســؤال‬\n      ‫املدعــى عليــه عــن ذلــك قــال نعــم لقــد حكمــت يف قضيــة ســرقة ســيارة‬\n      ‫نــوع ‪ .....‬يف املكتــب القضائــي رقــم ‪ .....‬لــدى الشــيخ ‪ .....‬هكــذا‬\n      ‫اجــاب‪ .‬وبعــرض ذلــك علــى املدعــي العــام أجــاب بقولــه ان دعــواي يف‬\n      ‫ســرقة ســيارة نــوع والعائــدة ‪ .....‬هكــذا أجــاب‪ .‬فعليــه فلــم يظهــر لــي ان‬\n      ‫مــا حكــم بــه علــى املدعــى عليــه يف القضيــة املنظــورة لــدي لــه عالقــة‬\n      ‫بالقضيــة التــي باملكتــب القضائــي رقــم ‪ .....‬لكــون املدعــى عليــه قــام‬\n      ‫بســرقتني لســيارتني كل ســرقة واقعــة ومنفصلــة عــن االخــرى فأمــرت‬\n\n\n‫‪149‬‬\n\f‫بإحلــاق ذلــك يف القــرار وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫االجــراء حســب املتبــع ‪.‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫ويف يــوم االثنــن ‪1434/8/8‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34267458‬يف‬\n‫‪1434/7/12‬ه ـ ونــص احلاجــة منــه‪ :‬وحيــث ســبق دراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة وباالطــاع علــي مــا أجاب به فضيلته علي قرارنا‬\n‫رقــم ‪ 34205524‬وتاريــخ ‪1434/5/5‬ه ـ لوحــظ مــا يلــي ذكــر املدعــى‬\n‫عليــه أنــه حكــم عليــه قبــل هــذه القضيــة يف قضيــة ســرقة وصــدرت‬\n‫قضيتــه حملكمــة االســتئناف برقــم ‪ 772795/33‬وتاريــخ ‪1433/6/1‬هـ‬\n‫وقــد جعــل فضيلتــه بدايــة ســجن املدعــى عليــه يف هــذه القضيــة التــي بــن‬\n‫يديــه مــن تاريــخ توقيفــه مــع أن املدعــي عليــه محكــوم عليــه يف قضيــة‬\n‫ســرقة ســابقا ولــم يتحقــق فضيلتــه مــن صفــة احلكــم الســابق حتــي ال‬\n‫تتدخــل عقوبــة الســجن يف هــذه القضيــة مــع القضيــة الســابقة لــو كان‬\n‫مســجونا فيهــا‪ .‬واهلل املوفــق أ ه ـ ‪ .‬فعليــه أجيــب أصحــاب الفضيلــة بأنــه‬\n‫حضــر املدعــى عليــه وجــرى ســؤاله عــن القضيــة الســابقة فأجــاب بقولــه‬\n‫لقــد حكــم علــي فضيلتــه القاضــي ‪ ....‬يف القضيــة االولــى بالســجن ملــدة‬\n‫ســنتني واجللــد ثالثمائــة جلــده هكــذا أجــاب فعليــه فقــد قــررت بــأن‬\n‫يبــدا احلكــم بســجن املدعــى عليــه يف القضيــة املنظــورة لــدي مــن تاريــخ‬\n‫انتهــاء محكوميتــه االولــى والتــي صــدر فيهــا حكمــا مــن الشــيخ ‪.....‬‬\n‫وبذلــك حكمــت وبعــرض علــي املدعــى عليــه قــرر القناعــة بذلــك ثــم‬\n‫حضــر املدعــي العــام وبعــرض ذلــك عليــه قــرر بأنــه معترضــا فأمــرت‬\n‫بإحلــاق ذلــك يف القــرار وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫حســب املتبــع‪ .‬واهلل املوفــق وصلــي اهلل وســلم علــي نبينــا محمــد‪ .‬حــرر‬\n\n\n                                                                                    ‫‪150‬‬\n\f                                                                          ‫‪1434/8/8‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد‪ .‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم ‪341858169‬‬\n      ‫وتاريــخ ‪1434/10/14‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ ‪ .......‬املســجل برقــم ‪ 3461346‬وتاريــخ‬\n      ‫‪1434/3/14‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ .....‬هويــة رقــم (‪)......‬‬\n      ‫التهامــه بقضيــة ســرقة علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وحيــث ســبق دراســة القــرار وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى‬\n      ‫قرارنــا رقــم ‪ 34205524‬وتاريــخ ‪1434/5/5‬ه ـ قررنــا املصادقــة علــى‬\n      ‫احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                   ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪151‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":145,"source_page_end":151,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0560af51d09b619ad296e98335360a29d59e33187ef7ed0bc2509cffb24a9590","normalized_text_hash":"b7d861c56ea56ae3aee6edbf36805ea10b47fc1bb861b3c9759bb46f9cbcde39","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p145-3461346"},{"id":"90f1995f-d555-5212-a9a7-14b5f17ac223","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -شروع يف سرقة أساك كهربائية -إقرار املدعى عليه - وجود سوابق قضائية على املدعى عليه -إدانة املدعى عليه بالسرقة -التعزير بالسجن واجللد -التوصية باإلبعاد عن الباد.","document_number":"3433258","case_number":"33593795","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/9","year":"1434","subject":"سرقة -شروع يف سرقة أساك كهربائية -إقرار املدعى عليه - وجود سوابق قضائية على املدعى عليه -إدانة املدعى عليه بالسرقة -التعزير بالسجن واجللد -التوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك ‪ 3433258 :‬تاريخه ‪1434/02/9:‬هـ‬\n                    ‫رقم القضية ‪33593795 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34185475‬تاريخه‪1434/04/13 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬شــروع يف ســرقة أســاك كهربائيــة ‪ -‬إقــرار املدعــى عليــه ‪-‬‬\n‫وجــود ســوابق قضائيــة علــى املدعــى عليــه ‪ -‬إدانــة املدعى عليه بالســرقة‬\n          ‫‪ -‬التعزيــر بالســجن واجللــد‪ -‬التوصيــة باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                                                        ‫املرء مؤاخذ بإقراره ‪.‬‬\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه نــازح بالشــروع يف ســرقة كيابــل مــن‬\n‫موقــع شــركة ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم‬\n‫عليــه بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد بــاغ مفــاده‬\n‫وجــود املدعــى عليــه يف إحــدى غــرف الكهربــاء حيث كان يريد ســرقة‬\n‫األســاك الكهربائيــة بعــد قطعهــا ‪،‬وقــد تضمنــت القضيــة إقــرار‬\n‫املدعــى عليــه بالدعــوى ‪ ،‬حكمــت احملكمــة بالتعزيــر بالســجن واجللــد‬\n‫والتوصيــة باإلبعــاد عــن البــاد ‪ ،‬ومت تصديــق احلكــم مــن محكمــة‬\n                                                           ‫االســتئناف‪.‬‬\n\n\n\n\n                                                                                   ‫‪152‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ 1433/10/10‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ ..........‬وتاريــخ ‪ 1433/10/10‬ه ـ ففــي يــوم األربعــاء‬\n      ‫املوافــق‪ 1434/01/21‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 15‬وفيهــا قــدم‬\n      ‫املدعــي العــام الئحــة دعــوى عامــة ضــد ‪ )30( ........... /‬عامـ ًا (نــازح) يقيم‬\n      ‫يف مدينــة الريــاض موقــوف بتاريــخ ‪1433/5/12‬ه ـ مبوجــب مذكــرة‬\n      ‫التوقيــف رقــم ‪ ....‬وتاريــخ ‪1433/6/1‬ه ـ أنــه بتاريــخ ‪1433/5/12‬ه ـ ورد‬\n      ‫ملركــز شــرطة العزيزيــة تقريــر دوريــات األمــن ‪ ....‬املتضمــن بــاغ‪...... /‬‬\n      ‫الوكيــل الشــرعي لشــركة ‪ ......‬والــذي يفيــد فيــه انــه أثنــاء تواجــده‬\n      ‫بالشــركة تفاجــأ بانقطــاع التيــار الكهربائــي وعنــد ذهابــه إلــى غرفــة‬\n      ‫الكهربــاء شــاهد شــخص بداخلهــا واتضــح أنــه املدعــى عليــه وأبلــغ‬\n      ‫دوريــات األمــن ومت القبــض عليــه وكان يرافقــه شــخص آخــر ارتكــب‬\n      ‫الفــرار وعثــر يف املوقــع علــى منشــار ومفــك ثقيــل وكشــف صغيــر جــرى‬\n      ‫اســتالمه وإيقافــه رهــن التحقيــق وباالنتقــال للموقــع اتضــح أنــه يقــع‬\n      ‫بطريــق ‪ .....‬شــركة ال‪ .....‬حيــث لوحــظ وجــود قطــع يف احــد الكيابــل‬\n      ‫التابعــة للشــركة وتبــن بأنــه الســبب يف انقطــاع التيــار اتخــذ الــازم‬\n      ‫مبعرفــة املختصــن‪ .‬وبســماع أقوالــه اعتــرف بأنــه حضــر إلــى مســتودع‬\n      ‫لغرض الســرقة للســكراب املوجود داخل املســتودع وكان معه منشــار‬\n      ‫حديــد وصــدق اعترافــه شــرع ًا بذلــك‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه‬\n      ‫االتهــام للمدعــى عليــه بالشــروع يف ســرقة كيابــل مــن شــركة ال‪......‬‬\n\n‫‪153‬‬\n\f                                                          ‫الواقعــة بطريــق اخلــرج‪.‬‬\n                                                ‫وذلك لألدلة والقرائن التالية ‪/:‬‬\n‫‪1‬ـ اعترافــه املصــدق شــرع ًا املثبــت مبلــف التحقيــق بالصفحــة رقــم ( ‪) 2‬‬\n                                            ‫مــن ملــف التحقيــق لفــه رقــم ( ‪. ) 1‬‬\n                                       ‫‪2‬ـ محضر القبض املرفق لفة رقم ( ‪.) 3‬‬\n               ‫وبالبحث عن سوابقه عثر له على سابقتني حيازة مخدرات‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫لــذا أطلــب إثبــات مــا اســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n‫ذلــك (علم ـ ًا بــأن احلــق اخلــاص مــا زال قائم ـاً) وبــاهلل التوفيــق وبعــرض‬\n‫ا إال يف‬  ‫ذلــك علــى املدعــى عليــه صــادق علــى الدعــوى جملــة وتفصي ـ ً‬\n‫وجــود شــخص آخــر معــه فقــال لــم يوجــد شــخص معــي وقــد شــرعت‬\n‫يف ســرقة كيابــل مــن الشــركة املذكــورة كمــا ورد يف الدعــوى‬\n‫فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه مبــا‬\n‫جــاء يف الدعــوى ((وألن املــرء مؤاخــذ بإقــراره)) فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بالشــروع يف ســرقة كيابــل مــن شــركة ال‪ .....‬الواقعــة‬\n‫علــى طريــق اخلــرج وحكمــت عليــه لقــاء ذلــك بســجنه أحــد عشــر‬\n‫شــهر ًا تبــدأ مــن تاريــخ اإليقــاف وجلــده مائتــي جلــدة مفرقــة علــى أربــع‬\n‫دفعــات أمــام النــاس كل دفعــة خمســون جلــدة وبــن كل دفعتني عشــرة‬\n‫أيــام وأوصــي بإبعــاده عــن البــاد بعــد تصفيــة مــا لــه وعليــه مــن حقــوق‬\n‫وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة واملدعــى العــام االعتــراض‬\n‫مكتفيــا بالئحــة الدعــوى وكان النطــق باحلكــم يف ‪1434/1/20‬ه ـ‬\n‫وأغلقــت اجللســة الســاعة العاشــرة وعليــه جــرى التوقيــع وصلــى اهلل علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                       ‫‪154‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعة‬\n      ‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقــم ‪ .....‬وتاريــخ ‪1434 /3/9‬ه ـ املرفــق‬\n      ‫بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ ‪ .......‬املســجل برقــم‬\n      ‫‪ ........‬وتاريــخ ‪1434/2/9‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪.........‬‬\n      ‫التهامــه بقضيــة ســرقة علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون بــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة قــررت الدائــرة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه أنــه‬\n      ‫البــد مــن ذكــر اســم املدعــي العــام يف أول الدعــوى ويالحــظ ذلــك‬\n      ‫ال ‪ .‬و اهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬   ‫مســتقب ً‬\n                                                                               ‫وســلم ‪.‬‬\n\n\n\n\n‫‪155‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":152,"source_page_end":155,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"00292527ddf0cb16dedc2d1908d34bc7705c2b74cb00583d11c0d870a2f4bf2d","normalized_text_hash":"eab7050e520e7630680c0f268ef01d983a522afde30e8752a3071939e99afc2a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p152-3433258"},{"id":"a3e809a4-0a19-5c29-889e-a8153299cd1b","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة أساك نحاسية -االشتراك يف سرقة أساك نحاسية -شرب املسكر -قيادة السيارة حتت تأثير املسكر -إقرار املدعى عليهما املصدق شرع ا -الرجوع عن اإلقرار بالسرقة واإلقرار بشرب املسكر -صرف النظر عن إقامة حد السرقة -التعزير بالسجن واجللد وأخذ التعهد.","document_number":"346374","case_number":"33595551","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/07","year":"1434","subject":"سرقة -سرقة أساك نحاسية -االشتراك يف سرقة أساك نحاسية -شرب املسكر -قيادة السيارة حتت تأثير املسكر -إقرار املدعى عليهما املصدق شرع ا -الرجوع عن اإلقرار بالسرقة واإلقرار بشرب املسكر -صرف النظر عن إقامة حد السرقة -التعزير بالسجن واجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 346374 :‬تاريخه ‪1434/01/07 :‬هـ‬\n                   ‫رقم الدعوى ‪33595551 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3456455‬تاريخه‪1434/03/07 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة أســاك نحاســية ‪ -‬االشــتراك يف ســرقة أســاك نحاســية‬\n‫‪ -‬شــرب املســكر ‪ -‬قيــادة الســيارة حتــت تأثيــر املســكر ‪ -‬إقــرار املدعــى‬\n‫عليهمــا املصــدق شــرع ًا ‪ -‬الرجــوع عــن اإلقــرار بالســرقة واإلقــرار بشــرب‬\n‫املســكر ‪ -‬صــرف النظــر عــن إقامــة حــد الســرقة ‪ -‬التعزيــر بالســجن‬\n                                                     ‫واجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n\n  ‫ما ذكره أهل العلم أن الرجوع عن اإلقرار شبهة يف إسقاط احلدود‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليهمــا باالشــتراك يف ســرقة أســاك‬\n‫نحاســية مــن مســتودع بعــد هتــك احلــرز و التســتر مــع شــريكهما و قيــادة‬\n‫األول الســيارة حتــت تأثيــر املســكر وهــو بحالــة غيــر طبيعيــة و اتهــام‬\n‫الثانــي باالشــتراك مــع آخــر يف ســرقة بالزمــا وجهــاز القــط مــن إحــدى‬\n‫االســتراحات‪ ،‬حيــث تقــدم أحــد األشــخاص ببــاغ للشــرطة يفيــد أن‬\n‫هنالك أربعة أشــخاص يســتقلون ســيارة قاموا بتكســير القفل اخلارجي‬\n‫للمســتودع وســرقة تســعة صناديــق أجهــزة كهربائيــة وعندمــا شــاهدوه‬\n‫هربــوا علــى الســيارة ‪ ،‬وطلــب املدعــي العــام إقامــة حــد الســرقة عليهما‪،‬‬\n‫وعقوبــة تعزيريــة لقــاء تســترهم علــى املشــاركني معهمــا‪ ،‬وإدانــة األول‬\n\n                                                                                   ‫‪156‬‬\n\f      ‫بقيــادة الســيارة حتــت تأثيــر املســكر و إفهامــه أن عقوبــة ذلــك عائــد‬\n      ‫للجهــة املختصــة‪ ،‬وقــد أنكــر املدعــى عليــه األول دعــوى املدعــي العــام‬\n      ‫واعتــرف بشــرب املســكر‪ ،‬والثانــي أنكــر مــا جــاء بدعــوى املدعــي‬\n      ‫العــام واعتــرف بشــرب املســكر فقــط‪ ،‬وعندمــا ُطلــب مــن املدعــي‬\n      ‫العــام بينتــه علــى دعــواه ذكــر إقــرار املدعــى عليهمــا املصــدق شــرع ًا‬\n      ‫واملتضمــن طبــق مــا جــاء بدعــوى املدعــي العــام و بســؤالهما عــن ذلــك‬\n      ‫دفعــا أن ذلــك كان باإلكــراه وال بينــة لهمــا علــى اإلكــراه ‪ ،‬لــذا مت‬\n      ‫احلكــم بصــرف النظــر عــن حــد الســرقة لعــدم حتقــق شــروطه ‪ ،‬وبجلــد‬\n      ‫املدعــى عليهمــا حــد املســكر ثمانــن جلــدة ‪ ،‬واحلكــم بإدانــة املدعــى‬\n      ‫عليــه األول بقيــادة ســيارة حتــت تأثيــر املســكر ‪ ،‬وإفهامــه أن عقابــه‬\n      ‫علــى ذلــك عائــد للجهــة املختصــة ‪ ،‬احلكــم بتعزيــر املدعــى عليهمــا‬\n      ‫بالســجن و اجللــد لقــاء توجــه الشــبهة بحقهمــا مبــا جــاء يف دعــوى املدعــي‬\n      ‫العــام‪ ،‬وقنــع املدعــى عليهمــا باحلكــم ‪ ،‬واملدعــي العــام قــرر اعتراضــه‬\n      ‫علــى احلكــم بــدون الئحــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن كل مــن ‪ .....‬و‪ ....‬و‪ .....‬القضــاة‬\n      ‫يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم ‪ .....‬وتاريــخ‬\n      ‫‪ .....‬املقيــدة باحملكمــة برقــم ‪ .....‬وتاريــخ ‪ ....‬ففــي يــوم اإلثنــن املوافق‪...‬‬\n      ‫افتتحــت اجللســة الســاعة ‪ 9.45‬قــدم املدعــي العــام بدائــرة التحقيــق‬\n      ‫واالدعــاء العــام ‪.....‬الئحتــه االدعائيــه ضــد كل مــن ‪ ....‬و‪.....‬واملتضمنــة‬\n      ‫مانصــه ‪.....‬إنــه بتاريــخ ‪ ....‬ورد ملركــز شــرطة امللــز تقريــر إحــدى دوريات‬\n\n‫‪157‬‬\n\f‫األمــن رقــم (‪ )....‬املتضمــن تلقيهــم بــاغ مــن غرفــة العمليــات مفــاده وجود‬\n‫ســرقة بحــي ‪ ...‬وبوصــول الفرقــة للموقــع قابلــت املبلــغ‪ .... /‬وقــد أفــاد‬\n‫الفرقــة أن أربعــة أشــخاص يســتقلون ســيارة نــوع ‪ ...‬حتمــل اللوحــة‬\n‫رقــم (‪ )....‬قامــوا بتكســير القفــل اخلارجــي للمســتودع وســرقة تســعة‬\n‫كراتــن أجهــزة كهربائيــة وعندمــا شــاهدوه هربــوا علــى الســيارة‪.‬‬\n‫ومبعاينــة املســتودع تبــن أنــه عبــارة عــن حاويــة بضائــع(‪ ).......‬بالقــرب‬\n‫مــن منــزل املبلــغ وبــه أســاك ووضــع علــى بابــه سالســل حديــد‪ .‬وبتاريــخ‬\n‫‪ .....‬حضــر ملركــز شــرطة ‪ .....‬املواطــن ‪ ....‬مخبــر ًا عــن ســرقة شاشــة‬\n‫بالزمــا (‪ )42‬بوصــة وجهــاز القــط مــن اســتراحته بحــي ‪ ......‬وباالنتقــال‬\n‫لالســتراحة اتضــح أنهــا مكونــة مــن ثــاث غــرف وقــد ســرق منهــا‬\n‫شاشــة بالزمــا‪ .‬وبتاريــخ ‪ ...26‬قبــض علــى املذكوريــن مــن قبــل وحــدة‬\n‫البحــث والتحــري وهمــا علــى الســيارة الــوارد أوصافهــا أعــاه‪ .‬وبســماع‬\n‫أقــوال املتهــم األول أقــر أنــه بتاريــخ ‪ ...‬بعــد منتصــف الليــل كان يرافقــه‬\n‫املتهــم الثانــي واملدعــو‪( ...‬فــرزت لــه أوراق مســتقلة حلــن القبــض عليــه)‬\n‫علــى ســيارته مــن نــوع ‪ ......‬وكانــا بحالــة غيــر طبيعيــة (ســكر) وأثنــاء‬\n‫جتولهــم بحــي ‪ .....‬شــاهدوا مســتودع واتفقــوا علــى ســرقته فقــام املتهــم‬\n‫الثانــي بتكســير البــاب اخلارجــي بواســطة عتلــة حديديــة ثــم دخــل‬\n‫املســتودع مــع‪ ...‬أمــا هــو فــكان بداخــل الســيارة ثــم خرجــا املتهــم الثانــي‬\n‫و‪....‬وهمــا يحمــان ثالثــة كراتــن بهــا أســاك كهربائيــة وأثنــاء ذلــك‬\n‫شــاهدوا صاحــب املســتودع فهربــوا ‪ ،‬ثــم قــام بإنــزال املســروقات بســيارة‬\n‫املتهــم الثانــي نــوع ‪ ......‬وصــادق علــى إقــراره شــرعاً‪ .‬وبســماع أقــوال‬\n‫املتهــم الثانــي أقــر أنــه بتاريــخ ‪ ....‬كان برفقــة املتهــم األول واملدعــو‪..../‬‬\n‫وكانــا بحالــة غيــر طبيعيــة علــى ســيارة املتهــم األول مــن نــوع ‪ ....‬الــوارد‬\n\n\n                                                                                        ‫‪158‬‬\n\f      ‫وصفهــا أعــاه وأثنــاء جتولهــم شــاهدوا مســتودع واتفقــوا علــى ســرقته‬\n      ‫فقــام‪ ..../‬بتكســير البــاب اخلارجــي بواســطة عتلــة حديديــة ثــم ســرقوا‬\n      ‫ثالثــة كراتــن بهــا أســاك كهربائيــة وعنــد مغادرتهــم شــاهدوا‬\n      ‫ســيارة تراقبهــم فرمــوا املســروقات بــأرض فضــاء بحــي ‪ ....‬أو ‪ .....‬وال‬\n      ‫يعلــم هــل عــاد لهــا املتهــم األول أم ال ‪ ،‬كمــا أقــر أنــه يف أحــد األيــام‬\n      ‫ورده اتصــال مــن‪ .../‬والــذي ميتهــن ســرقة االســتراحات وأخبــره بأنــه‬\n      ‫موجــود عنــد إحــدى االســتراحات بحــي ‪ .......‬فذهــب إليــه وعنــد وصولــه‬\n      ‫قــام ‪ ...‬بإخــراج شاشــه بالزمــا (‪ )42‬بوصــه مــن خلــف األشــجار ووضعهــا‬\n      ‫بســيارته ثــم ســأله عــن الشاشــة فأجابــه ‪ .... /‬بأنــه ســرقها مــن إحــدى‬\n      ‫االســتراحات يف ذلــك احلــي وصــادق علــى إقــراره شــرع ًا ‪ ،‬ويف إقــرا ٍر‬\n      ‫لــه ســابق أقــر أنــه هــو مــن قــام بكســر قفــل املســتودع‪ .‬جــرى عــرض‬\n      ‫املتهمــن علــى العامــل‪ ... /‬واســتطاع التعــرف علــى املتهــم الثانــي وأضــاف‬\n      ‫بأنــه هــو مــن حمــل املســروقات يف شــنطة الســيارة ‪ .....‬وبتفتيــش ســيارة‬\n      ‫املتهــم األول الــوارد وصفهــا أعــاه تبــن وجــود آثــار حتميــل وخــدوش‬\n      ‫علــى جانــب الشــنطة مــن الداخــل كمــا عثــر علــى قطــع صغيــرة مــن‬\n      ‫األســاك ممــا يؤكــد قيامــه بالســرقة‪ .‬بعــرض ســيارة املتهــم األول علــى‬\n      ‫املبلــغ األول‪ .....‬اســتطاع التعــرف عليهــا‪ .‬جــرى االنتقــال مــن قبــل إدارة‬\n      ‫التحريــات والبحــث اجلنائــي رفــق املتهمــن ومتكينهمــا مــن الداللــة علــى‬\n      ‫املوقعــن املســروقة حيــث قــام األول بالداللــة علــى موقــع املســتودع أمــا‬\n                                            ‫الثانــي فدلهــم علــى موقــع االســتراحة‪.‬‬\n      ‫وبالبحــث عــن ســوابقهما عثــر لــأول علــى ســابقة حيــازة واســتعمال‬\n      ‫املخــدرات وعثــر للثانــي علــى ســابقة ترويــج املخــدرات واســتعمالها‪ .‬وقــد‬\n      ‫أســفر التحقيــق عــن اتهامهمــا باالشــتراك يف ســرقة أســاك نحاســية‬\n\n\n‫‪159‬‬\n\f‫مــن مســتودع بعــد هتــك احلــرز بكســر قفله‪،‬والتســتر علــى شــريكيهما‬\n‫الهاربــن وشــرب املســكر وقيــادة األول الســيارة وهــو بحالــة غيــر‬\n‫طبيعيــة واتهــام الثانــي باالشــتراك مــع أخــر يف ســرقة شاشــة بالزمــا‬\n‫وجهــاز القــط مــن إحــدى االســتراحات وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪1‬ـ إقــرار األول املصــدق عليــه شــرع ًا املــدون علــى الصفحــة رقــم(‪)..‬‬\n‫مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )...‬وإقــراره حتقيقي ـ ًا املــدون‬\n‫علــى الصفحــة رقــم(‪ )...‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )...‬وعلــى‬\n              ‫الصفحــة رقــم(‪ )...‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪.)..‬‬\n‫‪ -2‬إقــرار املتهــم الثانــي املصــدق عليــه شــرع ًا املــدون علــى الصفحــة‬\n‫رقــم(‪ )...‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )..‬وعلــى الصفحــة رقــم(‪)..‬‬\n‫مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )..‬وإقــراره حتقيقي ـ ًا املــدون علــى‬\n‫الصفحــة رقــم(‪ )..‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )..‬وعلــى الصفحة‬\n                              ‫رقــم(‪ )..‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪.)..‬‬\n                                                   ‫‪3‬ـ ما ورد بتقرير دوريات األمن‪.‬‬\n‫‪4‬ـ محضــر تعــرف‪ .../‬علــى املتهــم الثانــي املــدون علــى الصفحــة رقــم(‪)..‬‬\n                                         ‫مــن ملــف التحقيــق املرفــق لفــة رقــم(‪.)..‬‬\n‫‪5‬ـ محضــر تفتيــش ســيارة املتهــم األول املــدون علــى الصفحــة رقــم(‪ )..‬مــن‬\n                                               ‫ملــف التحقيــق املرفــق لفة رقــم(‪.)..‬‬\n                                   ‫‪6‬ـ تناقض أقوالهم يف التصرف باملسروقات‪.‬‬\n                                       ‫‪ -7‬محضرا الداللة على موقعي السرقة‪.‬‬\n‫‪ -8‬محضــرا املعاينــة املدونــن علــى الصفحــة رقــم(‪ )..‬مــن ملفــي التحقيــق‬\n                                                               ‫املرفقــن لفة رقــم(‪.)...‬‬\n‫وحيــث أن مــا أقــدم عليــه املتهمــان فعــل محــرم ومعاقــب عليــه شــرعا‬\n\n\n                                                                                           ‫‪160‬‬\n\f      ‫وهــو ســرقة مــال محتــرم مــن حــرزه بعــد هتكــه ال شــبهة لهمــا فيــه‬\n      ‫وبلــغ النصــاب أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بحــد‬\n      ‫الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة واحلكــم‬\n      ‫عليهمــا بحــد املســكر واحلكــم عليهمــا بعقوبــة تعزيريــة تزجرهمــا‬\n      ‫وتــرع غيرهمــا وفق ـ ًا للمــادة(‪ )127‬مــن نظــام اإلجــراءات اجلزائيــة لقــاء‬\n      ‫تســترهما علــى الهاربــن والفصــل يف قيــادة املتهــم األول للســيارة وهــو‬\n      ‫حتــت تأثيــر املســكر مبوجــب الفقــرة (ثانيــا) مــن نظــام املــرور الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ (علمــا بــان‬\n      ‫احلــق اخلــاص مــازال قائمــا وقــد حضــر الســجينان ‪....‬مبوجــب بطاقــة‬\n      ‫نزيــل صــادرة مــن ســجن امللــز برقــم ‪ ....‬يف ‪ ....‬كمــا حضــر مــن‬\n      ‫اســمى نفســه‪ ....‬اليحمــل هويــه وبعــرض الدعــوى علــى املدعــى عليــه‬\n      ‫‪ ...‬قــال ماذكــره املدعــي العــام غيــر صحيــح والصحيــح اننــي قــد‬\n      ‫شــربت املســكر فقــط وماعــدا ذلــك فــا صحــة لــه وقــد ســلمت نفســي‬\n      ‫للشــرطة هكــذا أجــاب وقــد جــرى افهــام املدعــى عليــه ‪ ...‬باحضــار‬\n      ‫هويــة لــه يف اجللســه القادمــة فاســتعد بذلــك ورفعــت اجللســه لذلــك ويف‬\n      ‫يــوم اإلثنــن املوافــق ‪ ...‬افتتحــت اجللســة الســاعة ‪ 12.37‬وحضــر‬\n      ‫الســجني ‪ ...‬والســجني ‪ ...‬مبوجــب بطاقــة نزيــل ‪ ....‬والصــادر مــن‬\n      ‫شــرطة امللــز يف ‪ ...‬وبعــرض الدعــوى عليــه اجــاب ‪ ...‬قائــا ماذكــره‬\n      ‫املدعــي العــام غيــر صحيــح والصحيــح اننــي كنــت مــع ‪ ....‬وكنــت‬\n      ‫ســكرانا وعلــي هــو مــن قــام بالســرقة وامــا انــا فنزلــت مــن الســيارة ثــم‬\n      ‫ركبتهــا ولــم اســرق شــيء هكــذا اجــاب وبســؤال املدعــي العــام عــن‬\n             ‫البينــه قــال ماتضمنتــه اوراق املعاملــة واطلــب اطالعكــم عليهــا‬\n      ‫ويف يــوم اإلثنــن املوافق‪.....‬افتتحــت اجللســة الســاعة‪ 10.00‬ومبشــاركة‬\n\n\n‫‪161‬‬\n\f‫فضيلــة الشــيخ ‪ ....‬حيــث باشــر بعــد دورتــه التدريبيــة بــدال عــن ‪.....‬‬\n‫وباالطــاع علــى املعاملــة وجدناهــا تتضمــن ضمن طياتها ملف التحقيق‬\n‫وقــد تضمــن يف الصحيفــة رقــم ‪ ...‬اقــرارا مصدقــا شــرعا تضمــن مانصه‬\n‫أقــر أنــا ‪ ....‬مــن دون جبــر أو إكــراه باننــي قمــت بتاريــخ ‪ ...‬وبعــد‬\n‫منتصــف الليــل بالذهــاب رفــق ‪ ....‬و‪....‬الــى حــي امللــز علــى الســيارة‬\n‫العائــدة لــي ونحــن بحالــه غيــر طبيعيــه ســكر وأثنــاء جتولنــا شــاهدنا‬\n‫مســتودع واتفقنــا علــى ســرقته وقــام ‪ ....‬بتكســير البــاب اخلارجــي‬\n‫بواســط عتلــة حديديــه حتــى نتمكــن مــن الدخــول رفــق ‪ ...‬وأنــا أمــام‬\n‫مقــود الســيارة وقامــوا بســرقة عــدد ثــاث كراتــن مليئــه باســاك‬\n‫كهربائيــه وبعدهــا متــت مشــاهدتنا ومطاردتنــا مــن قبــل صاحــب‬\n‫املســتودع وارتكبــت الفــرار وبعدهــا قمــت بإنــزال املســروقات بســيارة‬\n‫‪ ..‬وهــي مــن نــوع فــورد ولــم يكــن لــي نصيــب مــن تلــك املســروقات‬\n‫كمــا جــرى االطــاع علــى ملــف اســتكمال محاضــر االســتدالل وقــد‬\n‫تضمــن بالصحيفــة‪ ..‬أثنــاء اســتجواب املدعــى عليــه ‪..‬مــن قبــل احملقــق‬\n‫عــن ســبب القبــض عليــه حيــث أجــاب قائــا بســبب قيامــي أنــا وزمالئــي‬\n‫‪....‬و‪ ....‬بســرقة عــدد ثــاث كراتــن مــن احــدى املســتودعات بحــي امللــز‬\n‫وقــد تضمنــت إجابتــه أن املســروقات ‪ 3‬كراتــن أســاك كهربائيــه‬\n‫وقــد أفــاد أنــه أثنــاء الســرقة لــم يكــن بحالــة طبيعيــه وعلــى هــذه‬\n‫االفــادات بصمــة منســوبة إليــه كمــا جــرى االطــاع علــى ملــف‬\n‫التحقيــق مــن الصحيفــة رقــم ‪ 3‬مــن ملــف التحقيــق وقــد اشــتملت علــى‬\n‫إقــرار مصــدق شــرعا للمدعــى عليــه ‪ ...‬تضمــن مانصــه أقــر أنــا ‪...‬‬\n‫بطوعــي واختيــاري بانــه ورد اتصــال علــى جوالــي مــن احــد رفاقــي‬\n‫ويدعــى ‪ ...‬والــذي ميتهــن ســرقة االســتراحات واخبرنــي انــه متواجد عند‬\n\n\n                                                                                ‫‪162‬‬\n\f      ‫إحــدى االســتراحات بحــي ‪ ..........‬وقمــت بالذهــاب إليــه وعنــد وصولــي‬\n      ‫إليــه قــام بإخــراج شاشــة بالزمــا مــن خلــف إحــدى األشــجار ووضعهــا‬\n      ‫معــي يف ســيارتي وعنــد ســؤال عــن تلــك الشاشــة أخبرنــي بأنــه قــام‬\n      ‫بســرقتها مــن اســتراحة مــن ذلــك احلــي وهــذا إقــرار منــي بذلــك كمــا‬\n      ‫تضمــن ملــف التحقيــق يف الصحيفــة رقــم (‪ )3‬وقــد تضمــن إقــرار لــ‪....‬‬\n      ‫تضمــن أقــر أنــا ‪ ...‬بطوعــي واختيــاري باننــي رفــق زمالئــي ‪ ...‬و‪ ...‬بتاريــخ‬\n      ‫‪ ...‬كنــا بحالــة ســكر وكنــت برفقــة زمالئــي علــى ســيارة تعــود لــ‪.....‬‬\n      ‫وأثنــاء جتولنــا بحــي ‪ .....‬شــاهدنا مســتودع واتفقنــا علــى ســرقته وقــام ‪...‬‬\n      ‫بتكســير البــاب اخلارجــي بواســطة عتلــة حتــى متكنــا مــن ســرقة ثالثــة‬\n      ‫كراتــن أســاك وعندمــا غادرنــا املوقــع شــاهدنا ســيارة تراقبنــا وقمنــا‬\n      ‫برمــي املســروقات بــأرض فضــاء بحــي ‪ ....‬أو ‪ ......‬ال اعلــم بالتحديــد هــذا‬\n      ‫إقــراري بطوعــي واختيــاري وهــو مصــدق شــرع ًا كمــا جــرى االطــاع‬\n      ‫علــى محضــر عــرض مــؤرخ يف ‪ ....‬حيــث مت عــرض املدعــى عليهمــا علــى‬\n      ‫‪.....‬يف مركــز الشــرطة بصفتــه احــد العمالــة الذيــن شــاهدوا اجلنــاه وقــد‬\n      ‫تضمــن احملضــر انــه اســتطاع التعــرف علــى املدعــى عليــه الثانــي ‪....‬‬\n      ‫واكــد انــه مــن قــام بتحميــل املســروقات بشــنطة الســيارة ‪ .....‬وذلــك‬\n      ‫بنســبة مائــة باملائــة وقــد دون ذلــك احملضــر علــى الصحيفــة رقــم ‪ ...‬مــن‬\n      ‫ملــف التحقيــق كمــا جــرى االطــاع علــى الصحيفــة رقــم ‪ ....‬مــن ذات‬\n      ‫امللــف وقــد تضمنــت محضــر تفتيــش مــؤرخ يف ‪ ....‬وقــد تضمــن انــه جــرى‬\n      ‫مــن قبــل احملقــق تفتيــش الســيارة ‪ ......‬ولــم يتــم العثور علــى أي ممنوعات‬\n      ‫أو محرمــات داخــل الســيارة وبتفتيــش شــنطة الســيارة جــرى مالحظــة‬\n      ‫وجــود آثــار حتميــل وخــدوش مــن الشــنطة مــن الداخــل ممــا يــدل علــى‬\n      ‫حتميلهــا باملســروقات كذلــك عثــر علــى قطــع صغيــره مــن األســاك‬\n\n\n‫‪163‬‬\n\f‫داخــل شــنطة الســيارة ممــا يوكــد قيامهــم بالســرقة وبعــرض ذلــك علــى‬\n‫املدعــى عليهمــا قــاال إمنــا ذكرنــاه هــو الصحيــح وماعــدا ذلــك فــا‬\n‫صحــة لــه وهــذه اإلقــرارات أخــذت منــا عــن طريــق اإلكــراه عــن طريــق‬\n‫احملققــن وال بينــة لدينــا علــى اإلكــراه بســؤال املدعــي العــام هــل لديــه‬\n‫مزيــد بينــه قــال ليــس لــدي ســوى ماتضمنتــه أوراق املعاملــة ورفعــت‬\n‫اجللســة النتهــاء الوقــت احملــدد لهــا ويف يــوم اإلثنــن املوافق‪....‬افتتحــت‬\n‫اجللســة الســاعة ‪ 12.38‬وفيهــا حضــر املدعــي العــام والســجينان‬\n‫املدعــى عليهمــا وجــرى ســؤال الســجيينني عــن ســوابقهما فقال املدعى‬\n‫عليــه ‪ ....‬ان لــدي ســابقة اســتعمال مخــدرات وقــال املدعــى عليــه ‪ ...‬ان‬\n‫لــدي ســابقة حيــازة مخــدرات بقصــد االســتعمال فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ومبــا ان املدعــى عليهمــا انكــرا مــا نســب إليهمــا‬\n‫مــن القيــام بالســرقة وأقــرا بتعاطــي املســكر وملــا تضمنــه إقــرار همــا‬\n‫املصــدق شــرعا ومبــا أن الرجــوع عــن اإلقــرار شــبه يف إســقاط احلــدود‬\n‫وملــا تقــدم جميعــه فقــد قررنــا مايلــي أوال صرفنــا النظــر عــن دعــوى‬\n‫املدعــي العــام إقامــة حــد الســرقة ضــد املدعــى عليهمــا لعــدم حتقــق‬\n‫شــرطه ثانيــا إقامــة حــد املســكر علــى املدعــى عليهمــا وذلــك بجلــد‬\n‫كل واحــد منهمــا ثمانــن جلــدة دفعــة واحــده ثالثــا ثبــت لدينــا قيــام‬\n‫املدعــى عليــه ‪ ....‬بقيــادة الســيارة وهــو حتــت تأثيــر املســكر وأفهمنــاه‬\n‫بــان عقوبــة ذلــك راجــع للجهــة املختصــة رابعــا تعزيــر املدعــى عليهمــا‬\n‫بســجن كل واحــد منهمــا ثــاث ســنوات ونصــف مــن تاريــخ إيقــاف‬\n‫كل واحــد منهمــا وجلــد كل واحــد منهمــا ثالثمائــة وخمســن جلــده‬\n‫مفرقــه علــى فتــرات كل مــره خمســون جلــده بــن كل مــره وأخــرى‬\n‫مــا ال يقــل عــن أســبوعني خامسـ ًا أخــذ التعهــد عليهمــا بالتوبــة إلــى اهلل‬\n\n\n                                                                                     ‫‪164‬‬\n\f      ‫وعــدم العــودة ملــا بــدر منهمــا وبذلــك حكمنــا وبعــرض احلكــم علــى‬\n      ‫املدعــى عليهمــا واملدعــي العــام قــرر املدعــي العــام عــدم القناعــة وطلــب‬\n      ‫االســتئناف بــدون الئحــه كمــا قــرر املدعــى عليهمــا القناعــة وامرنــا‬\n      ‫بتنظيــم القــرار الــازم ورفعــه حملكمــة االســتئناف لتدقيقــه وصلــى‬\n      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف الســاعة‬\n                         ‫‪ 12.47‬مــن يــوم االثنــن املوافــق ‪ ....‬ه ـ وبــاهلل التوفيــق‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافق‪....‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 01 : 45‬وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف بخطــاب‬\n      ‫رئيســها رقــم ‪ ....‬يف ‪ ....‬وقــد صــدر فيهــا قــرار الدائــرة الثانيــة لتمييــز‬\n      ‫القضايــا اخلماســية رقــم ‪ ....‬يف ‪ ......‬واملتضمــن مــا نصــه‪ :‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫وأمــرت بإحلــاق ذلــك بالضبــط وســجل القــرار وصلــى اهلل علــى نبينــا‬\n                                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ ....‬ه ـ‬\n\n\n\n\n‫‪165‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":156,"source_page_end":165,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6dc578ed452c4f26ea85157d1c1f863646a7127cf1249a567aeda615e7eb8ee7","normalized_text_hash":"6013c6dbea7725bd4aafb04c427aac658612c551f377a2729cf61a2370a2025e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p156-346374"},{"id":"b0af3d0a-0df1-51a8-b6ff-b91a068c4437","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -استغالل العمل يف السرقة -حتريف أرقام هياكل السيارات -بيع سيارات مسروقة -مقاومة قوات الشرطة - مسكر -حيازة مسكر بقصد الشرب -رجوع عن إقرار مصدق شرع ا -تستر على أحد اجلناة -إحضار بينة على دعوى إكراه بانتزاع اإلقرار -األخذ بالقرائن على انتزاع اإلقرار باإلكراه -التعزير بالسجن واجللد.","document_number":"3444627","case_number":"33600835","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"سرقة -سرقة سيارة -استغالل العمل يف السرقة -حتريف أرقام هياكل السيارات -بيع سيارات مسروقة -مقاومة قوات الشرطة - مسكر -حيازة مسكر بقصد الشرب -رجوع عن إقرار مصدق شرع ا -تستر على أحد اجلناة -إحضار بينة على دعوى إكراه بانتزاع اإلقرار -األخذ بالقرائن على انتزاع اإلقرار باإلكراه -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك ‪ 3444627:‬تاريخه ‪1434/2/23:‬هـ‬\n                   ‫رقم الدعوى ‪33600835 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34240378‬تاريخه‪1434/06/13 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬اســتغالل العمــل يف الســرقة ‪ -‬حتريــف أرقــام‬\n‫هيــاكل الســيارات ‪ -‬بيــع ســيارات مســروقة ‪ -‬مقاومــة قــوات الشــرطة ‪-‬‬\n‫مســكر ‪ -‬حيــازة مســكر بقصــد الشــرب ‪ -‬رجــوع عــن إقــرار مصــدق شــرع ًا‬\n‫‪ -‬تســتر علــى أحــد اجلنــاة ‪ -‬إحضــار بينــة علــى دعــوى إكــراه بانتــزاع‬\n‫اإلقــرار ‪ -‬األخــذ بالقرائــن علــى انتــزاع اإلقــرار باإلكــراه ‪ -‬التعزيــر‬\n                                                         ‫بالســجن واجللــد‪.‬‬\n\n\n\n\n‫مــا قــرره الفقهــاء مــن أن الســجن حــال التحقيــق وســيلة مــن وســائل‬\n                                                             ‫اإلكــراه‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه باالشــتراك مــع شــخص هــارب يف‬\n‫تكويــن عصابــة لســرقة الســيارات وأجزائهــا وتصريــف املســروقات‪،‬‬\n‫وقيامــه بســرقة عــدد مــن الســيارات واســتغالل عملــه يف الورشــة التــي‬\n‫يعمــل بهــا ثــم إحضــار الســيارات للورشــة وحتريــف أرقــام هياكلهــا‬\n‫وتركيبهــا علــى ســيارات أخــرى وبيعهــا وأكل ثمنهــا وحيــازة املســكر‬\n‫بقصــد التعاطــي والهــروب مــن الفرقــة القابضــة وتســتر الثانــي علــى‬\n‫األول ممــا جعــل املدعــى عليــه يــوكل يف أعمالــه اإلجراميــة ‪ ،‬وطلــب‬\n\n                                                                                 ‫‪166‬‬\n\f      ‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪،‬‬\n      ‫مت القبــض علــى املدعــى عليــه بعــد ورود بالغــات بســرقة ســيارات وبعــد‬\n      ‫البحــث والتحــري مت القبــض علــى املدعــى عليــه حيــث توجهت لــه التهمة‬\n      ‫باالشــتراك يف تكويــن عصابــة الســرقة وباســتجوابه اعتــرف مبــا نســب‬\n      ‫لــه‪ ،‬أنكــر املدعــى عليــه الدعــوى‪ ،‬تبــن وجــود إقــرار للمدعــى عليــه‬\n      ‫مصــدق شــرعاً‪ ،‬ادعــى املدعــى عليــه بــان إقــراره انتــزع منــه باإلكــراه‪،‬‬\n      ‫كمــا أحضــر شــاهدين علــى انتزاع اإلقــرار باإلكراه‪ ،‬األخــذ بالقرائن‬\n      ‫علــى انتــزاع اإلقــرار باإلكــراه ‪ ،‬توجيه التهمــة للمدعى عليه‪ ،‬حكمت‬\n      ‫احملكمــة تعزيــر املدعــى عليــه بالســجن واجللــد‪ ،‬وتوجيــه املدعــي العــام‬\n      ‫بإحضــار املدعــى عليــه الهــارب‪ ،‬ومت تصديــق احلكــم مــن محكمــة‬\n                                                                          ‫االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقــم ‪ .......‬وتاريــخ ‪ 1433/10/14‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ ..........‬وتاريــخ ‪ 1433/10/14‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1433/10/18‬ه ـ افتتحــت اجللســة الســاعة ‪02 : 00‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ .....‬وادعــى بقولــه بصف ــتي مدعي ـ ًا عام ـ ًا يف‬\n                             ‫دائ ــرة االدع ــاء الع ــام مبدينــة الريــاض أدع ــي علــى ‪:‬‬\n      ‫‪-1‬الوافــد ‪ 38 ........... /‬ســنة ســوري اجلنســية مبوجــب رخصــة االقامــة‬\n      ‫رقــم (‪ ).......‬اوقــف بتاريــخ ‪1433/3/1‬ه ـ واحيــل الــى الســجن العــام‬\n      ‫مبوجــب امــر االيقــاف رقــم ‪ .......‬وتاريــخ ‪1433/3/19‬ه ـ اســتنادا للبنــد‬\n‫‪167‬‬\n\f‫خامســا مــن القــرار الــوزاري رقــم ‪ 1900‬وتاريــخ ‪1428/7/9‬ه ـ وقيــد‬\n                                                       ‫ســجينا برقــم (‪. ).............‬‬\n‫‪ 51 ............-2‬ســنة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n                                          ‫(‪ )...........‬مفــرج عنــه بالكفالــة ‪.‬‬\n‫انــه بتاريــخ ‪1433/3/1‬ه ـ قبــض علــى املدعــى عليــه االول مــن قبــل ادارة‬\n‫التحريــات والبحــث اجلنائــي وبتاريــخ ‪1433/1/15‬ه ـ قبــض علــى الثانــي‬\n‫بعــد ورود عــدة بالغــات ملراكــز الشــرط عــن ســرقة مجموعــة كبيــرة‬\n                                                        ‫مــن الســيارات كالتالــي ‪:‬‬\n‫‪ -1‬تقــدم املواطــن ‪ ......... /‬ببــاغ لــدى مركــز شــرطة العليــا بتاريــخ‬\n‫‪1432/11/25‬ه ـ عــن تعــرض الســيارة العائــدة ملكيتهــا لشــركة‬\n‫‪ ............‬لتأجيــر الســيارات للســرقة نــوع ‪ .....‬اللــون فضــي ســنة صنعهــا‬\n                                   ‫‪2011‬م لوحــة رقــم(‪ )......‬وهــي مقفلــه ‪.‬‬\n‫‪-2‬وورد بــاغ الوافــد ‪ 29 .... ....... /‬ســنة امريكــي اجلنســية مبوجــب‬\n‫رخصــة االقامــة رقــم (‪ ).......‬لــدى مركــز شــرطة املعــذر بتاريــخ‬\n‫‪1433/1/3‬ه ـ عــن تعــرض ســيارته نــوع ‪ ....‬اللــون ابيــض ســنة صنعهــا‬\n                     ‫‪2011‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-3‬وورد بــاغ الوافــد ‪ 30 ......... /‬ســنة مصــري اجلنســية مبوجــب‬\n‫رخصــة االقامــة رقــم (‪ )............‬لــدى مركــز شــرطة البطحــاء بتاريــخ‬\n‫‪1433/1/10‬ه ـ عــن تعــرض الســيارة العائــدة ملكيتهــا ملؤسســة ‪....‬‬\n‫لتأجيــر الســيارات نــوع ‪ .....‬اللــون ابيــض ســنة صنعهــا ‪2010‬م لوحــة رقــم‬\n                                                ‫(‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-4‬وورد بــاغ منــدوب شــركة ال‪ ....‬لتأجيــر الســيارات لــدى مركــز‬\n‫شــرطة امللــز عــن تعــرض الســيارة نــوع ‪ .....‬اللــون فضــي ســنة صنعهــا‬\n\n\n                                                                                          ‫‪168‬‬\n\f                               ‫‪2005‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-5‬وورد بــاغ منــدوب الشــركة ال‪ ....‬للبيــع بالتقســيط لــدى مركــز‬\n      ‫شــرطة النســيم عــن تعــرض الســيارة نــوع ‪ ......‬اللــون ازرق فــاحت ســنة‬\n                    ‫صنعهــا ‪2007‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-6‬وورد بــاغ منــدوب شــركة ال‪ ....‬لتأجيــر الســيارات لــدى شــرطة‬\n      ‫مطــار امللــك خالــد عــن تعــرض الســيارة نــوع ‪ .....‬اللــون اخضــر ســنة‬\n                   ‫صنعهــا ‪2009‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-7‬وورد بــاغ منــدوب شــركة ال‪ .......‬لالســتثمار لــدى شــرطة منطقــة‬\n      ‫حائــل ‪ /‬مركــز شــرطة عــن تعــرض الســيارة نــوع ‪ .....‬اللــون ابيــض ســنة‬\n                       ‫صنعهــا ‪2008‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-8‬وورد بــاغ ‪ 63...........‬ســنة ســعودي لــدى شــرطة محافظــة جــدة‬\n      ‫مركــز شــرطة جــدة اجلديــد عــن تعــرض ســيارته نــوع ‪ ....‬اللــون ابيــض‬\n            ‫ســنة صنعهــا ‪2010‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-9‬وورد بــاغ منــدوب الشــركة ال‪ ....‬للبيــع للتقســيط لــدى مركــز‬\n      ‫شــرطة امللــز عــن تعــرض الســيارة نــوع ‪ ....‬اللــون ابيــض ســنة صنعهــا‬\n                              ‫‪2010‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-10‬وورد بــاغ منــدوب الشــركة ال‪ ....‬الدوليــة للمواصــات لــدى‬\n      ‫مركــز شــرطة املربــع عــن تعــرض الســيارة نــوع ‪ .....‬اللــون ازرق ســنة‬\n                    ‫صنعهــا ‪2009‬م لوحــة رقــم (‪ )... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-11‬وورد بــاغ منــدوب شــركة ال‪ ....‬املصرفيــة لالســتثمار لــدى مركز‬\n      ‫شــرطة النســيم عــن تعــرض الســيارة نــوع ‪ .....‬اللــون اســود ســنة صنعهــا‬\n                                  ‫‪2011‬م لوحــة رقــم (‪ )... ....‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-12‬وورد بــاغ منــدوب الشــركة ال‪ ....‬للبيــع بالتقســيط لــدى مركــز‬\n\n\n‫‪169‬‬\n\f‫شــرطة الروضــة عــن تعــرض الســيارة نــوع ‪.....‬اللــون ازرق ســنة صنعهــا‬\n                         ‫‪2010‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-13‬وورد بــاغ منــدوب ‪ ..........‬للبيــع بالتقســيط لــدى مركــز شــركة‬\n‫النســيم عــن تعــرض الســيارة نــوع ‪.....‬اللــون فضــي ســنة صنعهــا ‪2008‬م‬\n                                   ‫لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-14‬وورد بــاغ منــدوب الشــركة ‪ ..........‬للبيــع بالتقســيط لــدى مركــز‬\n‫شــرطة محافظــة جــدة مركــز شــرطة الصفــا عــن تعــرض الســيارة نــوع‬\n‫‪.....‬اللــون فضــي ســنة صنعهــا ‪2011‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي‬\n                                                                           ‫مقفلــه ‪.‬‬\n‫‪-15‬وورد بــاغ منــدوب شــركة ‪ .......‬لــدى مركــز شــرطة امللــز مــن‬\n‫تعــرض الســيارة نــوع ‪ .....‬اللــون ابيــض ســنة صنعهــا ‪2010‬م لوحــة رقــم‬\n                                                 ‫(‪ ).... ...‬للســرقة وهــي مقفلــه‬\n‫‪-16‬وورد بــاغ ‪ 28 ......‬ســنة ســعودي اجلنســية لــدى مركــز شــرطة‬\n‫النســيم بتاريــخ ‪1432/8/27‬ه ـ عــن تعــرض ســيارته نــوع ‪.....‬اللــون ابيض‬\n           ‫ســنة صنعهــا ‪2011‬م لوحــة رقــم (‪ ).......‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-17‬وورد بــاغ ‪ 43 .......‬ســنة ســعودي اجلنســية لــدى مركــز شــرطة‬\n‫النســيم عــن تعــرض الســيارة املســتأجرة مــن شــركة ‪ ............‬لتأجيــر‬\n‫الســيارات نــوع ‪.....‬اللــون ابيــض ســنة صنعهــا ‪2010‬م لوحــة رقــم (‪).......‬‬\n                                                         ‫للســرقة وهــي مقفلــه ‪.‬‬\n‫عليــه مت اتخــاذ جملــة مــن االجــراءات البحثيــة بالتنســيق مــع فــرق‬\n‫دوريــات األمــن الســرية واخضــاع الــورش يف الصناعيــة وأماكــن‬\n‫التشــاليح للمراقبــة ومالحظــة املتردديــن عليهــا حيــث توفــرت معلومــات‬\n‫لــدى دوريــات االمــن الســرية عــن وجــود أشــخاص ميتهنــون تلــك الســرقات‬\n\n\n                                                                                       ‫‪170‬‬\n\f      ‫ويتــرددون علــى ورشــة ‪ .......‬بصناعيــة النســيم وبإخضاعهــا للمراقبــة‬\n      ‫والرصــد مت مشــاهدة وافديــن أحدهمــا ارتكــب الفــرار بعــد مشــاهدته‬\n      ‫للفرقــة والثانــي يدعــى ‪ 32 ....‬ســنة ســوري اجلنســية إقامــة رقــم (‪).....‬‬\n      ‫(مت حفــظ االتهــام بحقــه مــن قبــل جهــة التحقيــق لعــدم كفايــة االدلــة‬\n      ‫بحقــه وفقـ ًا للمــادة ‪ 124‬مــن نظــام االجــراءات) وبتاريــخ ‪1433/1/13‬ه ـ‬\n      ‫مت االنتقــال للورشــة وضبــط بداخلهــا علــى ثــاث ســيارات مختلفــة‬\n      ‫االنــواع منزوعــة الهيــاكل واتضــح بعــد االستفســار عنهــا أنهــا مســروقة‬\n      ‫واملوضــح معلوماتهــا يف البــاغ رقــم (‪ 1‬ـ ـ ‪ 2‬ـ ـ ‪ )3‬كمــا عثــر علــى ثــاث‬\n      ‫هيــاكل ســيارات منزوعــة االرقــام ودون لوحــات وســاح نــاري نــوع‬\n      ‫مســدس يحمــل الرقــم (‪ ).....‬وعــدد (‪ )55‬طلقــة حيــة (فــرزت لــه اوراق‬\n      ‫واحيلــت الــى اجلهــة املختصــة) وعــدد اربــع عشــرة اســتمارة لســيارات‬\n      ‫متنوعــة وتســع عشــرة لوحــة لســيارات متنوعــة وجهــاز لســبك هيــاكل‬\n      ‫الســيارات وجهــاز برمجــة ســيارات وزجاجتــي مســكر مصنــع خارجيـ ًا‬\n      ‫بهــا النصــف مــن املــادة املســكرة وعــدة مفاتيــح لســيارات مختلفــة‬\n      ‫وثالثــة وثالثــون شــريحة هيــكل معدنيــة اتضــح ان عــدد منهــا عائــدة‬\n      ‫لســيارات مســروقة واملوضــح معلوماتهــا يف ســياق البــاغ رقــم (‪ 4‬حتــى‬\n      ‫‪ )17‬وبالبحــث والتحــري عــن مــن لــه عالقــة باملتهمــن اســفرت اجلهــود‬\n                                                        ‫عــن القبــض علــى كال مــن ‪:‬‬\n                                 ‫‪ 21 .......-1‬سنة سوري اجلنسية اقامة رقم (‪. ).......‬‬\n                                 ‫‪ 53 .......-2‬سنة سوري اجلنسية اقامة رقم (‪. ).......‬‬\n                               ‫‪ 41 .......-3‬سنة مصري اجلنسية اقامة رقم (‪. ).......‬‬\n      ‫(مت حفــظ االتهــام بحقهــم مــن قبــل جهــة التحقيــق لعــدم كفايــة االدلــة‬\n                         ‫اســتنادا للمــادة (‪ )124‬مــن نظــام االجــراءات اجلزائيــة) ‪.‬‬\n\n\n‫‪171‬‬\n\f‫وباســتجواب االول ‪ ......... /‬يعمــل حتــت كفالــة الثانــي ‪ ...... /‬اعتــرف‬\n                                                              ‫علــى النحــو التالــي ‪:‬‬\n‫‪-1‬انــه قبــل ســنتني تقريبــا مــن تاريــخ القبــض عليــه حضــر لــه زبــون يف‬\n‫الورشــة التــي يعمــل بهــا وبقيادتــه ســيارة نــوع ‪.....‬لونهــا ابيــض موديــل‬\n‫‪2008‬م ال يذكــر رقــم لوحتهــا وكان بهــا عطــل ميكانيكــي وطلــب‬\n‫منــه ان يحضــر بعــد يومــن الســتالمها وقــام بتركيــب جهــاز تتبــع عليهــا‬\n‫وبعدمــا اســتلم الزبــون ســيارته حــدد موقعهــا وكلــف ‪( .......‬فــرزت لــه‬\n‫اوراق للقبــض عليــه) بإحضارهــا وبالفعــل احضرهــا ودفــع لــه مقابــل‬\n‫ذلــك مبلــغ ســبعة االف ريــال وقــام بقــص رقــم هيكلهــا واخــراج منهــا‬\n‫املاكينــة والقيــر وباقــي الســيارة ظلــت يف الورشــة الــى ان مت القبــض‬\n                                                                               ‫عليــه ‪.‬‬\n‫‪-2‬قبــل ســنة تقريبــا مــن تاريــخ القبــض عليــه احضــر لــه ‪ .....‬ســيارة‬\n‫مســروقة نــوع ‪ .....‬لونهــا اســود موديــل ‪2011‬م ال يذكــر رقــم لوحتهــا ولــم‬\n‫يخبــره مــن ايــن او كيــف ســرقها واخذهــا منــه ودفــع مبلــغ مالــي وقــدره‬\n              ‫ســتة االف ريــال وقــام بقــص الســيارة وبيعهــا كقطــع غيــار ‪.‬‬\n‫‪-3‬وبعــد ذلــك بشــهرين تقريبــا احضــر لــه ‪ ......‬ســيارة مســروقة نــوع ‪.....‬‬\n‫ازرق فــاحت موديــل ‪2010‬م ال يذكــر رقــم لوحتهــا ولــم يخبــره مــن ايــن او‬\n‫كيــف ســرقها واحضــر معــه هيــكل وطلــب منــه تغييــر رقــم هيــكل‬\n‫هــذه الســيارة وتركيــب الهيــكل الــذي معــه مكانــه واعطــاه مقابــل‬\n‫ذلــك مبلــغ مالــي وقــدره الــف ريــال ثــم اخــذ الســيارة وذهــب بهــا وال يعلــم‬\n                                                             ‫مصيرهــا بعــد ذلــك ‪.‬‬\n‫‪-4‬بعــد ذلــك بثالثــة اشــهر تقريبــا احضــر لــه ‪ ......‬ســيارة نــوع ‪ .....‬لونهــا‬\n‫فضــي موديــل ‪2008‬م ال يذكــر رقــم لوحتهــا اخبــره انهــا لشــخص‬\n\n\n                                                                                          ‫‪172‬‬\n\f      ‫اخذهــا مــن شــركة ‪ .....‬بنظــام التأجيــر املنتهــي بالتمليــك وعليــه‬\n      ‫اقســاط متأخــرة ويرغــب يف التخلــص منهــا فأخذهــا منــه مقابــل مبلــغ‬\n      ‫وقــدره ثمانيــة االف ريــال ثــم قــام بقــص الســيارة وبيعهــا كقطــع غيــار ‪.‬‬\n      ‫‪-5‬يف ثالــث ايــام عيــد الفطــر لعــام ‪1432‬ه ـ احضــر لــه ‪ ......‬ســيارة‬\n      ‫مســروقة نــوع ‪ .....‬لونهــا فضــي موديــل ‪2011‬م ال يذكــر رقــم لوحتهــا‬\n      ‫ولــم يخبــره مــن ايــن او كيــف ســرقها وطلــب منــه نــزع رقــم هيكلهــا‬\n      ‫وقــام بذلــك مقابــل مبلــغ وقــدره الــف ريــال ثــم ذهــب بالســيارة وال يعلــم‬\n                                                                   ‫مصيرهــا بعــد ذلــك ‪.‬‬\n      ‫‪-6‬بعــد ذلــك بأســبوعني تقريبــا احضــر لــه ‪ ......‬ســيارة مســروقة نــوع ‪.....‬‬\n      ‫لونهــا ابيــض موديــل ‪2011‬م ال يعــرف مــن ايــن او كيــف ســرقها واخذها‬\n      ‫منــه مقابــل مبلــغ مالــي وقــدره عشــرة االف ريــال وكان يوجــد لديــه‬\n      ‫ســيارة مصدومــة اشــتراها مــن التشــليح مطابقــة ملواصفاتهــا فقــام بقــص‬\n      ‫رقــم الهيــكل الســيارة املصدومــة وتركيبــه مــكان هيــكل الســيارة‬\n                                                             ‫املســروقة ثــم قــام ببيعهــا ‪.‬‬\n      ‫‪-7‬يف نهايــة شــهر شــوال لعــام ‪1432‬ه ـ احضــر لــه ‪ ......‬ســيارة نــوع ‪.....‬‬\n      ‫لونهــا ابيــض موديــل ‪2010‬م ال يذكــر رقــم لوحتهــا وطلــب منــه تغييــر‬\n      ‫رقــم هيكلهــا وقــام بذلــك مقابــل مبلــغ الــف ريــال ثــم ذهــب بالســيارة وال‬\n                                                            ‫يعلــم مصيرهــا بعــد ذلــك ‪.‬‬\n      ‫‪-8‬بعــد ذلــك بعشــرة ايــام تقريبــا احضــر لــه ‪ ......‬ســيارة مســروقة نــوع‬\n      ‫‪ .....‬لونهــا ازرق فــاحت موديــل ‪2009‬م ال يذكــر رقــم لوحتهــا ولــم يخبــره‬\n      ‫مــن ايــن او كيــف ســرقها وطلــب منــه تغييــر رقــم هيكلهــا فقــام بذلــك‬\n      ‫مقابــل مبلــغ الــف ريــال ثــم ذهــب بالســيارة وال يعلــم مصيرهــا بعــد ذلــك ‪.‬‬\n      ‫‪-9‬يف نهايــة شــهر ذي القعــدة لعــام ‪1432‬ه ـ احضــر لــه ‪ ......‬ســيارة‬\n\n\n‫‪173‬‬\n\f‫مســروقة نــوع ‪.....‬لونهــا ابيــض موديــل ‪2010‬م ال يذكــر رقــم لوحتهــا‬\n‫ولــم يخبــره ايــن او كيــف ســرقها واخذهــا منــه مقابــل مبلــغ مالــي وقــدره‬\n             ‫ســتة االف ريــال وقــام بقــص الســيارة وبيعهــا كقطــع غيــار ‪.‬‬\n‫‪-10‬يف نهايــة عــام ‪1432‬ه ـ احضــر لــه ‪ ......‬ســيارة مســروقة نــوع ‪.....‬‬\n‫لونهــا فضــي موديــل ‪2011‬م ال يذكــر رقــم لوحتهــا ولــم يخبــره مــن ايــن‬\n‫او كيــف ســرقها وقــام بأخذهــا منــه مقابــل مبلــغ وقــدره عشــرة االف‬\n                ‫ريــال وظلــت الســيارة يف الورشــة الــى ان مت القبــض عليــه ‪.‬‬\n‫‪-11‬يف نهايــة عــام ‪1432‬ه ـ حضــر لــه يف الورشــة زبــون ‪ .......‬امريكــي‬\n‫اجلنســية وبقيادتــه ســيارة نــوع ‪ .....‬لونهــا ابيــض موديــل ‪2011‬م ال يذكــر‬\n‫رقــم لوحتهــا وكان بهــا صدمــه يف الرفــرف وطلــب اصالحهــا فطلــب‬\n‫منــه ان يحضــر بعــد يومــن الســتالمها وعندمــا ذهب قام بنســخ مفتاحها‬\n‫وكان يوجــد بهــا جهــاز تتبــع اخــذ رقمــه ويف اليــوم الثانــي حضــر الزبــون‬\n‫واســتلم ســيارته وذهــب وبعدهــا بحوالــي عشــرة ايــام حــدد موقعهــا عــن‬\n‫طريــق جهــاز التتبــع وكلــف ‪ ......‬بإحضارهــا وبالفعــل احضرهــا واعطــاه‬\n‫مقابــل ذلــك مبلــغ وقــدره ثمانيــة االف ريــال وظلــت الســيارة لديــه الــى ان‬\n                                                               ‫مت القبــض عليــه ‪.‬‬\n‫‪-12‬يف منتصــف شــهر محــرم لعــام ‪1433‬ه ـ احضــر لــه ‪ ......‬ســيارة‬\n‫مســروقة نــوع ‪ .....‬لونــا بيــج موديــل ‪2009‬م ال يذكــر رقــم لوحتهــا ولــم‬\n‫يخبــره مــن ايــن او كيــف ســرقها واخذهــا منــه واوقفهــا بحــي ‪ .......‬ولــم‬\n          ‫يدفــع لــه مقابلهــا أي مبلــغ كونــه مت القبــض عليــه قبــل ذلــك ‪.‬‬\n‫‪-13‬بعــد ذلــك بثالثــة ايــام تقريبــا احضــر لــه ‪ ......‬ســيارة مســروقة نــوع‬\n‫‪ .....‬لونهــا ابيــض موديــل ‪2010‬م ال يذكــر رقــم لوحتهــا ولــم يخبــره مــن‬\n‫ايــن او كيــف ســرقها واخذهــا منــه ولــم يدفــع لــه مقابلهــا شــيء كونــه‬\n\n\n                                                                                     ‫‪174‬‬\n\f                                                 ‫مت القبــض عليــه وهــي يف الورشــة ‪.‬‬\n      ‫واضــاف ان املدعــو ‪ ......‬احضــر لــه يف فتــرات مختلفــة مكائــن ســيارات‬\n      ‫مــن نــوع ‪ ..... .....‬وعددهــا ســبع مكائــن ال يعــرف مصدرهــا قام بشــرائها‬\n      ‫منــه ‪.‬كمــا اضــاف انــه طلــب مــن كفيلــه ‪ ...... /‬منــذ مــدة صــورة‬\n      ‫بطاقــة احوالــه وقــام بنســخها عــدة نســخ واســتخدمها يف عمليــة بيــع‬\n      ‫وشــراء الســيارات كمــا اقــر ان املدعــو ‪ ........ /‬اجلنســية واملدعــو ‪/‬‬\n      ‫‪ .......‬ســوري اجلنســية واملدعــو ‪ ....... /‬ســوري اجلنســية لــم يكــن لديهــم‬\n      ‫أي علــم مبــا يقــوم بــه او بالســيارات املســروقة التــي كانــت لديــه وقــد‬\n      ‫صــادق علــى اعترافاتــه شــرعا ومبناقشــته عــن عبوتــي املســكر التــي‬\n      ‫عثــر عليهــا بالورشــة افــاد انــه عثــر عليهــا يف احــدى الســيارات التــي‬\n                                                                  ‫اشــتراها مــن املــزاد ‪.‬‬\n      ‫وباســتجواب الثانــي ‪ ......... /‬صاحــب الورشــة وكفيــل االول ‪ ..... /‬وزوج‬\n      ‫شــقيقته افــاد ان الورشــة التــي يعمــل بهــا مكفولــه ‪ ......‬عائــدة لــه وقــام‬\n      ‫بفتــح الورشــة بنــاء ًا علــى طلــب مــن ‪ .....‬كونــه شــقيق زوجتــه وانــه هــو‬\n      ‫املســئول عنهــا بشــكل كامــل (فــرزت اوراق خاصــة بالتســتر التجــاري‬\n                                                       ‫واحيلــت الــى اجلهــة املختصــة) ‪.‬‬\n      ‫ومبناقشــته عن عدد تســعة وخمســون ســيارة نقلت من اســمه ألشــخاص‬\n      ‫اخريــن افــاد بانــه علــى علــم ببعضهــا حيــث انــه يشــرف علــى الورشــة مــن‬\n      ‫فتــرة ألخــرى والبعــض االخــر يتــم نقلــه مــن قبــل ‪ .....‬واضــاف ان ‪.....‬كان‬\n      ‫يقــوم بشــراء الســيارات املصدومــة مــن املــزاد ويقــوم بإصالحهــا ومــن‬\n      ‫ثــم بيعهــا ومبناقشــته عــن كيفيــة نقلهــا افــاد انــه يف بدايــات افتتاحــه‬\n            ‫للورشــة طلــب منــه ‪ ....‬صــورة البطاقــة إلبرازهــا للجهــات الرســمية ‪.‬‬\n      ‫وباســتجواب ‪ 21 ...........‬ســنة ســوري اجلنســية اقامــة رقــم (‪ )........‬يعمــل‬\n\n\n‫‪175‬‬\n\f‫حتــت كفالــة ‪ .......‬افــاد انــه يقــوم بتحميــل ســيارات بطلــب مــن االول‬\n‫‪ .....‬علــى الســطحة التــي يعمــل بهــا ويقــوم بإحضارهــا مــن التشــاليح‬\n‫وايصالهــا للورشــة التــي يعمــل بهــا ‪ ....‬يف صناعيــة النســيم ومبناقشــته‬\n‫عــن عــدد الســيارات التــي قــام بتحميلهــا افــاد بانــه ال ميكنــه احصائهــا‬\n‫كونــه يعمــل منــذ وقــت طويــل مع ‪ ....‬حوالي الســنة والنصف ومبناقشــته‬\n‫عــن نوعيــة الســيارات التــي يقــوم بتحميلهــا افــاد انــه مختلفــة االنــواع‬\n                                                             ‫ومعظمهــا مصدومــة‪.‬‬\n‫وببعــث زجاجتــي املســكر التــي مت ضبطهــا داخــل الورشــة ملركــز‬\n‫الســموم والكيميــاء الشــرعية للكشــف عــن ايجابيتهــا ملــادة الكحــول‬\n‫االيثيلــي مــن عدمــه ثبتــت ايجابيتهــا ملــادة الكحــول بنســبة ‪ %36‬العينــة‬\n                      ‫الثانيــة ثبتــت ايجابيتهــا ملــادة الكحــول بنســبة ‪. %34‬‬\n‫وقــد اســفر التحقيــق عــن توجيــه االتهــام لــأول ‪ .......‬باالشــتراك مــع ‪......‬‬\n‫يف تكويــن عصابــه لســرقة الســيارات واجزائهــا وتصريــف املســروقات‬\n‫وقيامــه بســرقة عــدد (ســبعة عشــر ســيارة) واســتغالل عملــه يف الورشــة‬\n‫التــي يعمــل بهــا ثــم احضارهــا للورشــة وحتريــف ارقــام هياكلهــا‬\n‫وتركيبهــا علــى ســيارات اخــرى وبيعهــا واكل ثمنهــا وحيازتــه‬\n‫للمســكر بقصــد تعاطيــه وهروبــه مــن الفرقــة القابضــة وتســتر الثانــي‬\n‫علــى االول ممــا جعــل االول يوغــل يف اعمالــه اإلجراميــة وذلــك لألدلــة‬\n                                                                  ‫والقرائــن التاليــة‪:‬‬\n‫‪-1‬مــا جــاء يف اعتــراف املــدون علــى الصفحــات رقــم (‪ 1‬ـ ـ ‪ )5‬مــن ملــف‬\n‫التحقيــق رقــم (‪ )2‬لفــة (‪ )2‬املتضمــن لفــة (‪ )14‬الدوســية رقــم (‪)1‬‬\n‫املتضمــن قيامــه باالشــتراك مــع املتهــم الهــارب ‪ ......‬بســرقة الســيارات‬\n           ‫وحتريــف هياكلهــا واالســتفادة مــن ثمنهــا واملصــدق شــرع ًا ‪.‬‬\n\n\n                                                                                          ‫‪176‬‬\n\f      ‫‪ -2‬مــا جــاء يف محضــر القبــض املتضمــن العثــور علــى ثــاث ســيارات‬\n      ‫داخــل الورشــة التــي يعمــل بهــا والتــي اتضــح أنهــا مســروقة والعثــور علــى‬\n      ‫ثــاث ســيارات هيــاكل لســيارات بــدون لوحــات وال أرقــام هيــكل‬\n      ‫وعــدد أربــع عشــرة اســتمارة ســيارات متنوعــة وتســع عشــرة لوحــة‬\n      ‫ســيارات متنوعــة وثالثــة وثالثــن شــريحة هيــكل معدنيــة وجهــاز لســبك‬\n      ‫هيــاكل الســيارات وســاح نــاري نــوع مســدس املرفــق لفــة (‪ )16‬مــن‬\n                                                                      ‫الدوســية رقــم (‪)1‬‬\n      ‫‪-3‬مــا جــاء يف اقــوال الثانــي ‪ ........‬انــه املســئول عــن الورشــة وتطابــق ذلــك‬\n      ‫مــع مــا ذكــره االول املــدون علــى صفحــة (‪ 1‬ـ ـ ‪ )5‬مــن دفتــر التحقيــق‬\n                           ‫رقــم (‪ )7‬املرفــق لفــة رقــم (‪ )7‬مــن الدوســية رقــم (‪. )1‬‬\n      ‫‪-4‬مــا جــاء يف نتيجــة فحــص الســيارات التــي عثــر عليهــا بالورشــة التــي‬\n      ‫يعمــل بهــا مــن قبــل األدلــة اجلنائيــة املتضمــن وجــود ثــاث ســيارات مت‬\n                                            ‫فحصهــا اتضــح ان هياكلهــا محرفــه ‪.‬‬\n      ‫‪-5‬مــا جــاء يف محضــر االنتقــال واملعاينــة املتضمــن العثــور علــى ثــاث‬\n      ‫هيــاكل ســيارات مفككــة والعثــور علــى عدد مــن قصاصات هياكل‬\n                       ‫ســيارات متنوعــة ولوحــات ســيارات وزجاجتــي املســكر‪.‬‬\n      ‫‪-6‬قيامــه بشــراء مائــة وســبعة وعشــرين ســيارة ومــن ثــم بيعهــا كمــا‬\n      ‫يتضــح جلهــة التحقيــق بعــد االستفســار عنــه ممــا يــدل علــى متاجرتــه‬\n                                                  ‫بالســيارات بطريقــة غيــر نظاميــة‪.‬‬\n      ‫‪-7‬مــا جــاء يف محضــر دوريــات األمــن الســرية املتضمــن هروبــه مــن‬\n      ‫الفرقــة اثنــاء اســتدعائه مــن الورشــة ممــا يــدل علــى تورطــه بتلــك‬\n                   ‫الســرقات املرفــق لفــة رقــم (‪ )16‬مــن الدوســية رقــم (‪.)1‬‬\n      ‫‪-8‬ما جاء يف اقوال ‪ ..... /‬ســوري اجلنســية قائد ســيارة (ســطحة) ســحب‬\n\n\n‫‪177‬‬\n\f‫ســيارات بقيامــه بنقــل ســيارات مصدومــة مــن الورشــة التــي يعمــل بهــا ‪/‬‬\n‫‪ ....‬وارســاله للتشــاليح بأمــر وبشــكل مســتمر ممــا يــدل علــى مترســه‬\n‫لعمليــات تشــليح الســيارات واالســتفادة مــن أجزائهــا وال يســتبعد جلهــة‬\n‫التحقيــق أن تكــون تلــك الســيارات مســروقة املدونــة علــى صفحــة رقــم‬\n‫(‪ 1‬ـ ـ ‪ )8‬مــن دفتــر التحقيــق رقــم (‪ )14‬املرفــق لفــة رقــم (‪ )2‬مــن الدوســية‬\n‫رقــم (‪- )1‬مــا جــاء يف اقــوال الثانــي املتضمنــة قيامــه باســتئجار الورشــة‬\n‫ملكفولــة ‪ ..... /‬طوعـ ًا منــه واعطائــه الصالحيــات الكاملــة بالتصــرف‬\n‫بهــا املدونــة علــى الصفحــة رقــم (‪ 1‬ـ ـ ‪ )5‬من الدفتر رقم (‪ )7‬من الدوســية‬\n                                                                          ‫رقــم (‪. )1‬‬\n‫‪-10‬مــا جــاء يف اعتــراف ‪ ..... /‬املتضمــن العمــل يف الورشــة العائــدة‬\n‫لكفليــه دون معرفــة كفيلــة نشــاط الورشــة او مــا يحــدث بهــا املدونــة‬\n ‫علــى الصفحــة (‪ 1‬ـ ـ ‪ )5‬مــن الدفتــر رقــم (‪ )2‬مــن الدوســية رقــم (‪. )1‬‬\n‫‪-11‬مــا جــاء يف اقــوال الثانــي املتضمنــة تســليمه صــورة هويتــه ملكفولــة‬\n‫املتهــم ‪ .... /‬دون ابــداء مبــرر لذلــك صفحــة رقــم (‪ 1‬ـ ـ ‪ )5‬مــن دفتــر‬\n                                       ‫التحقيــق رقــم (‪ )7‬الدوســية رقــم (‪. )1‬‬\n‫وببحــث ســوابقهما تبــن عــدم وجــود ســوابق مســجله عليهمــا حتــى‬\n                                                                           ‫تاريخــه ‪.‬‬\n‫وحيــث ان مــا اقــدم عليــه املدعــى عليهمــا فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا اطلــب اثبــات مــا اســند اليهمــا واحلكــم بتعزيرهمــا مبــا يردعهمــا‬\n‫والتشــديد علــى االول لقــاء مــا اقــدم عليــه مــن جــرم يعــد انتهــاك ًا ألمــن‬\n‫البــاد (علمــا بــان احلــق اخلــاص مــا زال قائم ـاً) هــذه دعــواي وبعــرض‬\n‫ذلــك علــى املدعــى عليــه طلــب صــورة مــن الئحــة الدعــوى لإلجابــة عــن‬\n‫الدعــوى يف اجللســة القادمــة ثــم رفعــت اجللســة لذلــك وبــاهلل التوفيــق‪،‬‬\n\n\n                                                                                        ‫‪178‬‬\n\f      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪ 1433/10/18‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1433/11/13‬ه ـ‬\n      ‫افتتحت اجللسة الساعة ‪ 11.30‬وفيها حضر املدعي العام واملدعى عليه‬\n      ‫وبعــرض مــا ورد يف الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره‬\n      ‫املدعــي العــام غيــر صحيــح ألنــي ال أســتلم ســيارات بــل أنــا ميكانيكــي‬\n      ‫وال عالقــة لــي بالســمكرة وقــص الهيــاكل وجميــع االعترافــات الواردة‬\n      ‫يف الالئحــة أخــذت منــي علــى ســبيل اإلكــراه وبالقــوة والضــرب والســب‬\n      ‫والتهديــد هكــذا أجــاب ثــم رفعــت اجللســة لالطــاع علــى االعترافــات‬\n      ‫وتأمــل مــا جــاء فيهــا ويف يــوم اإلثنــن املوافــق‪ 1434/01/19‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11.30‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n      ‫وبســؤال املدعــي العــام عــن ســبب عــدم إحضــار الســجني وقــد مت طلبــه‬\n      ‫أكثــر مــن مــرة ســابقا فأجــاب بأنــه مت طلبــه عــن طريــق املســؤول عــن‬\n      ‫إحضــار الســجناء حســب إفــادة احملضــر إال أنــه لــم يحضــر وقــد جــرى‬\n      ‫االطــاع علــى إقــراره املدعــى عليــه املصــادق عليهــا شــرعا املدونــة مبلــف‬\n      ‫التحقيــق الثانــي التــي تتضمــن إقــراره مبــا جاء مفصــا يف الئحة االدعاء‬\n      ‫العــام وبعــرض ذلــك علــى املدعــى عليــه أجــاب بــأن كل ذلــك حصــل‬\n      ‫عــن طريــق اإلكــراه بالضــرب بكيابــل الكهربــاء والعصــي واملســاومة‬\n      ‫بــأن جميــع مــن ســجن بســبب هــذه القضيــة لــن يخــرج إال بعــد أن أقــر‬\n      ‫مبــا أســند إلــي ويصــدق اعتــرايف مــن قبــل احملكمــة هكــذا أجــاب‬\n      ‫وبســؤاله البينــة علــى اإلكــراه قــال لــدي بينــة وهــم ‪ ..........‬و‪......‬و‪......‬‬\n      ‫وســوف أحضرهــا يف اجللســة القادمــة ثــم رفعــت اجللســة إلحضــار البينــة‬\n      ‫وذلــك حتــى يــوم الغــد املوافــق ‪1434/1/20‬ه ـ ويف املوعــد احملــدد‬\n\n\n‫‪179‬‬\n\f‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر حلضــوره ‪............‬‬\n‫الســعودي بالســجل رقــم ‪ ...........‬وبســؤاله عمــا لديــه أجــاب بقولــه بأنــي‬\n‫نســيب للمدعــى عليــه والورشــة كانــت باســمي وقــد ســجنت بســبب هذه‬\n‫القضيــة ملــدة شــهرين وأشــهد أن أحــد الضبــاط ال أذكــر اســمه أحضــر‬\n‫املدعــى عليــه عندمــا كنــت ســجينا وقــال لــه هــذا رحيمــك إن أردت أن‬\n‫نطلقــه فاعتــرف باالتهامــات املوجهــة ضــدك هكــذا شــهد كمــا حضــر‬\n‫‪ ......‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪ ...........‬وبســؤاله عمــا لديــه‬\n‫قــال انــي ســجنت بســبب هــذه القضيــة ملــدة شــهر بســبب تعامالتــي مــع‬\n‫املدعــى عليــه حيــث انــي أعمــل يف مكتــب للخدمــات العامــة وأســتلم‬\n‫منــه أوراقــا لكــي يقــوم صاحــب املكتــب مبراجعــة املــرور ويقــوم‬\n‫بنقــل ملكيــة الســيارات اخلاصــة باملدعــى عليــه وأشــهد أن الضابــط‬\n‫الــذي يحقــق يف القضيــة يقــول للمدعــى عليــه امامــي لــن يخــرج زميلــك‬\n‫وكان يقصدنــي إال إذا اعترفــت وصدقــت اعترافاتــك مــن احملكمــة‬\n‫هكــذا شــهد ثــم رفعــت اجللســة إلحضــار املدعــى عليــه ويف يــوم الثالثــاء‬\n‫املوافــق‪ 1434/02/19‬ه ـ افتتحــت اجللســة الســاعة ‪ 11.55‬وفيهــا حضر‬\n‫املدعــى العــام واملدعــى عليــه األول وبســؤال املدعــى عليــه عــن الســيارة‬\n‫املنزوعــة هياكلهــا املوجــودة يف الورشــة التــي يشــرف عليهــا أجــاب‬\n‫بقولــه بأنــي ميكانيكــي وال عالقــة لــي بهــذا األمــر فهــو مــن اختصاص‬\n‫الســمكري هكــذا أجــاب وبتأمــل مــا ســبق وحيــث أن هنــاك طرفــا‬\n‫لــم يتــم القبــض عليــه ليتــم أخــذ أقوالــه وهــو الهــارب ‪ ......‬حتــى يتضــح‬\n‫حقيقــة األمــر وحيــث أن إفــادة املذكوريــن تطعــن يف صحــة اإلقــرار مــع‬\n‫أن أحدهمــا وهــو املدعــى عليــه الثانــي ‪ .......‬متهمــا يف نفــس القضيــة إال‬\n‫أنــه يعضــد أقوالــه مــا جــاء يف أمــر اإلفــراج الصــادر بعــد املصادقــة علــى‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫إقــرار املدعــى عليــه األول وملــا قــرره الفقهــاء رحمهــم اهلل مــن أن الســجن‬\n      ‫حــال التحقيــق وســيلة مــن وســائل اإلكــراه إال أن إقــراره بأنــه املشــرف‬\n      ‫علــى الورشــة ولوجــود أكثــر مــن ســيارة مســروقة منزوعــة الهيــكل يف‬\n      ‫الورشــة مــع إقــراره وإن كان فيــه مــا فيــه قرائــن تســتوجب توجــه التهمــه‬\n      ‫ضــده يف املشــاركة يف ســرقة الســيارات املذكــورة لذلــك كلــه فقــد‬\n      ‫حكمــت بــرد دعــوى املدعــى العــام يف مطالبتــه بإثبــات إدانــة املدعــى‬\n      ‫عليــه األول ‪.......‬احلاضــر وحكمــت بتعزيــره لقــاء توجــه التهمــة ضــده‬\n      ‫يف املشــاركة بســرقة الســيارات املذكــورة بســجنه ملــدة ســنة وثالثــة‬\n      ‫أشــهر اعتبــارا مــن تاريــخ إيقافــه وجلــده مائــة وخمســون جلــده علــى أن‬\n      ‫تكــون كل دفعــة خمســون جلــدة ومــا بــن كل دفعــة واألخــرى مــدة ال‬\n      ‫تقــل عــن اســبوعني وأفهمــت املدعــي العــام أن لــه إقامــة الدعــوى علــى‬\n      ‫املدعــى عليــه الثانــي حــال حضــوره وبعــرض ذلــك علــى الطرفــن قــرر‬\n      ‫الطرفــان عــدم القناعــة وطلبــا متييــز احلكــم بــدون الئحــة اعتراضيــة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                             ‫حــرر يف ‪ 1434/02/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/05/07‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪1.45‬وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالريــاض وبرفقهــا قــرار الدائــرة اجلزائيــة الثانيــة رقــم ‪......‬‬\n      ‫يف ‪1434/4/20‬ه ـ املتضمــن أن صــورة ضبــط القــرار ناقصــة ويتعــذر‬\n      ‫دراســتها أ‪.‬ه ـ عليــه فقــد مت إكمــال الــازم حيــال ذلــك وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                     ‫‪ 1434/05/07‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n\n\n‫‪181‬‬\n\f‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم ‪......‬‬\n‫وتاريــخ ‪1434/5/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ ......‬املســجل برقــم ‪ ........‬وتاريــخ ‪1434/2/23‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪( ...... /1‬ســوري اجلنســية)‬\n‫‪ ...... / 2‬التهامهــم بســرقة ســيارة علــى النحــو املوضــح بالقــرار املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى‬\n‫قــرار الدائــرة رقــم‪ ........‬وتاريــخ ‪1434/4/20‬ه ـ قررنــا املصادقــة علــى‬\n‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى الــه‬\n                                                           ‫وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n                                                                                   ‫‪182‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":166,"source_page_end":182,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"41fa01f8b1683f7933c18e345a95237d5bb7cfc19414b01ff1e45bd802a15d6c","normalized_text_hash":"fe3a2cf0b87cc714e29b715be647dc84392dc253720906b640551b0ca61166a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p166-3444627"},{"id":"727fa880-9bae-54d9-ae17-b5f7f86a6535","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -إحداث تلفيات يف سيارة مسروقة -تصرف يف بضاعة مسروقة -توجيه تهمة بالقرائن -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملا اتهم به.","document_number":"3344793","case_number":"33601903","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/08","year":"1434","subject":"سرقة -سرقة سيارة -إحداث تلفيات يف سيارة مسروقة -تصرف يف بضاعة مسروقة -توجيه تهمة بالقرائن -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملا اتهم به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3344793:‬تاريخه ‪1434/11/08:‬هـ‬\n                          ‫رقم الدعوى ‪33601903:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3422526‬تاريخه‪1434/01/25 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬إحــداث تلفيــات يف ســيارة مســروقة‪ -‬تصــرف يف‬\n      ‫بضاعــة مســروقة‪ -‬توجيــه تهمــة بالقرائــن‪ -‬تعزيــر بالســجن واجللــد‬\n                                       ‫وأخــذ تعهــد بعــدم العــودة ملــا اتهــم بــه‪.‬‬\n\n\n\n                   ‫‪-1‬قول اهلل تعالى ( وال تفسدوا يف األرض بعد إصالحها )‬\n                          ‫‪-2‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين)‬\n      ‫‪-3‬قولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه‬\n                                                                   ‫ومالــه وعرضــه )‬\n      ‫‪-4‬قولــه صلــى اهلل عليــه وســلم فــإن دماءكــم وأموالكــم وإعراضكــم‬\n      ‫عليكــم حــرام كحرمــة يومكــم هــذا يف شــهركم هــذا يف بلدكــم هــذا )‬\n      ‫‪-5‬قولــه صلــى اهلل عليــه وســلم (إن املســلم أخــو املســلم فليــس املســلم‬\n                            ‫يحــل مــن أخيــه شــيء إال مــا حــل لــه مــن نفســه )‪.‬‬\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه ‪ .......‬مواطــن ‪ .......‬بطلــب‬\n      ‫إثبــات إدانتــه بســرقة ســيارة وإحــداث تلفيــات بهــا والتصــرف مبــا‬\n      ‫كانــت حتتويــه مــن بضاعــة عبــارة عــن كماليــات وطلــب احلكــم‬\n      ‫بعقوبــة تعزيريــة‪ ،‬حيــث مت القبــض علــى املدعــى عليــه بعــد بــاغ مفــاده‬\n      ‫تعــرض ســيارة أحــد األشــخاص للســرقة وبهــا بضاعــة معــدة للبيــع‬\n‫‪183‬‬\n\f‫وقــد شــاهد أحــد أقــارب ســائق الســيارة املتهــم يف أحــد احملــات يقــوم‬\n‫بعــرض البضاعــة حيــث تعــرف عليهــا الشــاهد وبعــد البحــث والتحــري‬\n‫مت القبــض علــى املدعــى عليــه إال أنــه أنكــر وذكــر أنــه اشــترى مــن‬\n‫أخيــه بعــض الكماليــات‪ ،‬وذكــر املدعــي العــام بيناتــه وهــي موجــودة‬\n‫يف لفــات املعاملــة منهــا شــهادة شــاهد‪ ،‬ومحضــري عــرض‪ ،‬وتقريــر‬\n‫مــن شــعبة التحريــات والبحــث اجلنائــي ومضمونــه أن املدعــى عليــه‬\n‫ســيء الســلوك وكثيــر للتجــوال آخــر الليــل وكذلــك محاولــة تضليــل‬\n‫جهــة التحقيــق واملراوغــة‪ ،‬وقــد تقــرر عــدم ثبــوت إدانــة املدعــى عليــه‬\n‫وتوجيــه التعزيــر ألجــل التهمــة‪ ،‬وحكمــت احملكمــة بتعزيــر املدعــى‬\n‫عليــه بالســجن واجللــد وأخــذ التعهــد‪ ،‬مت تصديــق احلكــم مــن محكمــة‬\n                                                                  ‫االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‬\n‫ـاء علــى‬‫ـدي أنــا ‪ ............‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬   ‫فلـ َّ‬\n‫املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫األحســاء برقــم ‪ ........‬وتاريخ‪..........‬واملقيــدة بهــذه احملكمــة برقــم‪..........‬‬\n‫وتاريخ‪.........‬واحملالــة إلينــا مــن فضيلــة الرئيــس برقم‪........‬وتاريــخ‪.........‬‬\n‫فتحــت اجللســة األولــى يــوم األربعــاء ‪......‬الســاعة العاشــرة والنصف وفيها‬\n‫حضــر املدعــي العــام ‪ ........‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫وقرر دعواه‬   ‫األحســاء ذي الرقم هـ ق‪ 137/2/2‬والتاريخ ‪1431/1/5‬هـ ّ‬\n‫ا ‪ :‬بصفتــي مدعيـ ًا عامـ ًا يف دائــرة االدعــاء العام مبحافظة األحســاء‬           ‫قائـ ً‬\n\n                                                                                             ‫‪184‬‬\n\f      ‫أدعــي علــى‪ ، ......... :‬البالــغ مــن العمــر (‪ )29‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ).........‬أعــزب ‪ ،‬متســبب ‪ ،‬قبــض عليــه‬\n      ‫بتاريــخ ‪........‬وأحيــل إلــى شــعبة ســجن محافظــة األحســاء مبوجــب القــرار‬\n      ‫الــوزاري رقــم (‪ )1900‬الفقــرة اخلامســة‪ ،‬وســجل نزيــل لديهــم برقــم(‪.)....‬‬\n      ‫انــه بتاريــخ ‪........‬ه ـ قبــض عليــه مــن قبــل إحــدى فــرق الدوريــات األمنيــة‬\n      ‫مبحافظــه اإلحســاء اثــر البــاغ املقــدم مــن الوافــد ‪ .......‬هنــدي اجلنســية‬\n      ‫عــن تعــرض ســيارة كفيلــه التــي بقيادتــه مــن نــوع موديــل (‪ )..‬لوحــة‬\n      ‫رقــم (‪ )......‬للســرقة أثنــاء وقوفهــا أمــام مقــر ســكنه بحــي ‪ ، .......‬حيــث‬\n      ‫قــام بإيقــاف ســيارة كفيلــه أمــام مقــر ســكنه بحــي يف متــام الســاعة‬\n      ‫الثانيــة عشــر صباح ـ ًا مــن يــوم األحــد املوافــق‪.........‬ويف متامــا الســاعة‬\n      ‫الثامنــة صباحـ ًا مــن نفــس اليــوم وعنــد خروجــه مــن منزلــه ملزاولــة عملــه‬\n      ‫لــم يعثــر عليهــا واتضــح لــه بأنهــا قــد تعرضــت للســرقة مضيف ـ ًا بأنهــا‬\n      ‫حتتــوي علــى بضاعــة عبــارة عــن مجموعــة مــن املســتلزمات الكماليــة‬\n      ‫(شــامبو ؟ وألعــاب أطفــال ؟ معجــون أســنان) تقــدر قيمتهــا بحوالــي‬\n      ‫ســتة وخمســون ألــف ريــال وال يتهــم أحــد ًا بتلــك الســرقة‪ .‬وباالنتقــال‬\n      ‫ومعاينــة الســيارة بعــد العثــور عليهــا اتضــح وجــود تلفيــات بهــا قــدرت‬\n      ‫مببلــغ ثمانيــة آالف وثمامنائــة وخمســون ريــال وســلمت لصاحبهــا بحالتهــا‬\n      ‫الراهنــة‪ .‬وبضبــط أقــوال الشــاهد املدعــو‪ )43( ........ /‬ســنة هنــدي‬\n      ‫اجلنســية والــذي أفــاد بوجــود صلــة قرابــة بينــه وبــن‪ ....... /‬املذكــور‬\n      ‫ويعلــم عــن تعــرض ســيارته املشــار إليهــا للســرقة ويعلــم عــن مواصفــات‬\n      ‫البضاعــة التــي بالســيارة عنــد الســرقة كونهمــا يعمــان ســوي ًا بنقــل‬\n      ‫البضائــع وذكــر بأنــه بتاريــخ ‪........‬ه ـ يف متــام الســاعة احلاديــة عشــر‬\n      ‫صباح ـ ًا وأثنــاء ذهابــه ألحــد البقــاالت ال يعــرف اســمها ‪ ............‬شــاهد‬\n\n\n‫‪185‬‬\n\f‫شــخص ســعودي اجلنســية خــارج مــن تلــك البقالــة وبحوزتــه كيــس أزرق‬\n‫اللــون وبــه مجموعــة مــن املقصــات والســكاكني وأغــراض أخــرى قــام‬\n‫بعرضهــا عليــه للبيــع وعندمــا شــاهد تلــك البضاعــة مــن قبــل الشــاهد‬\n‫املذكــور تعــرف عليهــا بأنهــا البضاعــة املســروقة والتــي كانــت بســيارة‬\n‫املبلــغ املذكــور وقــت الســرقة وعندمــا شــعر ذلــك الشــخص بأنــه علــم‬\n‫عــن مصــدر تلــك البضاعــة تراجــع عــن البيــع وقــام بالركــوب بســيارته‬\n‫التــي مــن نــوع ‪ .......‬اللــون فضــي لوحــة رقــم (‪ ).....‬وذهــب جلهــة غيــر‬\n‫معلومــة وأقــر بأنــه يســتطيع التعــرف علــى ذلــك الشــخص عنــد عرضــه‬\n‫عليــه‪ .‬وبعــرض صــورة املدعــى عليــه‪ .......... /‬علــى الشــاهد املذكــور‬\n‫واســتطاع التعــرف عليــه بنســبة (‪ )%100‬وذكــر بأنــه الشــخص الــذي‬\n‫قــام بعــرض البضاعــة عليــه‪ .‬وبعــرض املدعــى عليــه‪ .... /‬املذكــور علــى‬\n‫الشــاهد‪ ..... /‬املذكــور عرضـ ًا قانونيـ ًا واســتطاع التعــرف عليــه بنســبة‬\n‫(‪ )%100‬وذكــر بأنــه الشــخص الــذي قــام بعــرض البضاعــة املســروقة‬\n‫ا قــام‬\n      ‫عليــه‪ .‬وبضبــط أقــوال املدعــى عليــه األولى‪/‬أعتــرف بأنــه فع ـ ً‬\n‫بعــرض بضاعــة علــى الوافــد‪ . ..../‬ومبواجهــة الشــاهد‪ ..... /‬املذكــور‬\n‫باملدعــى عليــه وأفــاد الشــاهد مبثــل مــا أفــاد بــه بشــهادته وباســتجوابه‬\n‫ا قــام بعــرض تلــك البضاعــة علــى الشــاهد‬    ‫املدعــى عليــه‪ /‬أقــر بأنــه فعـ ً‬\n‫لشــرائها ولكنــه أفــاد بأنــه حصــل عليهــا مــن شــقيقه‪ ........ /‬حيــث قــام‬\n‫بشــرائها منــه بقيمــة مائــة وثمانيــة وســبعني ريــال واتضــح مــن املواجهــة‬\n‫ارتبــاك املدعــى عليــه وخوفــه وتخبطــه يف الــكالم‪ .‬ومبواجهــه املدعــى‬\n‫عليــه‪ .... /‬بشــقيقه املدعــو‪ .... /‬وذلــك داخــل ســجن محافظــة األحســاء‬\n‫وأفــاد املدعــى عليــه ‪ ............‬بأنــه حصــل علــى تلــك البضاعــة املســروقة‬\n‫مــن شــقيقه‪ ... /‬حيــث قــام بشــرائها مببلــغ مائــة وثمانيــة وســبعني‬\n\n\n                                                                                       ‫‪186‬‬\n\f      ‫ا وذكــر بأنــه‬    ‫ريــال وبســماع شــقيقه‪ ... /‬ذلــك أنكــره جملــة وتفصي ـ ً‬\n      ‫شــقيقه‪ .... /‬مــراوغ ويريــد تبرئــه نفســه خوف ـ ًا مــن العقوبــة وتبــن مــن‬\n      ‫املواجهــة ضعــف موقــف املدعــى عليــه‪ .... /‬وعــدم اســتطاعته إكمــال‬\n      ‫املواجهــة‪ .‬وباالطــاع علــى فواتيــر مــن قبــل املبلــغ موضح ـ ًا بهــا قيمــة‬\n      ‫البضاعــة املســروقة واتضــح مببلــغ وقــدره ســتة وخمســون ألــف وســتمائة‬\n      ‫وثالثــة وعشــرون (‪ )56623‬ريــال كذلــك مت إحضــار فواتيــر موضح ـ ًا‬\n      ‫بهــا قيمــة إصــاح املركبــة بعــد العثــور عليهــا واتضــح بــأن التكلفــة‬\n      ‫اإلجماليــة مببلــغ وقــدره ثمانيــة آالف وثمامنائــة وخمســون (‪ )8850‬ريــال‬\n      ‫وذلــك حســب الفواتيــر املرفقــة بــاألوراق‪ .‬وقــد أســفر التحقيــق معــه عــن‬\n      ‫توجيــه االتهــام لــه بســرقة ســيارة الوافــد‪....... /‬و ‪ ......‬هنــدي اجلنســية‬\n      ‫التــي مــن نــوع (‪ )0000 000‬وأحــداث تلفيــات بهــا تقــدر مببلــغ وقــدره‬\n      ‫ثمانيــة آالف وثمامنائــة وخمســون (‪ )8850‬ريــال كذلــك التصــرف‬\n      ‫مبــا كانــت حتتويــه مــن بضاعــة عبــارة عــن كماليــات تقــدر قيمتهــا‬\n      ‫بســتة وخمســن ألــف وســتمائة وثالثــة وعشــرين ريــا ًال ‪ ،‬وذلــك لألدلــة‬\n                                                                  ‫والقرائــن التاليــة‪-:‬‬\n      ‫‪-1‬ماجــاء يف أقــوال الشــاهد‪ ....../‬املنــوه عنــه واملــدون علــى الصفحــة‬\n                                              ‫رقم(‪)11‬مــن دفتــر التحقيــق رقــم(‪)2‬‬\n      ‫‪-2‬محضــر عــرض صــورة املدعــى عليــه علــى أنظــار الشــاهد والــذي‬\n      ‫اســتطاع بــه التعــرف علــى املدعــى عليــه‪ ..... /‬بنســبة (‪ )%100‬وذكــر‬\n      ‫بأنــه مــن قــام بعــرض البضاعــة املســروقة عليــه املنــوه عنــه واملــدون علــى‬\n                                 ‫الصفحــة رقم(‪)16‬مــن ملــف االســتدالل رقــم(‪.)2‬‬\n      ‫‪-3‬محضــر عــرض املدعــى عليــه علــى أنظــار الشــاهد عرضــا قانونيــا‬\n      ‫والــذي اســتطاع التعــرف عليــه بنســبة (‪ )%100‬وذكــر بأنــه مــن قــام‬\n\n\n‫‪187‬‬\n\f‫بعــرض البضاعــة املســروقة عليــه املنــوه عنــه واملــدون علــى الصفحــة‬\n                                         ‫رقم(‪)9‬مــن ملــف االســتدالل رقــم(‪.)1‬‬\n‫‪ -4‬كتــاب شــعبة التحريــات والبحــث اجلنائــي رقــم (‪822/9/21‬س)‬\n                                  ‫وتاريــخ ‪........‬ه ـ املرفقــة علــى اللفــة رقــم(‪)27‬‬\n‫‪-5‬محاضــر املواجهــة والــذي تبــن منهــا قــوة حجــة الشــاهد‪ ..... /‬كذلك‬\n‫قــوة حجــة شــقيقه املدعــو‪ ... /‬وضعــف موقــف املدعــى عليــه املنــوه عنهــا‬\n     ‫واملدونــة علــى الصفحتــن رقم(‪)16-13‬مــن ملــف االســتدالل رقــم(‪)1‬‬\n‫‪-6‬مــا جــاء بالفواتيــر التــي احضرهــا املبلــغ والتــي تثبــت قيمــة البضاعــة‬\n‫وكذلــك فواتيــر إصــاح الســيارة املســروقة بعــد العثــور عليهــا املرفقــة‬\n                                                       ‫علــى اللفــات رقــم(‪)63-41‬‬\n‫ا وتراجعــه عــن ذلــك‬      ‫‪ -7‬إنــكاره الشــديد ملــا نســب إليــه جملــة وتفصيـ ً‬\n‫ا عــرض عليــه‬      ‫اإلنــكار بعــد مواجهتــه بالشــاهد واعترافــه بأنــه فع ـ ً‬\n‫تلــك البضاعــة حيــث قــام بشــرائها مــن شــقيقه‪ ..../‬مببلــغ وقــدره مائــة‬\n‫وثمانيــة وســبعني (‪ )178‬ريــا ًال دليــل علــى قيامــه بالســرقة ومراوغتــه‬\n                       ‫محــاو ًال تضليــل جهــة التحقيــق لإلفــات مــن العقوبــة‪.‬‬\n‫‪-8‬كــون مقــر ســكن املدعــى عليــه املذكــور قريــب جــد ًا مــن ســكن‬\n‫املبلــغ ممــا ال يســتبعد قيامــه بالســرقة كونــه وأشــقائه مــن املشــبوهني‬\n‫لدينــا بالســرقات‪ .‬وبالبحــث عمــا إذا كان لــه ســوابقه اتضــح خلــو‬\n‫ســجله مــن الســوابق ‪.‬وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــم بكامــل‬\n‫أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب‬\n                                                              ‫إثبــات مــا أســند إليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة تزجرهــم وتــردع غيرهــم‪ .‬علمـ ًا بــأن احلــق‬\n‫اخلــاص ال يــزال قائم ـ ًا عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد‬\n\n\n                                                                                           ‫‪188‬‬\n\f      ‫ا ‪ :‬مــا‬ ‫مــن أهليتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـ ً‬\n      ‫ذكــره املدعــي العــام مــن اتهامــي بســرقة ســيارة الوافــد ‪ ........‬مــن نــوع‬\n      ‫وإحــداث تلفيــات بهــا تقــدر مببلــغ ثمانيــة آالف وثمامنائــة وخمســن ريــا ًال‬\n      ‫والتصــرف مبــا كانــت حتويــه مــن بضاعــة كماليــات تقــدر قيمتهــا‬\n      ‫بســتة وخمســن ألــف وســتمائة وثالثــة وعشــرين ريــا ًال كل ذلــك غيــر‬\n      ‫صحيــح فلــم أقــم بســرقة أي ســيارة وال أعــرف مــن ســرقها وإمنــا اشــتريت‬\n      ‫مــن أخــي بعــض الكماليــات وأردت بيعهــا كعادتــي وتفاجــأت بذلــك‬\n      ‫العامــل يقــول إن هــذه البضاعــة مســروقة وأنــا ال علــم لــي بســرقتها وإمنــا‬\n      ‫أخذتهــا مــن أخــي هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام علــى‬\n      ‫ـدي ســوى مــا يف أوراق املعاملــة وأطلــب الرجــوع إليهــا‬   ‫دعــواه قــال ليــس لـ َّ‬\n      ‫هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪:‬‬\n      ‫أقــوال الشــاهد ‪ .......‬املدونــة علــى الصحيفــة(‪ )11‬مــن دفتــر التحقيــق‬\n      ‫نصــه ‪ :‬أقـ ُّـر أنــا املوقــع أدنــاه ‪43 .....‬ســنة هنــدي‬\n                                                                ‫رقــم(‪ )2‬املتضمــن مــا ُّ‬\n      ‫اجلنســية إقامــة رقــم(‪ )......‬أقـ ُّـر وأنــا بكامــل قــواي العقليــة املعتبــرة‬\n      ‫شــرع ًا وبطوعــي واختيــاري بأننــي أعمــل ســائق لســيارة نقــل بضائــع مــن‬\n      ‫نــوع ‪ ......‬مــع ابــن أخــي بنقــل البضائــع للمحــات التجاريــة وأفيدكم بأن‬\n      ‫ســيارة ابــن أخــي مــن نــوع‪ .......‬تعرضــت للســرقة وبهــا بضاعــة كماليــات‬\n      ‫تقــدر قيمتهــا بخمســن ألــف ريــال وال نعلــم مــن الــذي قــام بســرقتها‬\n      ‫لكــن يف يــوم أمــس وأثنــاء ذهابــي إلحــدى البقــاالت شــاهدت شــخص‬\n      ‫ســعودي اجلنســية ‪-‬وذكــر أوصافــه‪ -‬خــارج مــن البقالــة وبيــده أغــراض‬\n      ‫وبعــد رؤيتهــا اتضــح أنهــا مــن البضاعــة املســروقة ا‪.‬ه ـ نــص احلاجــة‬\n      ‫ا ‪ :‬مــا ذكــره الشــاهد‬      ‫منــه وبعرضــه علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫يف شــهادته صحيــح وقــد أخــذت البضاعــة مــن أخــي وال عــن ســرقتها‬\n\n\n‫‪189‬‬\n\f‫شــيئ ًا هكــذا قــرر كمــا جــرى االطــاع علــى كتــاب شــعبة التحريــات‬\n‫والبحــث اجلنائــي رقــم(‪ ).......‬وتاريخ‪........‬ه ـ املتضمــن أن املدعــى عليــه‬\n‫ســيء الســلوك وكثيــر التجــول يف آخــر الليــل ا‪.‬ه ـ وبعرضــه علــى املدعى‬\n‫ا ‪ :‬مــا ذكــر يف التقريــر غير صحيح فأنــا أعمل أعمال‬           ‫عليــه أجــاب قائـ ً‬\n‫حــرة أتــرزق مــن ورائهــا وعنــد الســاعة الثانيــة عشــرة أكــون يف املنــزل‬\n‫هكــذا قــرر كمــا جــرى االطــاع علــى محاضــر املواجهــة بــن املدعــى‬\n‫عليــه وبــن صاحــب احلــق اخلــاص وشــاهده املتضمنــة ظهــور قــوة موقــف‬\n‫األخيريــن وضعــف جانــب املدعــى عليــه وبعــرض ذلــك علــى املدعــى عليــه‬\n‫ا ‪ :‬مــا ذكــر يف احملاضــر غيــر صحيــح فأنــا لــم أخــف مــن‬        ‫أجــاب قائ ـ ً‬\n‫أي شــيء وإذا كان أخــي قــد ســرق البضاعــة فــا علــم‬        ‫أحــد ولــم أســرق َّ‬\n               ‫ـأن أخــي صاحــب ســوابق هكــذا قــرر‬    ‫لــي بذلــك مــع علمــه بـ َّ‬\n‫كمــا جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمــن عــدم‬\n‫وجــود ســوابق علــى املدعــى عليــه كمــا جــرى االطــاع علــى مذكــرة‬\n‫ـاء علــى‬‫إيقــاف املدعــى عليــه املتضمنــة أنــه أوقــف بتاريــخ‪ ......‬ه ـ فبنـ ً‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه‬\n‫أن‬\n ‫والتأكــد مــن أهليتــه وبعــد دراســة أوراق املعاملــة ودراســتها ومبــا َّ‬\n‫املدعــى عليــه أنكــر دعــوى املدعــي العــام باتهامــه بســرقة ســيارة الوافــد‬\n‫‪ .......‬مــن نــوع وإحــداث تلفيــات بهــا تقــدر مببلــغ ثمانيــة آالف وثمامنائــة‬\n‫وخمســن ريــا ًال والتصــرف مبــا كانــت حتويــه مــن بضاعــة كماليــات‬\n‫تقــدر قيمتهــا بســتة وخمســن ألــف وســتمائة وثالثــة وعشــرين ريــا ًال وال‬\n‫بينــة للمدعــي العــام علــى ذلــك ممــا يســتوجب عــدم إثبــات إدانــة املدعــى‬\n‫عليــه بذلــك ومبــا أ َّنــه يتهــم بذلــك ويــدلُّ لــه وجــود البضاعــة املســروقة‬\n‫معــه وأخذهــا مــن أخيــه مــع علمــه بأ َّنــه صاحــب ســوابق وشــهادة الشــاهد‬\n\n\n                                                                                        ‫‪190‬‬\n\f      ‫أن مــا‬    ‫املذكــورة ومحاضــر املواجهــة وتقريــر البحــث اجلنائــي ومبــا َّ‬\n      ‫ض َب ْعـ َـد‬  ‫ال ْر ِ‬‫{و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬      ‫يتهــم بــه مــن احملــرم شــرع ًا قــال تعالــى ‪َ :‬‬\n      ‫الل ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن } وقــال‬    ‫{وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n                                                                                        ‫ِإ ْص َلحِ َهــا } وقــال تعالــى ‪َ :‬‬\n      ‫دم ـ ُه وما ُل ـ ُه‬ ‫ـرام ُ‬\n                               ‫صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم حـ ٌ‬\n      ‫َكـ ْـم‬  ‫كـ ْـم َو َأ ْم َوال ُ‬\n                                    ‫‪((:‬فـ ِإ َّن د َِم َاء ُ‬\n                                                        ‫وعرضــه)) وقــال عليــه الصــاة والســام َ‬                              ‫ُ‬\n      ‫ك ْم‬    ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬        ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬  ‫كـ ْـم َ‬ ‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬‫اض ُ‬  ‫َو َأ ْع َر َ‬\n      ‫كـ ْـم َهـ َـذا )) وقــال عليــه الصــاة والســام ‪َ (( :‬أال ِإ َّن‬                                       ‫َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬\n      ‫ـس َي ِحــلُّ لِ ُْسـل ٍِم مِ ــنْ َأخِ يـ ِه َشـ ْـي ٌء ِإال َمــا َحــلَّ َلـ ُه‬  ‫ْال ُْسـل َِم َأ ُخــو ْال ُْسـل ِِم ‪َ ،‬ف َل ْيـ َ‬\n      ‫مِ ــنْ ن َْف ِسـ ِه )) ممــا يســتوجب تعزيــر املدعــى عليــه لــذا كلــه وألجــل احلــق‬\n      ‫ـدي إدانــة‬    ‫العــام حكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬أو ًال ‪ /‬لــم يثبــت لـ َّ‬\n      ‫املدعــى عليــه بســرقة ســيارة الوافــد ‪ ......‬مــن نــوع‪ .......‬وإحــداث تلفيــات‬\n      ‫بهــا تقــدر مببلــغ ثمانيــة آالف وثمامنائــة وخمســون ريــال والتصــرف مبــا‬\n      ‫كانــت حتويــه مــن بضاعــة كماليــات تقــدر قيمتهــا بســتة وخمســن‬\n                                      ‫ألــف وســتمائة وثالثــة وعشــرين ريــا ًال وقـ ُ‬\n      ‫ـررت ر َّد دعــوى املدعــي العــام‬\n      ‫بإثبــات إدانــة املدعــى عليــه بذلــك ‪ .‬ثاني ـ ًا ‪ /‬يعــزر ألجــل التهمــة بســجنه‬\n      ‫ملــدة ســبعة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة وبجلــده مائــة‬\n      ‫مفرقــة علــى ثــاث دفعــات كل دفعــة خمســون جلــدة‬         ‫وخمســن جلــدة َّ‬\n      ‫وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام‪ .‬ثالثـ ًا ‪ /‬يؤخــذ عليه‬\n      ‫التعهــد بعــدم العــودة ملثــل مــا يتهــم بــه وبتــاوة احلكــم علــى الطرفــن‬\n      ‫وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر القناعــة بــه وطلــب‬\n      ‫املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف دون‬\n      ‫الئحــة اعتراضيــة مكتفيـ ًا مبــا ورد يف الئحــة الدعــوى وأقفلــت اجللســة‬\n      ‫الســاعة احلاديــة عشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد‬\n\n\n‫‪191‬‬\n\f                    ‫وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1433/11/21‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء برقــم ‪........‬‬\n‫وتاريــخ ‪.......‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪ ......‬وتاريــخ ‪.......‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪...........‬‬\n‫املســجل برقــم ‪ .........‬وتاريــخ ‪.........‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n‫ضــد‪ .............../‬يف قضيــة ســرقة وقــد تضمــن القــرار حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                             ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪ .....‬ه ـ‬\n\n\n\n\n                                                                                           ‫‪192‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":183,"source_page_end":192,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f490f597a1dcf47106383663695a001551885baee45a290152614454217e7332","normalized_text_hash":"a32849798432aad2ef105c18ee98f021f441fbcf9dd9efa310b771cc92f56e33","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p183-3344793"},{"id":"27d0e83d-75fe-518c-bdbc-ef9c51076f57","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -مشاركة آخر يف السرقة -تستر على أحد اجلناة -تعزير بالقرائن -تغيير لوحة سيارة مسروقة -مشروعية التعزير بالقرائن -تعزير بالسجن واجللد -التوصية باإلبعاد.","document_number":"3433183","case_number":"33604661","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"سرقة -سرقة سيارة -مشاركة آخر يف السرقة -تستر على أحد اجلناة -تعزير بالقرائن -تغيير لوحة سيارة مسروقة -مشروعية التعزير بالقرائن -تعزير بالسجن واجللد -التوصية باإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"          ‫رقم الصك ‪ 3433183:‬تاريخه ‪1434/2/9:‬هـ‬\n                          ‫رقم الدعوى ‪33604661:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34201241‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬مشــاركة آخــر يف الســرقة ‪ -‬تســتر علــى أحــد‬\n      ‫اجلنــاة ‪ -‬تعزيــر بالقرائــن ‪ -‬تغييــر لوحــة ســيارة مســروقة ‪ -‬مشــروعية‬\n         ‫التعزيــر بالقرائــن ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬التوصيــة باإلبعــاد‪.‬‬\n\n\n\n\n      ‫ا يف تهمــة رواه أبــو داود‬\n                                ‫‪-1‬حبــس النبــي صلــى اهلل عليــه وســلم رج ـ ً‬\n                                            ‫والترمــذي وقــال حديــث صحيــح‪.‬‬\n                                                 ‫‪-2‬مشروعية التعزير بالقرائن‪.‬‬\n                                                               ‫‪-3‬األصل البراءة‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد مقيــم يعمــل يف ورشــة بســرقة ســيارتني مت‬\n      ‫وصفهــا‪ ،‬وســرقة لوحــة ســيارة مبشــاركة أشــخاص آخريــن تســتر‬\n      ‫عليهــم‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكم عليــه بعقوبة‬\n      ‫تعزيريــة‪ ،‬وقــد قبــض علــى املدعــى عليــه بعــد بالغــات بســرقة ســيارات‬\n      ‫عثــر عليهــا يف ورشــة يعمــل بهــا املدعــى عليــه‪ ،‬لكــن أنكــر املدعــى‬\n      ‫عليــه وذكــر أنــه مت القبــض عليــه لوجــود ســيارة يف الورشــة التــي يعمــل‬\n      ‫بهــا أحضرهــا لــه شــخص آخــر لــم يكــن يعلــم أن الســيارة مســروقة إال‬\n      ‫بعــد القبــض عليــه‪ ،‬ونظــر ًا لوجــود القرائــن الدالــة علــى صحــة الدعــوى‬\n\n‫‪193‬‬\n\f‫ومنهــا أن الورشــة خاصــة بإصــاح ســيارات الشــركة التــي يعمــل‬\n‫بهــا املدعــى عليــه وتناقــض أقــوال املدعــى عليــه لــدى جهــة التحقيــق‬\n‫ومخالفــة العــرف‪ ،‬وملشــروعية التعزيــر بالقرائــن فقــد مت احلكــم عليــه‬\n‫بالســجن واجللــد والتوصيــة باإلبعــاد عــن البــاد ومت تصديــق احلكــم مــن‬\n                                                      ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ 1433/10/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ ........‬وتاريــخ ‪ 1433/10/16‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق‪ 1434/01/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 15‬وفيهــا قــدم‬\n‫املدعــي العــام الئحــة دعــوى عامــة ضــد ‪ 22 ....‬ســنة أفغانــي اجلنســية‬\n‫مبوجــب رخصــة اإلقامــة رقــم (‪ )...‬أوقــف بتاريــخ ‪1433/6/17‬ه ـ وأحيــل‬\n‫إلــى الســجن العــام مبوجــب أمــر اإلحالــة رقــم ‪ ....‬وتاريــخ ‪1433/6/30‬ه ـ‬\n‫اســتناد ًا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة حيــث أنــه‬\n‫بتاريــخ ‪1433/6/17‬ه ـ أبلــغ املواطــن ‪ ........‬مالــك مؤسســة ‪ ......‬لتأجيــر‬\n‫الســيارات مركــز شــرطة ‪ ....‬عــن تعــرض الســيارة التابعــة ملؤسســته مــن‬\n‫نــوع ‪ ......‬حتمــل اللوحــة رقــم (‪ ).... ...‬للســرقة مــن أمــام املؤسســة بحــي‬\n‫الــ‪ .....‬وبتاريــخ ‪1433/6/17‬ه ـ ورد ملركــز شــرطة ‪ .....‬خطــاب مديــر‬\n‫مركــز شــرطة ‪ ....‬رقــم ‪ ....‬يف ‪1433/6/17‬ه ـ املتضمــن بــاغ‪..........‬‬\n‫الوكيــل الشــرعي عــن مؤسســة ‪ .....‬لتأجيــر الســيارة عــن تعــرض ســيارة‬\n‫املؤسســة مــن نــوع ‪ .....‬لوحــة رقــم (‪ ).... ...‬للســرقة مــن أمــام مكتــب‬\n\n                                                                                     ‫‪194‬‬\n\f      ‫املؤسســة الواقــع بحــي الــ‪ ....‬وبعــد تتبعهــا مــن قبــل منــدوب املؤسســة‬\n      ‫بواســطة شــريحة تتبــع ســبق أن مت وضعهــا يف الســيارة قبــل ســرقتها‬\n      ‫مت العثــور عليهــا يف إحــدى الــورش اخلاصــة بســيارات األجــرة العامــة‬\n      ‫بحــي ‪ .....‬فتــم التنســيق مــع دوريــات األمــن والقبــض علــى املدعــى عليــه‬\n      ‫والــذي يعمــل بنفــس الورشــة وهــو يقــوم بفــك بعــض القطــع مــن املركبــة‬\n      ‫املســتبدل لوحاتهــا بلوحــات غيــر عائــدة لهــا حتمــل رقــم (‪ ).......‬وبتاريــخ‬\n      ‫ا عــن‬ ‫‪1432/4/28‬ه ـ حضــر ملركــز شــرطة ‪ ........ /.....‬بصفتــه وكيـ ً‬\n      ‫شــركة الــ‪ ....‬مبلغــا عــن فقــدان لوحــة ســيارة ‪ .......‬حتمــل الرقــم (‪).......‬‬\n      ‫وباســتجواب املدعــى عليــه أفــاد أن الســيارة ‪ ...‬ذات الرقــم (‪ ).......‬عثــر‬\n      ‫عليهــا داخــل الورشــة التــي يعمــل بهــا وأن شــخص ســوداني ال يعرفــه‬\n      ‫أحضرهــا لــه وطلــب منــه إصالحهــا وقــد أســفر التحقيــق عــن توجيــه‬\n      ‫االتهــام للمدعــى عليــه بســرقة ســيارتني األولــى مــن نــوع ‪ ....‬لوحــة رقــم‬\n      ‫(‪ ).......‬والثانيــة مــن نــوع ‪ ......‬رقــم (‪ ).......‬وســرقة لوحــة حتمــل الرقــم‬\n      ‫‪ .......‬مبشــاركة أشــخاص تســتر عليهــم وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                             ‫‪1‬ـ اعترافه املصدق شرع ًا املدون لفة رقم (‪ )9‬ص (‪.)8‬‬\n                                  ‫‪2‬ـ ما جاء يف محضر القبض املرفق لفة رقم (‪.)7‬‬\n      ‫‪3‬ـ تبريــر املدعــى عليــه بــأن الســيارة مت إحضارهــا لــه مــن قبــل شــخص‬\n                                  ‫ســوداني دون أي عنــوان أو اســم أو الداللــة عليــه‪.‬‬\n      ‫‪4‬ـ العثــور علــى الســيارة الثانيــة املســروقة بجــوار الورشــة التــي يعمــل بهــا‬\n                                         ‫املدعــى عليــه يــدل علــى ضلوعــه يف ســرقتها‪.‬‬\n      ‫‪5‬ـ العثــور علــى لوحــة مســروقة مركبــة علــى الســيارة املســروقة يــدل‬\n      ‫علــى ضلــوع املدعــى عليــه يف ســرقة اللوحــة‪ .‬وبالبحــث عــن ســوابقه لــم‬\n                                                  ‫يعثــر لــه علــى ســوابق حتــى تاريخــه‪.‬‬\n\n\n‫‪195‬‬\n\f‫وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫اطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره‬\n‫وتــردع غيــره‪ .‬وبــاهلل التوفيــق وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n‫قائــا إن مــا ذكــره املدعــي العــام مــن وجــود ســيارة ‪ ...‬داخــل الورشــة‬\n‫التــي أعمــل فيهــا صحيــح وقــد مت القبــض علــي وعلمــت بعــد القبــض أن‬\n‫هــذه الســيارة مســروقة وقــد أحضرهــا لــي شــخص ســوداني زبــون عنــدي‬\n‫ولــم أكــن موجــود ًا حــن أحضرهــا وقــام بإدخالهــا للورشــة ثــم حضــر لي‬\n‫بعــد ذلــك وطلــب منــي إصــاح الســيارة ولــم أكــن أعلــم أنهــا مســروقة‬\n‫ولــم أشــترك يف ســرقتها هكــذا أجــاب وباالطــاع علــى إقــراره املصــدق‬\n‫شــرع ًا املــدون علــى ص ‪ 8‬لفــة ( ‪ ) 9‬ألفيــت متضمن ـ ًا قولــه إن شــخص ًا‬\n‫ســوداني ًا أحضــر لــه الســيارة ‪ ....‬لوحــة ( ‪ ).... ...‬وأن املدعــى عليــه قــام‬\n‫بإدخالهــا الورشــة دون علــم صاحــب الورشــة إلصالحهــا وأن لــم يفــك‬\n‫الســيارة ولــم ينــزل لوحتهــا أ ‪ .‬ه ـ بتصــرف وبعــرض عليــه قــال الصحيــح‬\n‫مــا ذكــرت يف مجلــس احلكــم علم ـ ًا أن أحــد لوحتــي الســيارة مفقــودة‬\n‫ثــم جــرى ســؤاله هــل الورشــة خاصــة فقــال نعــم هــي خاصــة مبكتــب‬\n‫ال‪ ...‬لتأجيــر الســيارات وال تصلــح فيهــا غيــر ســيارات املكتــب ثــم جــرى‬\n‫عــرض قولــه املــدون علــى ص ‪ 13‬لفــة ( ‪ ) 1‬أنــه ال يعــرف الســوداني بينمــا‬\n‫ذكــر يف مجلــس احلكــم أنــه مــن زبائنــه فقــال ال هــو زبــون هكــذا‬\n‫أجــاب فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n‫بعلمــه بســرقة الســيارة التــي يف ورشــته بعــد القبــض عليــه وألن األصــل‬\n‫البــراءة ولقيــام القرائــن الدالــة علــى تعاونــه يف الســرقة إمــا مشــاركة أو‬\n‫تواطــؤ ًا بالتســتر وهــي وجــود الســيارة يف ورشــته التــي أقــر أنهــا خاصــة‬\n‫بســيارات الشــركة التــي وتناقضــه يف معرفــة مــن يدعــي أنــه أحضرهــا‬\n\n\n                                                                                      ‫‪196‬‬\n\f      ‫وتناقضــه يف ذكــر مــن أدخلهــا الورشــة وإقــراره بعــدم وجــود أحــد‬\n      ‫لوحتيهــا ومخالفــة العــرف يف عــدم معرفــة عنــوان مــن يحضــر الســيارة‬\n      ‫لإلصــاح وملشــروعية التعزيــر بالقرائــن كمــا حبــس النبــي صلــى اهلل‬\n      ‫ا يف تهمــة رواه أبــو داود والترمــذي وقــال حســن صحيــح‬       ‫عليــه وســلم رجـ ً‬\n      ‫وألن محضــر القبــض املذكــور لــم يتضمــن إال وجــود ســيارة واحــدة‬\n      ‫فإنــه لــم يثبــت لــدي إدانــة املدعــى عليــه مبــا جــاء يف الدعــوى وإمنــا قامــت‬\n      ‫القرائــن علــى اتهامــه بســرقة ســيارة وتغييــر لوحتهــا وحكمــت عليــه‬\n      ‫لقــاء ذلــك بســجنه ثمانيــة أشــهر تبــدأ مــن تاريــخ اإليقــاف وجلــده مائــة‬\n      ‫وعشــرين جلــدة أمــام النــاس مفرقــة علــى دفعتــن كل دفعة ســتون جلدة‬\n      ‫وبينهمــا عشــرة أيــام وأوصــي بإبعــاده عــن البــاد بعــد تصفيــة مــا لــه ومــا‬\n      ‫عليــه مــن حقــوق وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة واملدعــي‬\n      ‫العــام االعتــراض مكتفيــا بالئحــة الدعــوى وكان النطــق باحلكــم يف‬\n      ‫‪ 1434 / 1 / 25‬ه ـ وأغلقــت اجللســة الســاعة احلاديــة عشــرة وعليــه جــرى‬\n             ‫التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده ‪...‬وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ ..........‬وتاريــخ ‪/4/1‬‬\n      ‫‪1434‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n      ‫الشــيخ ‪ ......... /‬املســجل برقــم‪ .......‬وتاريــخ ‪1434/2/9‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪( ...../‬أفغانــي اجلنســية) يف قضيــة ســرقة‬\n      ‫ســيارة علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل بــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قــررت الدائــرة باألكثريــة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه‬\n\n\n‫‪197‬‬\n\f‫إلــى إضافــة أن املدعــى عليــه يتحــدث العربيــة بالضبــط والقــرار قبــل‬\n‫بعــث املعاملــة جلهــة التنفيــذ ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                 ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪198‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":193,"source_page_end":198,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e46151ef4a35f4b447ed13ce80ede122b1bb4cb2f1b8efcbb4aac418b3fed132","normalized_text_hash":"3d815496c5fda2e9a989ac715ada8e723d111e0cabdaf6aac47857cc0b2c8e4b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p193-3433183"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"ef6d7863-d4a0-554a-8291-cfd9446c5d15","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة حقيبة من داخل سيارة مشتملة على أوراق رسمية -حتليل عينة دم املدعى عليه -تطابق أمناط وراثية -محضر انتقال ومعاينة -وجود سوابق على املدعى عليه -عدم تداخل العقوبات -عدم انطباق حكم حد السرقة إذا لم يكن املسروق ماال- كسر زجاج سيارة.","document_number":"3461346","case_number":"33591190","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/14","year":"1434","subject":"سرقة -سرقة حقيبة من داخل سيارة مشتملة على أوراق رسمية -حتليل عينة دم املدعى عليه -تطابق أمناط وراثية -محضر انتقال ومعاينة -وجود سوابق على املدعى عليه -عدم تداخل العقوبات -عدم انطباق حكم حد السرقة إذا لم يكن املسروق ماال- كسر زجاج سيارة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك ‪ 3461346 :‬تاريخه ‪1434/3/14:‬هـ‬\n                          ‫رقم الدعوى ‪33591190 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34353817‬تاريخه ‪1434/11/09 :‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة حقيبــة مــن داخــل ســيارة مشــتملة علــى أوراق رســمية‬\n      ‫‪ -‬حتليــل عينــة دم املدعــى عليــه ‪ -‬تطابــق أمنــاط وراثيــة ‪ -‬محضــر‬\n      ‫انتقــال ومعاينــة ‪ -‬وجــود ســوابق علــى املدعــى عليــه ‪ -‬عــدم تداخــل‬\n      ‫العقوبــات ‪ -‬عــدم انطبــاق حكــم حــد الســرقة إذا لــم يكــن املســروق مــاالً‪-‬‬\n                                                                 ‫كســر زجــاج ســيارة‪.‬‬\n\n\n\n\n               ‫إذا لم يكن املسروق ما ًال فال تنطبق عليه أحكام حد السرقة ‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بكســر زجــاج ســيارة وســرقة‬\n      ‫حقيبــة حتتــوي أوراقـ ًا رســمية وبطاقــات أحــوال ‪ ،‬وطلــب املدعــي العــام‬\n      ‫إثبــات إدانتــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ ،‬قبــض علــى املدعــى عليــه‬\n      ‫بعــد إدانتــه يف قضيــة ســرقة وبتحليــل عينــة مــن دمــه أثبتــت الفحوصــات‬\n      ‫الوراثيــة تطابــق األمنــاط الوراثيــة لعينــة دم املدعــى عليــه ‪ ،‬وقــد أقــر‬\n      ‫املدعــى عليــه بالدعــوى وتبــن وجــود ســوابق قضائيــة علــى املدعــى‬\n      ‫عليــه‪ ،‬ولــم تنطبــق أحــكام حــد الســرقة علــى املســروق إذا لــم يكــن‬\n      ‫مــا ًال ‪ ،‬لــذا حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد ‪،‬‬\n                                ‫ومت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n‫‪145‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33591190‬وتاريخ ‪1433/10/09‬هـ الـمقـي ــدة‬\n‫بالـمـحـكـم ــة بـرق ـ ــم ‪ 331769804‬وتــاري ـ ــخ ‪1433/10/09‬ه ـ فـف ــي‬\n‫يـ ــوم االثـن ــن الـمـواف ــق ‪1434/02/25‬ه ـ افـتـت ـحـ ــت اجلـل ـسـ ــة السـاعـ ــة‬\n‫‪ 01 : 00‬وفيهــا حضــر املدعــي العــام ‪ .....‬وادعــى علــى ‪ 27،........‬عامــا‪،‬‬\n‫ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي رقــم (‪ ).........‬أوقــف بتاريــخ‬\n‫‪1433/2/22‬ه ـ علــى ذمــة قضيــة ســرقة وأحيــل إلــى ســجن امللــز مبوجب‬\n‫أمــر التوقيــف رقــم (‪ )138‬وتاريــخ ‪1433/2/27‬ه ـ اســتناد ًا للبنــد‬\n‫خامسـ ًا مــن القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي‬\n‫علــى املــادة ( ‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة وقيــد ســجين ًا برقــم‬\n‫(‪.)..........‬قائــا يف دعــواه عليــه انــه بتاريــخ ‪1432/2/22‬ه ـ قبــض علــى‬\n‫املدعــى عليــه مــن قبــل إحــدى فــرق الدوريــات األمنيــة التهامــه بالســرقة‬\n‫مــن داخــل ســيارة حتمــل اللوحــة رقــم ( ‪] ).......‬صــدر بحقــه الئحــة دعــوى‬\n‫عامــة وأحيلــت إلــى احملكمــة اجلزئية بالريــاض باخلطاب رقم (‪)46029‬‬\n‫وتاريــخ ‪1433/4/20‬ه ـ [‪ ،‬وبتحليــل عينــة دمــه أثبــت تقريــر الفحــوص‬\n‫الوراثيــة رقــم (‪11-910‬فحــوص وراثيــة لعــام ‪1433‬هــ) تطابــق األمنــاط‬\n‫الوراثيــة لعينــة دم املدعــى عليــه مــع عينــة مســحة دم رفعــت مــن املقعــد‬\n‫اخللفــي األميــن للســيارة حتمــل اللوحــة رقــم (‪ ).... ...‬العائــدة لــ‪ ......‬واملعمــم‬\n‫عــن كســر زجاجهــا وســرقة حقيبــة بداخلهــا عــدد (‪ )3‬جــوازات ســفر‬\n‫إحداهــا عائــد للــ‪ ......‬وعــدد (‪ )3‬بطاقــات أحــوال عائــدة ‪ .....‬ووالدتــه‬\n\n                                                                                             ‫‪146‬‬\n\f      ‫وابنــه وصــورة دفتــر عائلــة ‪ .....‬مطبوعــات رســمية لــ‪ .....‬وأوراق متنوعــة‬\n      ‫تابعــة ملكتــب ‪ ......‬وبســماع أقــوال املبلــغ ‪« .......‬ســوري اجلنســية» مبوجــب‬\n      ‫رخصــة اإلقامــة رقــم (‪ ).......‬يعمــل حتــت كفالــة ‪ .....‬أفــاد أنــه أوقــف‬\n      ‫الســيارة التــي بقيادتــه حتمــل اللوحــة رقــم (‪ ).......‬العائــدة ملكيتهــا‬\n      ‫ل ــ‪ ......‬أمــام شــقته وبعــد نومــه طــرق عليــه جــاره البــاب وأخبــره بــأن‬\n      ‫الســيارة تعرضــت لكســر الزجــاج األميــن اخللفــي واتضــح أنــه ســرق منهــا‬\n      ‫عــدد (‪ )3‬جــوازات ســفر إحداهــا عائــد لــ‪ .....‬وعــدد (‪ )3‬بطاقــات أحــوال‬\n      ‫عائــدة لــ‪ .....‬ووالدتــه وابنــه وصــورة دفتــر عائلــة ‪ .....‬مطبوعــات رســمية‬\n      ‫لــ‪ .....‬وأوراق متنوعــة تابعــة ملكتــب ‪ ......‬وباالنتقــال للموقــع ملعاينــة‬\n      ‫الســيارة حتمــل اللوحــة رقــم (‪ )............‬اتضــح تعــرض الزجــاج اخللفــي‬\n      ‫األميــن للكســر والزجــاج متناثــر علــى املرتبــة ووجــدت بقعــة دم علــى‬\n      ‫املرتبــة وكذلــك الــدرج األمامــي مفتــوح ومت رفــع اآلثــار مــن قبــل األدلــة‬\n      ‫اجلنائيــة‪ .‬وباســتجوابه أقــر أنــه أثنــاء مــروره وبقيادتــه ســيارة مــن نــوع‬\n      ‫بأحــد الشــوارع توقــف بجانــب ســيارته فشــاهد بداخــل الســيارة حقيبــة‬\n      ‫ســوداء فأخــرج مــن ســيارته مفــك العجــات وكســر الزجــاج األميــن‬\n      ‫وســرق احلقيبــة وعثــر بداخلهــا علــى أوراق رســمية عائــدة ل ـ ‪......‬وصــور‬\n      ‫بطاقــات ‪ .....‬ووالدتــه وابنــه وجــواز ســفر وبطاقــة عائلــة ‪.....‬وقــام برميهــا‬\n      ‫يف أحــد أوعيــة النفايــات وصــادق علــى ذلــك شــرع ًا ‪ .‬وقد أســفر التحقيق‬\n      ‫عــن اتهــام املدعــى عليــه بكســر زجــاج ســيارة عائــدة لـ ـ ‪ ......‬وســرقة‬\n      ‫حقيبــة حتــوي أوراق رســمية وبطاقــات أحــوال وجــوازات ســفر ‪ ،‬وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ :‬أوالً‪ :‬مــا جــاء إقــرار املصــدق شــرع ًا املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )15‬مــن ملــف التحقيــق رقــم (‪.)1‬ثانيـ ًا ‪ :‬مــا تضمنــه‬\n      ‫تقريــر الفحــوص الوراثيــة رقــم (‪ /11-910‬فحــوص وراثيــة ‪1433/‬ه ـ )‬\n\n\n‫‪147‬‬\n\f‫واملرفــق علــى اللفــات رقــم (‪.)18-16‬ثالثـاً‪ :‬مــا جــاء يف محضــر االنتقــال‬\n‫واملعاينــة املــدون علــى الصفحتــن رقــم (‪ )3-2‬مــن دفتــر التحقيــق املرفــق‬\n‫لفــة رقــم (‪ .)1‬رابعـاً‪ :‬مــا جــاء يف احملضــر املعــد مــن قبــل الفرقــة املرفــق‬\n‫علــى اللفــة رقــم (‪ .)7‬وببحــث ســوابقه اتضــح وجــود أربــع ســوابق اثنتــان‬\n‫منهــا حيــازة مخــدرات اقترنــت إحداهــا باســتعمال املخــدرات والثالثــة‬\n‫شــرب املســكرات والرابعــة ســرقة ســيارات مســجلة عليــه حتــى تاريخه‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة بليغــة زاجــرة‬\n‫لــه رادعــة لغيــره لقــاء مــا أســند إليــه والتشــديد عليــه مبــا يردعــه لقــاء‬\n‫ذلــك ولعــدم ارتداعــه مــن عقوبــات ســوابقه ((علم ـ ًا بــأن احلــق اخلــاص‬\n‫مــازال قائمـاً)) ‪ .‬وبــاهلل التوفيــق‪ .‬أ ه ـ ‪ .‬وبعــرض دعــوى املدعــي العام على‬\n‫املدعــى عليــه ‪ _ ...........‬ســعودي بالهويــة رقــم ‪ .....‬اجــاب قائــا مــا جــاء‬\n‫يف دعــوى املدعــي العــام كلــه صحيــح فقــد قمــت بكســر زجــاج ســيارة‬\n‫مــن نــوع ‪ .....‬ووجــدت بداخلهــا كيــس بداخلــه اوراق رســمية فأخذتــه‬\n‫وملــا لــم أجــد فيــه مبالــغ ماليــة قمــت برميــه يف برميــل النفايــات والســوابق‬\n‫املذكــورة يف دعــوى املدعــي العــام صحيحــه وقــد نلــت عقابــي عليهــا‬\n‫هكــذا أجــاب‪ .‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وحيــث‬\n‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام وحيــث ان املســروق ليــس‬\n‫مــاال فــا تنطبــق عليــه أحــكام حــد الســرقة وألن مــا قــام بــه املدعــى‬\n‫عليــه جــرم عظيــم يوجــب تعزيــره ‪ .‬فعليــه فقــد ثبــت لــدي قيــام املدعــى‬\n‫عليــه بكســر زجــاج ســيارة واخــذ كيــس بداخلــه أوراق رســمية وقــررت‬\n‫تعزيــره لقــاء ذلــك بســجنه ثــاث ســنوات مــن تاريــخ ايقافــه وجلــده‬\n‫ثالثمائــة جلــده مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــده بــن‬\n\n\n                                                                                         ‫‪148‬‬\n\f      ‫كل دفعــة واخــرى عشــرة ايــام وبذلــك حكمــت ‪ .‬وبعرضــه علــى املدعــي‬\n      ‫العــام قــرر االعتــراض مكتفيــا بالئحــة الدعــوى امــا املدعــى عليــه فقــد‬\n      ‫قــرر القناعــة باحلكــم‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫ويف يــوم األحــد ‪1434/6/11‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫العــام وحضــر حلضــوره املدعــى عليــه ‪ ....‬وقــد عــادت املعاملــة حملكمــة‬\n      ‫االســتئناف وبرفقهــا القــرار رقــم ‪ 34205524‬وتاريــخ ‪1434/5/5‬ه ـ‬\n      ‫ونــص احلاجــة منــه‪ :‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قررنــا إعادتهــا ملالحظــة االتــي‪ :‬جــاء يف دعــوى املدعــي العــام قوله (صدر‬\n      ‫بحقــه) اي بحــق املدعــى عليــه دعــوى عامــة وأحيلــت الــى احملكمــة‬\n      ‫اجلزئيــة بالريــاض باخلطــاب رقــم (‪ )46029‬وتاريــخ ‪1434/4/20‬ه ـ فهــل‬\n      ‫مــا صــدر بحقــه هــو يف نفــس هــذه الدعــوى او غيرهــا علــى فضيلتــه‬\n      ‫التحقــق مــن ذلــك فــإن كانــت هــي نفــس هــذه الدعــوى بوقائعهــا وزمنهــا‬\n      ‫فمــا وجــه تكــرار الدعــوى عليــه ‪.‬أ ه ـ ‪ .‬فعليــه اجيــب اصحــاب الفضيلــة‬\n      ‫بأنــه جــرى الكتابــة إلدارة احملكمــة عــن ذلــك فاتضــح بــأن القضيــة‬\n      ‫املذكــورة يف القــرار احيلــت للمكتــب القضائــي رقــم ‪ 26‬وصــدرت‬\n      ‫حملكمــة االســتئناف برقــم ‪ 33/772795‬يف ‪1433/6/1‬ه ـ وبســؤال‬\n      ‫املدعــى عليــه عــن ذلــك قــال نعــم لقــد حكمــت يف قضيــة ســرقة ســيارة‬\n      ‫نــوع ‪ .....‬يف املكتــب القضائــي رقــم ‪ .....‬لــدى الشــيخ ‪ .....‬هكــذا‬\n      ‫اجــاب‪ .‬وبعــرض ذلــك علــى املدعــي العــام أجــاب بقولــه ان دعــواي يف‬\n      ‫ســرقة ســيارة نــوع والعائــدة ‪ .....‬هكــذا أجــاب‪ .‬فعليــه فلــم يظهــر لــي ان‬\n      ‫مــا حكــم بــه علــى املدعــى عليــه يف القضيــة املنظــورة لــدي لــه عالقــة‬\n      ‫بالقضيــة التــي باملكتــب القضائــي رقــم ‪ .....‬لكــون املدعــى عليــه قــام‬\n      ‫بســرقتني لســيارتني كل ســرقة واقعــة ومنفصلــة عــن االخــرى فأمــرت‬\n\n\n‫‪149‬‬\n\f‫بإحلــاق ذلــك يف القــرار وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫االجــراء حســب املتبــع ‪.‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫ويف يــوم االثنــن ‪1434/8/8‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34267458‬يف‬\n‫‪1434/7/12‬ه ـ ونــص احلاجــة منــه‪ :‬وحيــث ســبق دراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة وباالطــاع علــي مــا أجاب به فضيلته علي قرارنا‬\n‫رقــم ‪ 34205524‬وتاريــخ ‪1434/5/5‬ه ـ لوحــظ مــا يلــي ذكــر املدعــى‬\n‫عليــه أنــه حكــم عليــه قبــل هــذه القضيــة يف قضيــة ســرقة وصــدرت‬\n‫قضيتــه حملكمــة االســتئناف برقــم ‪ 772795/33‬وتاريــخ ‪1433/6/1‬هـ‬\n‫وقــد جعــل فضيلتــه بدايــة ســجن املدعــى عليــه يف هــذه القضيــة التــي بــن‬\n‫يديــه مــن تاريــخ توقيفــه مــع أن املدعــي عليــه محكــوم عليــه يف قضيــة‬\n‫ســرقة ســابقا ولــم يتحقــق فضيلتــه مــن صفــة احلكــم الســابق حتــي ال‬\n‫تتدخــل عقوبــة الســجن يف هــذه القضيــة مــع القضيــة الســابقة لــو كان‬\n‫مســجونا فيهــا‪ .‬واهلل املوفــق أ ه ـ ‪ .‬فعليــه أجيــب أصحــاب الفضيلــة بأنــه‬\n‫حضــر املدعــى عليــه وجــرى ســؤاله عــن القضيــة الســابقة فأجــاب بقولــه‬\n‫لقــد حكــم علــي فضيلتــه القاضــي ‪ ....‬يف القضيــة االولــى بالســجن ملــدة‬\n‫ســنتني واجللــد ثالثمائــة جلــده هكــذا أجــاب فعليــه فقــد قــررت بــأن‬\n‫يبــدا احلكــم بســجن املدعــى عليــه يف القضيــة املنظــورة لــدي مــن تاريــخ‬\n‫انتهــاء محكوميتــه االولــى والتــي صــدر فيهــا حكمــا مــن الشــيخ ‪.....‬‬\n‫وبذلــك حكمــت وبعــرض علــي املدعــى عليــه قــرر القناعــة بذلــك ثــم‬\n‫حضــر املدعــي العــام وبعــرض ذلــك عليــه قــرر بأنــه معترضــا فأمــرت‬\n‫بإحلــاق ذلــك يف القــرار وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫حســب املتبــع‪ .‬واهلل املوفــق وصلــي اهلل وســلم علــي نبينــا محمــد‪ .‬حــرر‬\n\n\n                                                                                    ‫‪150‬‬\n\f                                                                          ‫‪1434/8/8‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد‪ .‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم ‪341858169‬‬\n      ‫وتاريــخ ‪1434/10/14‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ ‪ .......‬املســجل برقــم ‪ 3461346‬وتاريــخ‬\n      ‫‪1434/3/14‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ .....‬هويــة رقــم (‪)......‬‬\n      ‫التهامــه بقضيــة ســرقة علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وحيــث ســبق دراســة القــرار وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى‬\n      ‫قرارنــا رقــم ‪ 34205524‬وتاريــخ ‪1434/5/5‬ه ـ قررنــا املصادقــة علــى‬\n      ‫احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                   ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪151‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":145,"source_page_end":151,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0560af51d09b619ad296e98335360a29d59e33187ef7ed0bc2509cffb24a9590","normalized_text_hash":"b7d861c56ea56ae3aee6edbf36805ea10b47fc1bb861b3c9759bb46f9cbcde39","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p145-3461346"},{"id":"90f1995f-d555-5212-a9a7-14b5f17ac223","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -شروع يف سرقة أساك كهربائية -إقرار املدعى عليه - وجود سوابق قضائية على املدعى عليه -إدانة املدعى عليه بالسرقة -التعزير بالسجن واجللد -التوصية باإلبعاد عن الباد.","document_number":"3433258","case_number":"33593795","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/9","year":"1434","subject":"سرقة -شروع يف سرقة أساك كهربائية -إقرار املدعى عليه - وجود سوابق قضائية على املدعى عليه -إدانة املدعى عليه بالسرقة -التعزير بالسجن واجللد -التوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك ‪ 3433258 :‬تاريخه ‪1434/02/9:‬هـ‬\n                    ‫رقم القضية ‪33593795 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34185475‬تاريخه‪1434/04/13 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬شــروع يف ســرقة أســاك كهربائيــة ‪ -‬إقــرار املدعــى عليــه ‪-‬‬\n‫وجــود ســوابق قضائيــة علــى املدعــى عليــه ‪ -‬إدانــة املدعى عليه بالســرقة‬\n          ‫‪ -‬التعزيــر بالســجن واجللــد‪ -‬التوصيــة باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                                                        ‫املرء مؤاخذ بإقراره ‪.‬‬\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه نــازح بالشــروع يف ســرقة كيابــل مــن‬\n‫موقــع شــركة ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم‬\n‫عليــه بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد بــاغ مفــاده‬\n‫وجــود املدعــى عليــه يف إحــدى غــرف الكهربــاء حيث كان يريد ســرقة‬\n‫األســاك الكهربائيــة بعــد قطعهــا ‪،‬وقــد تضمنــت القضيــة إقــرار‬\n‫املدعــى عليــه بالدعــوى ‪ ،‬حكمــت احملكمــة بالتعزيــر بالســجن واجللــد‬\n‫والتوصيــة باإلبعــاد عــن البــاد ‪ ،‬ومت تصديــق احلكــم مــن محكمــة‬\n                                                           ‫االســتئناف‪.‬‬\n\n\n\n\n                                                                                   ‫‪152‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ 1433/10/10‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ ..........‬وتاريــخ ‪ 1433/10/10‬ه ـ ففــي يــوم األربعــاء‬\n      ‫املوافــق‪ 1434/01/21‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 15‬وفيهــا قــدم‬\n      ‫املدعــي العــام الئحــة دعــوى عامــة ضــد ‪ )30( ........... /‬عامـ ًا (نــازح) يقيم‬\n      ‫يف مدينــة الريــاض موقــوف بتاريــخ ‪1433/5/12‬ه ـ مبوجــب مذكــرة‬\n      ‫التوقيــف رقــم ‪ ....‬وتاريــخ ‪1433/6/1‬ه ـ أنــه بتاريــخ ‪1433/5/12‬ه ـ ورد‬\n      ‫ملركــز شــرطة العزيزيــة تقريــر دوريــات األمــن ‪ ....‬املتضمــن بــاغ‪...... /‬‬\n      ‫الوكيــل الشــرعي لشــركة ‪ ......‬والــذي يفيــد فيــه انــه أثنــاء تواجــده‬\n      ‫بالشــركة تفاجــأ بانقطــاع التيــار الكهربائــي وعنــد ذهابــه إلــى غرفــة‬\n      ‫الكهربــاء شــاهد شــخص بداخلهــا واتضــح أنــه املدعــى عليــه وأبلــغ‬\n      ‫دوريــات األمــن ومت القبــض عليــه وكان يرافقــه شــخص آخــر ارتكــب‬\n      ‫الفــرار وعثــر يف املوقــع علــى منشــار ومفــك ثقيــل وكشــف صغيــر جــرى‬\n      ‫اســتالمه وإيقافــه رهــن التحقيــق وباالنتقــال للموقــع اتضــح أنــه يقــع‬\n      ‫بطريــق ‪ .....‬شــركة ال‪ .....‬حيــث لوحــظ وجــود قطــع يف احــد الكيابــل‬\n      ‫التابعــة للشــركة وتبــن بأنــه الســبب يف انقطــاع التيــار اتخــذ الــازم‬\n      ‫مبعرفــة املختصــن‪ .‬وبســماع أقوالــه اعتــرف بأنــه حضــر إلــى مســتودع‬\n      ‫لغرض الســرقة للســكراب املوجود داخل املســتودع وكان معه منشــار‬\n      ‫حديــد وصــدق اعترافــه شــرع ًا بذلــك‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه‬\n      ‫االتهــام للمدعــى عليــه بالشــروع يف ســرقة كيابــل مــن شــركة ال‪......‬‬\n\n‫‪153‬‬\n\f                                                          ‫الواقعــة بطريــق اخلــرج‪.‬‬\n                                                ‫وذلك لألدلة والقرائن التالية ‪/:‬‬\n‫‪1‬ـ اعترافــه املصــدق شــرع ًا املثبــت مبلــف التحقيــق بالصفحــة رقــم ( ‪) 2‬‬\n                                            ‫مــن ملــف التحقيــق لفــه رقــم ( ‪. ) 1‬‬\n                                       ‫‪2‬ـ محضر القبض املرفق لفة رقم ( ‪.) 3‬‬\n               ‫وبالبحث عن سوابقه عثر له على سابقتني حيازة مخدرات‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫لــذا أطلــب إثبــات مــا اســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n‫ذلــك (علم ـ ًا بــأن احلــق اخلــاص مــا زال قائم ـاً) وبــاهلل التوفيــق وبعــرض‬\n‫ا إال يف‬  ‫ذلــك علــى املدعــى عليــه صــادق علــى الدعــوى جملــة وتفصي ـ ً‬\n‫وجــود شــخص آخــر معــه فقــال لــم يوجــد شــخص معــي وقــد شــرعت‬\n‫يف ســرقة كيابــل مــن الشــركة املذكــورة كمــا ورد يف الدعــوى‬\n‫فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه مبــا‬\n‫جــاء يف الدعــوى ((وألن املــرء مؤاخــذ بإقــراره)) فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بالشــروع يف ســرقة كيابــل مــن شــركة ال‪ .....‬الواقعــة‬\n‫علــى طريــق اخلــرج وحكمــت عليــه لقــاء ذلــك بســجنه أحــد عشــر‬\n‫شــهر ًا تبــدأ مــن تاريــخ اإليقــاف وجلــده مائتــي جلــدة مفرقــة علــى أربــع‬\n‫دفعــات أمــام النــاس كل دفعــة خمســون جلــدة وبــن كل دفعتني عشــرة‬\n‫أيــام وأوصــي بإبعــاده عــن البــاد بعــد تصفيــة مــا لــه وعليــه مــن حقــوق‬\n‫وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة واملدعــى العــام االعتــراض‬\n‫مكتفيــا بالئحــة الدعــوى وكان النطــق باحلكــم يف ‪1434/1/20‬ه ـ‬\n‫وأغلقــت اجللســة الســاعة العاشــرة وعليــه جــرى التوقيــع وصلــى اهلل علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                       ‫‪154‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعة‬\n      ‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقــم ‪ .....‬وتاريــخ ‪1434 /3/9‬ه ـ املرفــق‬\n      ‫بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ ‪ .......‬املســجل برقــم‬\n      ‫‪ ........‬وتاريــخ ‪1434/2/9‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪.........‬‬\n      ‫التهامــه بقضيــة ســرقة علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون بــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة قــررت الدائــرة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه أنــه‬\n      ‫البــد مــن ذكــر اســم املدعــي العــام يف أول الدعــوى ويالحــظ ذلــك‬\n      ‫ال ‪ .‬و اهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬   ‫مســتقب ً‬\n                                                                               ‫وســلم ‪.‬‬\n\n\n\n\n‫‪155‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":152,"source_page_end":155,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"00292527ddf0cb16dedc2d1908d34bc7705c2b74cb00583d11c0d870a2f4bf2d","normalized_text_hash":"eab7050e520e7630680c0f268ef01d983a522afde30e8752a3071939e99afc2a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p152-3433258"},{"id":"a3e809a4-0a19-5c29-889e-a8153299cd1b","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة أساك نحاسية -االشتراك يف سرقة أساك نحاسية -شرب املسكر -قيادة السيارة حتت تأثير املسكر -إقرار املدعى عليهما املصدق شرع ا -الرجوع عن اإلقرار بالسرقة واإلقرار بشرب املسكر -صرف النظر عن إقامة حد السرقة -التعزير بالسجن واجللد وأخذ التعهد.","document_number":"346374","case_number":"33595551","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/07","year":"1434","subject":"سرقة -سرقة أساك نحاسية -االشتراك يف سرقة أساك نحاسية -شرب املسكر -قيادة السيارة حتت تأثير املسكر -إقرار املدعى عليهما املصدق شرع ا -الرجوع عن اإلقرار بالسرقة واإلقرار بشرب املسكر -صرف النظر عن إقامة حد السرقة -التعزير بالسجن واجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 346374 :‬تاريخه ‪1434/01/07 :‬هـ‬\n                   ‫رقم الدعوى ‪33595551 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3456455‬تاريخه‪1434/03/07 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة أســاك نحاســية ‪ -‬االشــتراك يف ســرقة أســاك نحاســية‬\n‫‪ -‬شــرب املســكر ‪ -‬قيــادة الســيارة حتــت تأثيــر املســكر ‪ -‬إقــرار املدعــى‬\n‫عليهمــا املصــدق شــرع ًا ‪ -‬الرجــوع عــن اإلقــرار بالســرقة واإلقــرار بشــرب‬\n‫املســكر ‪ -‬صــرف النظــر عــن إقامــة حــد الســرقة ‪ -‬التعزيــر بالســجن‬\n                                                     ‫واجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n\n  ‫ما ذكره أهل العلم أن الرجوع عن اإلقرار شبهة يف إسقاط احلدود‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليهمــا باالشــتراك يف ســرقة أســاك‬\n‫نحاســية مــن مســتودع بعــد هتــك احلــرز و التســتر مــع شــريكهما و قيــادة‬\n‫األول الســيارة حتــت تأثيــر املســكر وهــو بحالــة غيــر طبيعيــة و اتهــام‬\n‫الثانــي باالشــتراك مــع آخــر يف ســرقة بالزمــا وجهــاز القــط مــن إحــدى‬\n‫االســتراحات‪ ،‬حيــث تقــدم أحــد األشــخاص ببــاغ للشــرطة يفيــد أن‬\n‫هنالك أربعة أشــخاص يســتقلون ســيارة قاموا بتكســير القفل اخلارجي‬\n‫للمســتودع وســرقة تســعة صناديــق أجهــزة كهربائيــة وعندمــا شــاهدوه‬\n‫هربــوا علــى الســيارة ‪ ،‬وطلــب املدعــي العــام إقامــة حــد الســرقة عليهما‪،‬‬\n‫وعقوبــة تعزيريــة لقــاء تســترهم علــى املشــاركني معهمــا‪ ،‬وإدانــة األول‬\n\n                                                                                   ‫‪156‬‬\n\f      ‫بقيــادة الســيارة حتــت تأثيــر املســكر و إفهامــه أن عقوبــة ذلــك عائــد‬\n      ‫للجهــة املختصــة‪ ،‬وقــد أنكــر املدعــى عليــه األول دعــوى املدعــي العــام‬\n      ‫واعتــرف بشــرب املســكر‪ ،‬والثانــي أنكــر مــا جــاء بدعــوى املدعــي‬\n      ‫العــام واعتــرف بشــرب املســكر فقــط‪ ،‬وعندمــا ُطلــب مــن املدعــي‬\n      ‫العــام بينتــه علــى دعــواه ذكــر إقــرار املدعــى عليهمــا املصــدق شــرع ًا‬\n      ‫واملتضمــن طبــق مــا جــاء بدعــوى املدعــي العــام و بســؤالهما عــن ذلــك‬\n      ‫دفعــا أن ذلــك كان باإلكــراه وال بينــة لهمــا علــى اإلكــراه ‪ ،‬لــذا مت‬\n      ‫احلكــم بصــرف النظــر عــن حــد الســرقة لعــدم حتقــق شــروطه ‪ ،‬وبجلــد‬\n      ‫املدعــى عليهمــا حــد املســكر ثمانــن جلــدة ‪ ،‬واحلكــم بإدانــة املدعــى‬\n      ‫عليــه األول بقيــادة ســيارة حتــت تأثيــر املســكر ‪ ،‬وإفهامــه أن عقابــه‬\n      ‫علــى ذلــك عائــد للجهــة املختصــة ‪ ،‬احلكــم بتعزيــر املدعــى عليهمــا‬\n      ‫بالســجن و اجللــد لقــاء توجــه الشــبهة بحقهمــا مبــا جــاء يف دعــوى املدعــي‬\n      ‫العــام‪ ،‬وقنــع املدعــى عليهمــا باحلكــم ‪ ،‬واملدعــي العــام قــرر اعتراضــه‬\n      ‫علــى احلكــم بــدون الئحــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن كل مــن ‪ .....‬و‪ ....‬و‪ .....‬القضــاة‬\n      ‫يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم ‪ .....‬وتاريــخ‬\n      ‫‪ .....‬املقيــدة باحملكمــة برقــم ‪ .....‬وتاريــخ ‪ ....‬ففــي يــوم اإلثنــن املوافق‪...‬‬\n      ‫افتتحــت اجللســة الســاعة ‪ 9.45‬قــدم املدعــي العــام بدائــرة التحقيــق‬\n      ‫واالدعــاء العــام ‪.....‬الئحتــه االدعائيــه ضــد كل مــن ‪ ....‬و‪.....‬واملتضمنــة‬\n      ‫مانصــه ‪.....‬إنــه بتاريــخ ‪ ....‬ورد ملركــز شــرطة امللــز تقريــر إحــدى دوريات‬\n\n‫‪157‬‬\n\f‫األمــن رقــم (‪ )....‬املتضمــن تلقيهــم بــاغ مــن غرفــة العمليــات مفــاده وجود‬\n‫ســرقة بحــي ‪ ...‬وبوصــول الفرقــة للموقــع قابلــت املبلــغ‪ .... /‬وقــد أفــاد‬\n‫الفرقــة أن أربعــة أشــخاص يســتقلون ســيارة نــوع ‪ ...‬حتمــل اللوحــة‬\n‫رقــم (‪ )....‬قامــوا بتكســير القفــل اخلارجــي للمســتودع وســرقة تســعة‬\n‫كراتــن أجهــزة كهربائيــة وعندمــا شــاهدوه هربــوا علــى الســيارة‪.‬‬\n‫ومبعاينــة املســتودع تبــن أنــه عبــارة عــن حاويــة بضائــع(‪ ).......‬بالقــرب‬\n‫مــن منــزل املبلــغ وبــه أســاك ووضــع علــى بابــه سالســل حديــد‪ .‬وبتاريــخ‬\n‫‪ .....‬حضــر ملركــز شــرطة ‪ .....‬املواطــن ‪ ....‬مخبــر ًا عــن ســرقة شاشــة‬\n‫بالزمــا (‪ )42‬بوصــة وجهــاز القــط مــن اســتراحته بحــي ‪ ......‬وباالنتقــال‬\n‫لالســتراحة اتضــح أنهــا مكونــة مــن ثــاث غــرف وقــد ســرق منهــا‬\n‫شاشــة بالزمــا‪ .‬وبتاريــخ ‪ ...26‬قبــض علــى املذكوريــن مــن قبــل وحــدة‬\n‫البحــث والتحــري وهمــا علــى الســيارة الــوارد أوصافهــا أعــاه‪ .‬وبســماع‬\n‫أقــوال املتهــم األول أقــر أنــه بتاريــخ ‪ ...‬بعــد منتصــف الليــل كان يرافقــه‬\n‫املتهــم الثانــي واملدعــو‪( ...‬فــرزت لــه أوراق مســتقلة حلــن القبــض عليــه)‬\n‫علــى ســيارته مــن نــوع ‪ ......‬وكانــا بحالــة غيــر طبيعيــة (ســكر) وأثنــاء‬\n‫جتولهــم بحــي ‪ .....‬شــاهدوا مســتودع واتفقــوا علــى ســرقته فقــام املتهــم‬\n‫الثانــي بتكســير البــاب اخلارجــي بواســطة عتلــة حديديــة ثــم دخــل‬\n‫املســتودع مــع‪ ...‬أمــا هــو فــكان بداخــل الســيارة ثــم خرجــا املتهــم الثانــي‬\n‫و‪....‬وهمــا يحمــان ثالثــة كراتــن بهــا أســاك كهربائيــة وأثنــاء ذلــك‬\n‫شــاهدوا صاحــب املســتودع فهربــوا ‪ ،‬ثــم قــام بإنــزال املســروقات بســيارة‬\n‫املتهــم الثانــي نــوع ‪ ......‬وصــادق علــى إقــراره شــرعاً‪ .‬وبســماع أقــوال‬\n‫املتهــم الثانــي أقــر أنــه بتاريــخ ‪ ....‬كان برفقــة املتهــم األول واملدعــو‪..../‬‬\n‫وكانــا بحالــة غيــر طبيعيــة علــى ســيارة املتهــم األول مــن نــوع ‪ ....‬الــوارد‬\n\n\n                                                                                        ‫‪158‬‬\n\f      ‫وصفهــا أعــاه وأثنــاء جتولهــم شــاهدوا مســتودع واتفقــوا علــى ســرقته‬\n      ‫فقــام‪ ..../‬بتكســير البــاب اخلارجــي بواســطة عتلــة حديديــة ثــم ســرقوا‬\n      ‫ثالثــة كراتــن بهــا أســاك كهربائيــة وعنــد مغادرتهــم شــاهدوا‬\n      ‫ســيارة تراقبهــم فرمــوا املســروقات بــأرض فضــاء بحــي ‪ ....‬أو ‪ .....‬وال‬\n      ‫يعلــم هــل عــاد لهــا املتهــم األول أم ال ‪ ،‬كمــا أقــر أنــه يف أحــد األيــام‬\n      ‫ورده اتصــال مــن‪ .../‬والــذي ميتهــن ســرقة االســتراحات وأخبــره بأنــه‬\n      ‫موجــود عنــد إحــدى االســتراحات بحــي ‪ .......‬فذهــب إليــه وعنــد وصولــه‬\n      ‫قــام ‪ ...‬بإخــراج شاشــه بالزمــا (‪ )42‬بوصــه مــن خلــف األشــجار ووضعهــا‬\n      ‫بســيارته ثــم ســأله عــن الشاشــة فأجابــه ‪ .... /‬بأنــه ســرقها مــن إحــدى‬\n      ‫االســتراحات يف ذلــك احلــي وصــادق علــى إقــراره شــرع ًا ‪ ،‬ويف إقــرا ٍر‬\n      ‫لــه ســابق أقــر أنــه هــو مــن قــام بكســر قفــل املســتودع‪ .‬جــرى عــرض‬\n      ‫املتهمــن علــى العامــل‪ ... /‬واســتطاع التعــرف علــى املتهــم الثانــي وأضــاف‬\n      ‫بأنــه هــو مــن حمــل املســروقات يف شــنطة الســيارة ‪ .....‬وبتفتيــش ســيارة‬\n      ‫املتهــم األول الــوارد وصفهــا أعــاه تبــن وجــود آثــار حتميــل وخــدوش‬\n      ‫علــى جانــب الشــنطة مــن الداخــل كمــا عثــر علــى قطــع صغيــرة مــن‬\n      ‫األســاك ممــا يؤكــد قيامــه بالســرقة‪ .‬بعــرض ســيارة املتهــم األول علــى‬\n      ‫املبلــغ األول‪ .....‬اســتطاع التعــرف عليهــا‪ .‬جــرى االنتقــال مــن قبــل إدارة‬\n      ‫التحريــات والبحــث اجلنائــي رفــق املتهمــن ومتكينهمــا مــن الداللــة علــى‬\n      ‫املوقعــن املســروقة حيــث قــام األول بالداللــة علــى موقــع املســتودع أمــا‬\n                                            ‫الثانــي فدلهــم علــى موقــع االســتراحة‪.‬‬\n      ‫وبالبحــث عــن ســوابقهما عثــر لــأول علــى ســابقة حيــازة واســتعمال‬\n      ‫املخــدرات وعثــر للثانــي علــى ســابقة ترويــج املخــدرات واســتعمالها‪ .‬وقــد‬\n      ‫أســفر التحقيــق عــن اتهامهمــا باالشــتراك يف ســرقة أســاك نحاســية‬\n\n\n‫‪159‬‬\n\f‫مــن مســتودع بعــد هتــك احلــرز بكســر قفله‪،‬والتســتر علــى شــريكيهما‬\n‫الهاربــن وشــرب املســكر وقيــادة األول الســيارة وهــو بحالــة غيــر‬\n‫طبيعيــة واتهــام الثانــي باالشــتراك مــع أخــر يف ســرقة شاشــة بالزمــا‬\n‫وجهــاز القــط مــن إحــدى االســتراحات وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪1‬ـ إقــرار األول املصــدق عليــه شــرع ًا املــدون علــى الصفحــة رقــم(‪)..‬‬\n‫مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )...‬وإقــراره حتقيقي ـ ًا املــدون‬\n‫علــى الصفحــة رقــم(‪ )...‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )...‬وعلــى‬\n              ‫الصفحــة رقــم(‪ )...‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪.)..‬‬\n‫‪ -2‬إقــرار املتهــم الثانــي املصــدق عليــه شــرع ًا املــدون علــى الصفحــة‬\n‫رقــم(‪ )...‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )..‬وعلــى الصفحــة رقــم(‪)..‬‬\n‫مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )..‬وإقــراره حتقيقي ـ ًا املــدون علــى‬\n‫الصفحــة رقــم(‪ )..‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪ )..‬وعلــى الصفحة‬\n                              ‫رقــم(‪ )..‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪.)..‬‬\n                                                   ‫‪3‬ـ ما ورد بتقرير دوريات األمن‪.‬‬\n‫‪4‬ـ محضــر تعــرف‪ .../‬علــى املتهــم الثانــي املــدون علــى الصفحــة رقــم(‪)..‬‬\n                                         ‫مــن ملــف التحقيــق املرفــق لفــة رقــم(‪.)..‬‬\n‫‪5‬ـ محضــر تفتيــش ســيارة املتهــم األول املــدون علــى الصفحــة رقــم(‪ )..‬مــن‬\n                                               ‫ملــف التحقيــق املرفــق لفة رقــم(‪.)..‬‬\n                                   ‫‪6‬ـ تناقض أقوالهم يف التصرف باملسروقات‪.‬‬\n                                       ‫‪ -7‬محضرا الداللة على موقعي السرقة‪.‬‬\n‫‪ -8‬محضــرا املعاينــة املدونــن علــى الصفحــة رقــم(‪ )..‬مــن ملفــي التحقيــق‬\n                                                               ‫املرفقــن لفة رقــم(‪.)...‬‬\n‫وحيــث أن مــا أقــدم عليــه املتهمــان فعــل محــرم ومعاقــب عليــه شــرعا‬\n\n\n                                                                                           ‫‪160‬‬\n\f      ‫وهــو ســرقة مــال محتــرم مــن حــرزه بعــد هتكــه ال شــبهة لهمــا فيــه‬\n      ‫وبلــغ النصــاب أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بحــد‬\n      ‫الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة واحلكــم‬\n      ‫عليهمــا بحــد املســكر واحلكــم عليهمــا بعقوبــة تعزيريــة تزجرهمــا‬\n      ‫وتــرع غيرهمــا وفق ـ ًا للمــادة(‪ )127‬مــن نظــام اإلجــراءات اجلزائيــة لقــاء‬\n      ‫تســترهما علــى الهاربــن والفصــل يف قيــادة املتهــم األول للســيارة وهــو‬\n      ‫حتــت تأثيــر املســكر مبوجــب الفقــرة (ثانيــا) مــن نظــام املــرور الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ (علمــا بــان‬\n      ‫احلــق اخلــاص مــازال قائمــا وقــد حضــر الســجينان ‪....‬مبوجــب بطاقــة‬\n      ‫نزيــل صــادرة مــن ســجن امللــز برقــم ‪ ....‬يف ‪ ....‬كمــا حضــر مــن‬\n      ‫اســمى نفســه‪ ....‬اليحمــل هويــه وبعــرض الدعــوى علــى املدعــى عليــه‬\n      ‫‪ ...‬قــال ماذكــره املدعــي العــام غيــر صحيــح والصحيــح اننــي قــد‬\n      ‫شــربت املســكر فقــط وماعــدا ذلــك فــا صحــة لــه وقــد ســلمت نفســي‬\n      ‫للشــرطة هكــذا أجــاب وقــد جــرى افهــام املدعــى عليــه ‪ ...‬باحضــار‬\n      ‫هويــة لــه يف اجللســه القادمــة فاســتعد بذلــك ورفعــت اجللســه لذلــك ويف‬\n      ‫يــوم اإلثنــن املوافــق ‪ ...‬افتتحــت اجللســة الســاعة ‪ 12.37‬وحضــر‬\n      ‫الســجني ‪ ...‬والســجني ‪ ...‬مبوجــب بطاقــة نزيــل ‪ ....‬والصــادر مــن‬\n      ‫شــرطة امللــز يف ‪ ...‬وبعــرض الدعــوى عليــه اجــاب ‪ ...‬قائــا ماذكــره‬\n      ‫املدعــي العــام غيــر صحيــح والصحيــح اننــي كنــت مــع ‪ ....‬وكنــت‬\n      ‫ســكرانا وعلــي هــو مــن قــام بالســرقة وامــا انــا فنزلــت مــن الســيارة ثــم‬\n      ‫ركبتهــا ولــم اســرق شــيء هكــذا اجــاب وبســؤال املدعــي العــام عــن‬\n             ‫البينــه قــال ماتضمنتــه اوراق املعاملــة واطلــب اطالعكــم عليهــا‬\n      ‫ويف يــوم اإلثنــن املوافق‪.....‬افتتحــت اجللســة الســاعة‪ 10.00‬ومبشــاركة‬\n\n\n‫‪161‬‬\n\f‫فضيلــة الشــيخ ‪ ....‬حيــث باشــر بعــد دورتــه التدريبيــة بــدال عــن ‪.....‬‬\n‫وباالطــاع علــى املعاملــة وجدناهــا تتضمــن ضمن طياتها ملف التحقيق‬\n‫وقــد تضمــن يف الصحيفــة رقــم ‪ ...‬اقــرارا مصدقــا شــرعا تضمــن مانصه‬\n‫أقــر أنــا ‪ ....‬مــن دون جبــر أو إكــراه باننــي قمــت بتاريــخ ‪ ...‬وبعــد‬\n‫منتصــف الليــل بالذهــاب رفــق ‪ ....‬و‪....‬الــى حــي امللــز علــى الســيارة‬\n‫العائــدة لــي ونحــن بحالــه غيــر طبيعيــه ســكر وأثنــاء جتولنــا شــاهدنا‬\n‫مســتودع واتفقنــا علــى ســرقته وقــام ‪ ....‬بتكســير البــاب اخلارجــي‬\n‫بواســط عتلــة حديديــه حتــى نتمكــن مــن الدخــول رفــق ‪ ...‬وأنــا أمــام‬\n‫مقــود الســيارة وقامــوا بســرقة عــدد ثــاث كراتــن مليئــه باســاك‬\n‫كهربائيــه وبعدهــا متــت مشــاهدتنا ومطاردتنــا مــن قبــل صاحــب‬\n‫املســتودع وارتكبــت الفــرار وبعدهــا قمــت بإنــزال املســروقات بســيارة‬\n‫‪ ..‬وهــي مــن نــوع فــورد ولــم يكــن لــي نصيــب مــن تلــك املســروقات‬\n‫كمــا جــرى االطــاع علــى ملــف اســتكمال محاضــر االســتدالل وقــد‬\n‫تضمــن بالصحيفــة‪ ..‬أثنــاء اســتجواب املدعــى عليــه ‪..‬مــن قبــل احملقــق‬\n‫عــن ســبب القبــض عليــه حيــث أجــاب قائــا بســبب قيامــي أنــا وزمالئــي‬\n‫‪....‬و‪ ....‬بســرقة عــدد ثــاث كراتــن مــن احــدى املســتودعات بحــي امللــز‬\n‫وقــد تضمنــت إجابتــه أن املســروقات ‪ 3‬كراتــن أســاك كهربائيــه‬\n‫وقــد أفــاد أنــه أثنــاء الســرقة لــم يكــن بحالــة طبيعيــه وعلــى هــذه‬\n‫االفــادات بصمــة منســوبة إليــه كمــا جــرى االطــاع علــى ملــف‬\n‫التحقيــق مــن الصحيفــة رقــم ‪ 3‬مــن ملــف التحقيــق وقــد اشــتملت علــى‬\n‫إقــرار مصــدق شــرعا للمدعــى عليــه ‪ ...‬تضمــن مانصــه أقــر أنــا ‪...‬‬\n‫بطوعــي واختيــاري بانــه ورد اتصــال علــى جوالــي مــن احــد رفاقــي‬\n‫ويدعــى ‪ ...‬والــذي ميتهــن ســرقة االســتراحات واخبرنــي انــه متواجد عند‬\n\n\n                                                                                ‫‪162‬‬\n\f      ‫إحــدى االســتراحات بحــي ‪ ..........‬وقمــت بالذهــاب إليــه وعنــد وصولــي‬\n      ‫إليــه قــام بإخــراج شاشــة بالزمــا مــن خلــف إحــدى األشــجار ووضعهــا‬\n      ‫معــي يف ســيارتي وعنــد ســؤال عــن تلــك الشاشــة أخبرنــي بأنــه قــام‬\n      ‫بســرقتها مــن اســتراحة مــن ذلــك احلــي وهــذا إقــرار منــي بذلــك كمــا‬\n      ‫تضمــن ملــف التحقيــق يف الصحيفــة رقــم (‪ )3‬وقــد تضمــن إقــرار لــ‪....‬‬\n      ‫تضمــن أقــر أنــا ‪ ...‬بطوعــي واختيــاري باننــي رفــق زمالئــي ‪ ...‬و‪ ...‬بتاريــخ‬\n      ‫‪ ...‬كنــا بحالــة ســكر وكنــت برفقــة زمالئــي علــى ســيارة تعــود لــ‪.....‬‬\n      ‫وأثنــاء جتولنــا بحــي ‪ .....‬شــاهدنا مســتودع واتفقنــا علــى ســرقته وقــام ‪...‬‬\n      ‫بتكســير البــاب اخلارجــي بواســطة عتلــة حتــى متكنــا مــن ســرقة ثالثــة‬\n      ‫كراتــن أســاك وعندمــا غادرنــا املوقــع شــاهدنا ســيارة تراقبنــا وقمنــا‬\n      ‫برمــي املســروقات بــأرض فضــاء بحــي ‪ ....‬أو ‪ ......‬ال اعلــم بالتحديــد هــذا‬\n      ‫إقــراري بطوعــي واختيــاري وهــو مصــدق شــرع ًا كمــا جــرى االطــاع‬\n      ‫علــى محضــر عــرض مــؤرخ يف ‪ ....‬حيــث مت عــرض املدعــى عليهمــا علــى‬\n      ‫‪.....‬يف مركــز الشــرطة بصفتــه احــد العمالــة الذيــن شــاهدوا اجلنــاه وقــد‬\n      ‫تضمــن احملضــر انــه اســتطاع التعــرف علــى املدعــى عليــه الثانــي ‪....‬‬\n      ‫واكــد انــه مــن قــام بتحميــل املســروقات بشــنطة الســيارة ‪ .....‬وذلــك‬\n      ‫بنســبة مائــة باملائــة وقــد دون ذلــك احملضــر علــى الصحيفــة رقــم ‪ ...‬مــن‬\n      ‫ملــف التحقيــق كمــا جــرى االطــاع علــى الصحيفــة رقــم ‪ ....‬مــن ذات‬\n      ‫امللــف وقــد تضمنــت محضــر تفتيــش مــؤرخ يف ‪ ....‬وقــد تضمــن انــه جــرى‬\n      ‫مــن قبــل احملقــق تفتيــش الســيارة ‪ ......‬ولــم يتــم العثور علــى أي ممنوعات‬\n      ‫أو محرمــات داخــل الســيارة وبتفتيــش شــنطة الســيارة جــرى مالحظــة‬\n      ‫وجــود آثــار حتميــل وخــدوش مــن الشــنطة مــن الداخــل ممــا يــدل علــى‬\n      ‫حتميلهــا باملســروقات كذلــك عثــر علــى قطــع صغيــره مــن األســاك‬\n\n\n‫‪163‬‬\n\f‫داخــل شــنطة الســيارة ممــا يوكــد قيامهــم بالســرقة وبعــرض ذلــك علــى‬\n‫املدعــى عليهمــا قــاال إمنــا ذكرنــاه هــو الصحيــح وماعــدا ذلــك فــا‬\n‫صحــة لــه وهــذه اإلقــرارات أخــذت منــا عــن طريــق اإلكــراه عــن طريــق‬\n‫احملققــن وال بينــة لدينــا علــى اإلكــراه بســؤال املدعــي العــام هــل لديــه‬\n‫مزيــد بينــه قــال ليــس لــدي ســوى ماتضمنتــه أوراق املعاملــة ورفعــت‬\n‫اجللســة النتهــاء الوقــت احملــدد لهــا ويف يــوم اإلثنــن املوافق‪....‬افتتحــت‬\n‫اجللســة الســاعة ‪ 12.38‬وفيهــا حضــر املدعــي العــام والســجينان‬\n‫املدعــى عليهمــا وجــرى ســؤال الســجيينني عــن ســوابقهما فقال املدعى‬\n‫عليــه ‪ ....‬ان لــدي ســابقة اســتعمال مخــدرات وقــال املدعــى عليــه ‪ ...‬ان‬\n‫لــدي ســابقة حيــازة مخــدرات بقصــد االســتعمال فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ومبــا ان املدعــى عليهمــا انكــرا مــا نســب إليهمــا‬\n‫مــن القيــام بالســرقة وأقــرا بتعاطــي املســكر وملــا تضمنــه إقــرار همــا‬\n‫املصــدق شــرعا ومبــا أن الرجــوع عــن اإلقــرار شــبه يف إســقاط احلــدود‬\n‫وملــا تقــدم جميعــه فقــد قررنــا مايلــي أوال صرفنــا النظــر عــن دعــوى‬\n‫املدعــي العــام إقامــة حــد الســرقة ضــد املدعــى عليهمــا لعــدم حتقــق‬\n‫شــرطه ثانيــا إقامــة حــد املســكر علــى املدعــى عليهمــا وذلــك بجلــد‬\n‫كل واحــد منهمــا ثمانــن جلــدة دفعــة واحــده ثالثــا ثبــت لدينــا قيــام‬\n‫املدعــى عليــه ‪ ....‬بقيــادة الســيارة وهــو حتــت تأثيــر املســكر وأفهمنــاه‬\n‫بــان عقوبــة ذلــك راجــع للجهــة املختصــة رابعــا تعزيــر املدعــى عليهمــا‬\n‫بســجن كل واحــد منهمــا ثــاث ســنوات ونصــف مــن تاريــخ إيقــاف‬\n‫كل واحــد منهمــا وجلــد كل واحــد منهمــا ثالثمائــة وخمســن جلــده‬\n‫مفرقــه علــى فتــرات كل مــره خمســون جلــده بــن كل مــره وأخــرى‬\n‫مــا ال يقــل عــن أســبوعني خامسـ ًا أخــذ التعهــد عليهمــا بالتوبــة إلــى اهلل‬\n\n\n                                                                                     ‫‪164‬‬\n\f      ‫وعــدم العــودة ملــا بــدر منهمــا وبذلــك حكمنــا وبعــرض احلكــم علــى‬\n      ‫املدعــى عليهمــا واملدعــي العــام قــرر املدعــي العــام عــدم القناعــة وطلــب‬\n      ‫االســتئناف بــدون الئحــه كمــا قــرر املدعــى عليهمــا القناعــة وامرنــا‬\n      ‫بتنظيــم القــرار الــازم ورفعــه حملكمــة االســتئناف لتدقيقــه وصلــى‬\n      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف الســاعة‬\n                         ‫‪ 12.47‬مــن يــوم االثنــن املوافــق ‪ ....‬ه ـ وبــاهلل التوفيــق‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافق‪....‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 01 : 45‬وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف بخطــاب‬\n      ‫رئيســها رقــم ‪ ....‬يف ‪ ....‬وقــد صــدر فيهــا قــرار الدائــرة الثانيــة لتمييــز‬\n      ‫القضايــا اخلماســية رقــم ‪ ....‬يف ‪ ......‬واملتضمــن مــا نصــه‪ :‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫وأمــرت بإحلــاق ذلــك بالضبــط وســجل القــرار وصلــى اهلل علــى نبينــا‬\n                                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ ....‬ه ـ‬\n\n\n\n\n‫‪165‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":156,"source_page_end":165,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6dc578ed452c4f26ea85157d1c1f863646a7127cf1249a567aeda615e7eb8ee7","normalized_text_hash":"6013c6dbea7725bd4aafb04c427aac658612c551f377a2729cf61a2370a2025e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p156-346374"},{"id":"b0af3d0a-0df1-51a8-b6ff-b91a068c4437","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -استغالل العمل يف السرقة -حتريف أرقام هياكل السيارات -بيع سيارات مسروقة -مقاومة قوات الشرطة - مسكر -حيازة مسكر بقصد الشرب -رجوع عن إقرار مصدق شرع ا -تستر على أحد اجلناة -إحضار بينة على دعوى إكراه بانتزاع اإلقرار -األخذ بالقرائن على انتزاع اإلقرار باإلكراه -التعزير بالسجن واجللد.","document_number":"3444627","case_number":"33600835","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"سرقة -سرقة سيارة -استغالل العمل يف السرقة -حتريف أرقام هياكل السيارات -بيع سيارات مسروقة -مقاومة قوات الشرطة - مسكر -حيازة مسكر بقصد الشرب -رجوع عن إقرار مصدق شرع ا -تستر على أحد اجلناة -إحضار بينة على دعوى إكراه بانتزاع اإلقرار -األخذ بالقرائن على انتزاع اإلقرار باإلكراه -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك ‪ 3444627:‬تاريخه ‪1434/2/23:‬هـ‬\n                   ‫رقم الدعوى ‪33600835 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34240378‬تاريخه‪1434/06/13 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬اســتغالل العمــل يف الســرقة ‪ -‬حتريــف أرقــام‬\n‫هيــاكل الســيارات ‪ -‬بيــع ســيارات مســروقة ‪ -‬مقاومــة قــوات الشــرطة ‪-‬‬\n‫مســكر ‪ -‬حيــازة مســكر بقصــد الشــرب ‪ -‬رجــوع عــن إقــرار مصــدق شــرع ًا‬\n‫‪ -‬تســتر علــى أحــد اجلنــاة ‪ -‬إحضــار بينــة علــى دعــوى إكــراه بانتــزاع‬\n‫اإلقــرار ‪ -‬األخــذ بالقرائــن علــى انتــزاع اإلقــرار باإلكــراه ‪ -‬التعزيــر‬\n                                                         ‫بالســجن واجللــد‪.‬‬\n\n\n\n\n‫مــا قــرره الفقهــاء مــن أن الســجن حــال التحقيــق وســيلة مــن وســائل‬\n                                                             ‫اإلكــراه‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه باالشــتراك مــع شــخص هــارب يف‬\n‫تكويــن عصابــة لســرقة الســيارات وأجزائهــا وتصريــف املســروقات‪،‬‬\n‫وقيامــه بســرقة عــدد مــن الســيارات واســتغالل عملــه يف الورشــة التــي‬\n‫يعمــل بهــا ثــم إحضــار الســيارات للورشــة وحتريــف أرقــام هياكلهــا‬\n‫وتركيبهــا علــى ســيارات أخــرى وبيعهــا وأكل ثمنهــا وحيــازة املســكر‬\n‫بقصــد التعاطــي والهــروب مــن الفرقــة القابضــة وتســتر الثانــي علــى‬\n‫األول ممــا جعــل املدعــى عليــه يــوكل يف أعمالــه اإلجراميــة ‪ ،‬وطلــب‬\n\n                                                                                 ‫‪166‬‬\n\f      ‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪،‬‬\n      ‫مت القبــض علــى املدعــى عليــه بعــد ورود بالغــات بســرقة ســيارات وبعــد‬\n      ‫البحــث والتحــري مت القبــض علــى املدعــى عليــه حيــث توجهت لــه التهمة‬\n      ‫باالشــتراك يف تكويــن عصابــة الســرقة وباســتجوابه اعتــرف مبــا نســب‬\n      ‫لــه‪ ،‬أنكــر املدعــى عليــه الدعــوى‪ ،‬تبــن وجــود إقــرار للمدعــى عليــه‬\n      ‫مصــدق شــرعاً‪ ،‬ادعــى املدعــى عليــه بــان إقــراره انتــزع منــه باإلكــراه‪،‬‬\n      ‫كمــا أحضــر شــاهدين علــى انتزاع اإلقــرار باإلكراه‪ ،‬األخــذ بالقرائن‬\n      ‫علــى انتــزاع اإلقــرار باإلكــراه ‪ ،‬توجيه التهمــة للمدعى عليه‪ ،‬حكمت‬\n      ‫احملكمــة تعزيــر املدعــى عليــه بالســجن واجللــد‪ ،‬وتوجيــه املدعــي العــام‬\n      ‫بإحضــار املدعــى عليــه الهــارب‪ ،‬ومت تصديــق احلكــم مــن محكمــة‬\n                                                                          ‫االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقــم ‪ .......‬وتاريــخ ‪ 1433/10/14‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ ..........‬وتاريــخ ‪ 1433/10/14‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1433/10/18‬ه ـ افتتحــت اجللســة الســاعة ‪02 : 00‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ .....‬وادعــى بقولــه بصف ــتي مدعي ـ ًا عام ـ ًا يف‬\n                             ‫دائ ــرة االدع ــاء الع ــام مبدينــة الريــاض أدع ــي علــى ‪:‬‬\n      ‫‪-1‬الوافــد ‪ 38 ........... /‬ســنة ســوري اجلنســية مبوجــب رخصــة االقامــة‬\n      ‫رقــم (‪ ).......‬اوقــف بتاريــخ ‪1433/3/1‬ه ـ واحيــل الــى الســجن العــام‬\n      ‫مبوجــب امــر االيقــاف رقــم ‪ .......‬وتاريــخ ‪1433/3/19‬ه ـ اســتنادا للبنــد‬\n‫‪167‬‬\n\f‫خامســا مــن القــرار الــوزاري رقــم ‪ 1900‬وتاريــخ ‪1428/7/9‬ه ـ وقيــد‬\n                                                       ‫ســجينا برقــم (‪. ).............‬‬\n‫‪ 51 ............-2‬ســنة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n                                          ‫(‪ )...........‬مفــرج عنــه بالكفالــة ‪.‬‬\n‫انــه بتاريــخ ‪1433/3/1‬ه ـ قبــض علــى املدعــى عليــه االول مــن قبــل ادارة‬\n‫التحريــات والبحــث اجلنائــي وبتاريــخ ‪1433/1/15‬ه ـ قبــض علــى الثانــي‬\n‫بعــد ورود عــدة بالغــات ملراكــز الشــرط عــن ســرقة مجموعــة كبيــرة‬\n                                                        ‫مــن الســيارات كالتالــي ‪:‬‬\n‫‪ -1‬تقــدم املواطــن ‪ ......... /‬ببــاغ لــدى مركــز شــرطة العليــا بتاريــخ‬\n‫‪1432/11/25‬ه ـ عــن تعــرض الســيارة العائــدة ملكيتهــا لشــركة‬\n‫‪ ............‬لتأجيــر الســيارات للســرقة نــوع ‪ .....‬اللــون فضــي ســنة صنعهــا‬\n                                   ‫‪2011‬م لوحــة رقــم(‪ )......‬وهــي مقفلــه ‪.‬‬\n‫‪-2‬وورد بــاغ الوافــد ‪ 29 .... ....... /‬ســنة امريكــي اجلنســية مبوجــب‬\n‫رخصــة االقامــة رقــم (‪ ).......‬لــدى مركــز شــرطة املعــذر بتاريــخ‬\n‫‪1433/1/3‬ه ـ عــن تعــرض ســيارته نــوع ‪ ....‬اللــون ابيــض ســنة صنعهــا‬\n                     ‫‪2011‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-3‬وورد بــاغ الوافــد ‪ 30 ......... /‬ســنة مصــري اجلنســية مبوجــب‬\n‫رخصــة االقامــة رقــم (‪ )............‬لــدى مركــز شــرطة البطحــاء بتاريــخ‬\n‫‪1433/1/10‬ه ـ عــن تعــرض الســيارة العائــدة ملكيتهــا ملؤسســة ‪....‬‬\n‫لتأجيــر الســيارات نــوع ‪ .....‬اللــون ابيــض ســنة صنعهــا ‪2010‬م لوحــة رقــم‬\n                                                ‫(‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-4‬وورد بــاغ منــدوب شــركة ال‪ ....‬لتأجيــر الســيارات لــدى مركــز‬\n‫شــرطة امللــز عــن تعــرض الســيارة نــوع ‪ .....‬اللــون فضــي ســنة صنعهــا‬\n\n\n                                                                                          ‫‪168‬‬\n\f                               ‫‪2005‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-5‬وورد بــاغ منــدوب الشــركة ال‪ ....‬للبيــع بالتقســيط لــدى مركــز‬\n      ‫شــرطة النســيم عــن تعــرض الســيارة نــوع ‪ ......‬اللــون ازرق فــاحت ســنة‬\n                    ‫صنعهــا ‪2007‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-6‬وورد بــاغ منــدوب شــركة ال‪ ....‬لتأجيــر الســيارات لــدى شــرطة‬\n      ‫مطــار امللــك خالــد عــن تعــرض الســيارة نــوع ‪ .....‬اللــون اخضــر ســنة‬\n                   ‫صنعهــا ‪2009‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-7‬وورد بــاغ منــدوب شــركة ال‪ .......‬لالســتثمار لــدى شــرطة منطقــة‬\n      ‫حائــل ‪ /‬مركــز شــرطة عــن تعــرض الســيارة نــوع ‪ .....‬اللــون ابيــض ســنة‬\n                       ‫صنعهــا ‪2008‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-8‬وورد بــاغ ‪ 63...........‬ســنة ســعودي لــدى شــرطة محافظــة جــدة‬\n      ‫مركــز شــرطة جــدة اجلديــد عــن تعــرض ســيارته نــوع ‪ ....‬اللــون ابيــض‬\n            ‫ســنة صنعهــا ‪2010‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-9‬وورد بــاغ منــدوب الشــركة ال‪ ....‬للبيــع للتقســيط لــدى مركــز‬\n      ‫شــرطة امللــز عــن تعــرض الســيارة نــوع ‪ ....‬اللــون ابيــض ســنة صنعهــا‬\n                              ‫‪2010‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-10‬وورد بــاغ منــدوب الشــركة ال‪ ....‬الدوليــة للمواصــات لــدى‬\n      ‫مركــز شــرطة املربــع عــن تعــرض الســيارة نــوع ‪ .....‬اللــون ازرق ســنة‬\n                    ‫صنعهــا ‪2009‬م لوحــة رقــم (‪ )... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-11‬وورد بــاغ منــدوب شــركة ال‪ ....‬املصرفيــة لالســتثمار لــدى مركز‬\n      ‫شــرطة النســيم عــن تعــرض الســيارة نــوع ‪ .....‬اللــون اســود ســنة صنعهــا‬\n                                  ‫‪2011‬م لوحــة رقــم (‪ )... ....‬للســرقة وهــي مقفلــه ‪.‬‬\n      ‫‪-12‬وورد بــاغ منــدوب الشــركة ال‪ ....‬للبيــع بالتقســيط لــدى مركــز‬\n\n\n‫‪169‬‬\n\f‫شــرطة الروضــة عــن تعــرض الســيارة نــوع ‪.....‬اللــون ازرق ســنة صنعهــا‬\n                         ‫‪2010‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-13‬وورد بــاغ منــدوب ‪ ..........‬للبيــع بالتقســيط لــدى مركــز شــركة‬\n‫النســيم عــن تعــرض الســيارة نــوع ‪.....‬اللــون فضــي ســنة صنعهــا ‪2008‬م‬\n                                   ‫لوحــة رقــم (‪ ).... ...‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-14‬وورد بــاغ منــدوب الشــركة ‪ ..........‬للبيــع بالتقســيط لــدى مركــز‬\n‫شــرطة محافظــة جــدة مركــز شــرطة الصفــا عــن تعــرض الســيارة نــوع‬\n‫‪.....‬اللــون فضــي ســنة صنعهــا ‪2011‬م لوحــة رقــم (‪ ).... ...‬للســرقة وهــي‬\n                                                                           ‫مقفلــه ‪.‬‬\n‫‪-15‬وورد بــاغ منــدوب شــركة ‪ .......‬لــدى مركــز شــرطة امللــز مــن‬\n‫تعــرض الســيارة نــوع ‪ .....‬اللــون ابيــض ســنة صنعهــا ‪2010‬م لوحــة رقــم‬\n                                                 ‫(‪ ).... ...‬للســرقة وهــي مقفلــه‬\n‫‪-16‬وورد بــاغ ‪ 28 ......‬ســنة ســعودي اجلنســية لــدى مركــز شــرطة‬\n‫النســيم بتاريــخ ‪1432/8/27‬ه ـ عــن تعــرض ســيارته نــوع ‪.....‬اللــون ابيض‬\n           ‫ســنة صنعهــا ‪2011‬م لوحــة رقــم (‪ ).......‬للســرقة وهــي مقفلــه ‪.‬‬\n‫‪-17‬وورد بــاغ ‪ 43 .......‬ســنة ســعودي اجلنســية لــدى مركــز شــرطة‬\n‫النســيم عــن تعــرض الســيارة املســتأجرة مــن شــركة ‪ ............‬لتأجيــر‬\n‫الســيارات نــوع ‪.....‬اللــون ابيــض ســنة صنعهــا ‪2010‬م لوحــة رقــم (‪).......‬‬\n                                                         ‫للســرقة وهــي مقفلــه ‪.‬‬\n‫عليــه مت اتخــاذ جملــة مــن االجــراءات البحثيــة بالتنســيق مــع فــرق‬\n‫دوريــات األمــن الســرية واخضــاع الــورش يف الصناعيــة وأماكــن‬\n‫التشــاليح للمراقبــة ومالحظــة املتردديــن عليهــا حيــث توفــرت معلومــات‬\n‫لــدى دوريــات االمــن الســرية عــن وجــود أشــخاص ميتهنــون تلــك الســرقات‬\n\n\n                                                                                       ‫‪170‬‬\n\f      ‫ويتــرددون علــى ورشــة ‪ .......‬بصناعيــة النســيم وبإخضاعهــا للمراقبــة‬\n      ‫والرصــد مت مشــاهدة وافديــن أحدهمــا ارتكــب الفــرار بعــد مشــاهدته‬\n      ‫للفرقــة والثانــي يدعــى ‪ 32 ....‬ســنة ســوري اجلنســية إقامــة رقــم (‪).....‬‬\n      ‫(مت حفــظ االتهــام بحقــه مــن قبــل جهــة التحقيــق لعــدم كفايــة االدلــة‬\n      ‫بحقــه وفقـ ًا للمــادة ‪ 124‬مــن نظــام االجــراءات) وبتاريــخ ‪1433/1/13‬ه ـ‬\n      ‫مت االنتقــال للورشــة وضبــط بداخلهــا علــى ثــاث ســيارات مختلفــة‬\n      ‫االنــواع منزوعــة الهيــاكل واتضــح بعــد االستفســار عنهــا أنهــا مســروقة‬\n      ‫واملوضــح معلوماتهــا يف البــاغ رقــم (‪ 1‬ـ ـ ‪ 2‬ـ ـ ‪ )3‬كمــا عثــر علــى ثــاث‬\n      ‫هيــاكل ســيارات منزوعــة االرقــام ودون لوحــات وســاح نــاري نــوع‬\n      ‫مســدس يحمــل الرقــم (‪ ).....‬وعــدد (‪ )55‬طلقــة حيــة (فــرزت لــه اوراق‬\n      ‫واحيلــت الــى اجلهــة املختصــة) وعــدد اربــع عشــرة اســتمارة لســيارات‬\n      ‫متنوعــة وتســع عشــرة لوحــة لســيارات متنوعــة وجهــاز لســبك هيــاكل‬\n      ‫الســيارات وجهــاز برمجــة ســيارات وزجاجتــي مســكر مصنــع خارجيـ ًا‬\n      ‫بهــا النصــف مــن املــادة املســكرة وعــدة مفاتيــح لســيارات مختلفــة‬\n      ‫وثالثــة وثالثــون شــريحة هيــكل معدنيــة اتضــح ان عــدد منهــا عائــدة‬\n      ‫لســيارات مســروقة واملوضــح معلوماتهــا يف ســياق البــاغ رقــم (‪ 4‬حتــى‬\n      ‫‪ )17‬وبالبحــث والتحــري عــن مــن لــه عالقــة باملتهمــن اســفرت اجلهــود‬\n                                                        ‫عــن القبــض علــى كال مــن ‪:‬‬\n                                 ‫‪ 21 .......-1‬سنة سوري اجلنسية اقامة رقم (‪. ).......‬‬\n                                 ‫‪ 53 .......-2‬سنة سوري اجلنسية اقامة رقم (‪. ).......‬‬\n                               ‫‪ 41 .......-3‬سنة مصري اجلنسية اقامة رقم (‪. ).......‬‬\n      ‫(مت حفــظ االتهــام بحقهــم مــن قبــل جهــة التحقيــق لعــدم كفايــة االدلــة‬\n                         ‫اســتنادا للمــادة (‪ )124‬مــن نظــام االجــراءات اجلزائيــة) ‪.‬‬\n\n\n‫‪171‬‬\n\f‫وباســتجواب االول ‪ ......... /‬يعمــل حتــت كفالــة الثانــي ‪ ...... /‬اعتــرف‬\n                                                              ‫علــى النحــو التالــي ‪:‬‬\n‫‪-1‬انــه قبــل ســنتني تقريبــا مــن تاريــخ القبــض عليــه حضــر لــه زبــون يف‬\n‫الورشــة التــي يعمــل بهــا وبقيادتــه ســيارة نــوع ‪.....‬لونهــا ابيــض موديــل‬\n‫‪2008‬م ال يذكــر رقــم لوحتهــا وكان بهــا عطــل ميكانيكــي وطلــب‬\n‫منــه ان يحضــر بعــد يومــن الســتالمها وقــام بتركيــب جهــاز تتبــع عليهــا‬\n‫وبعدمــا اســتلم الزبــون ســيارته حــدد موقعهــا وكلــف ‪( .......‬فــرزت لــه‬\n‫اوراق للقبــض عليــه) بإحضارهــا وبالفعــل احضرهــا ودفــع لــه مقابــل‬\n‫ذلــك مبلــغ ســبعة االف ريــال وقــام بقــص رقــم هيكلهــا واخــراج منهــا‬\n‫املاكينــة والقيــر وباقــي الســيارة ظلــت يف الورشــة الــى ان مت القبــض‬\n                                                                               ‫عليــه ‪.‬‬\n‫‪-2‬قبــل ســنة تقريبــا مــن تاريــخ القبــض عليــه احضــر لــه ‪ .....‬ســيارة‬\n‫مســروقة نــوع ‪ .....‬لونهــا اســود موديــل ‪2011‬م ال يذكــر رقــم لوحتهــا ولــم‬\n‫يخبــره مــن ايــن او كيــف ســرقها واخذهــا منــه ودفــع مبلــغ مالــي وقــدره‬\n              ‫ســتة االف ريــال وقــام بقــص الســيارة وبيعهــا كقطــع غيــار ‪.‬‬\n‫‪-3‬وبعــد ذلــك بشــهرين تقريبــا احضــر لــه ‪ ......‬ســيارة مســروقة نــوع ‪.....‬‬\n‫ازرق فــاحت موديــل ‪2010‬م ال يذكــر رقــم لوحتهــا ولــم يخبــره مــن ايــن او‬\n‫كيــف ســرقها واحضــر معــه هيــكل وطلــب منــه تغييــر رقــم هيــكل‬\n‫هــذه الســيارة وتركيــب الهيــكل الــذي معــه مكانــه واعطــاه مقابــل‬\n‫ذلــك مبلــغ مالــي وقــدره الــف ريــال ثــم اخــذ الســيارة وذهــب بهــا وال يعلــم‬\n                                                             ‫مصيرهــا بعــد ذلــك ‪.‬‬\n‫‪-4‬بعــد ذلــك بثالثــة اشــهر تقريبــا احضــر لــه ‪ ......‬ســيارة نــوع ‪ .....‬لونهــا‬\n‫فضــي موديــل ‪2008‬م ال يذكــر رقــم لوحتهــا اخبــره انهــا لشــخص‬\n\n\n                                                                                          ‫‪172‬‬\n\f      ‫اخذهــا مــن شــركة ‪ .....‬بنظــام التأجيــر املنتهــي بالتمليــك وعليــه‬\n      ‫اقســاط متأخــرة ويرغــب يف التخلــص منهــا فأخذهــا منــه مقابــل مبلــغ‬\n      ‫وقــدره ثمانيــة االف ريــال ثــم قــام بقــص الســيارة وبيعهــا كقطــع غيــار ‪.‬‬\n      ‫‪-5‬يف ثالــث ايــام عيــد الفطــر لعــام ‪1432‬ه ـ احضــر لــه ‪ ......‬ســيارة‬\n      ‫مســروقة نــوع ‪ .....‬لونهــا فضــي موديــل ‪2011‬م ال يذكــر رقــم لوحتهــا‬\n      ‫ولــم يخبــره مــن ايــن او كيــف ســرقها وطلــب منــه نــزع رقــم هيكلهــا‬\n      ‫وقــام بذلــك مقابــل مبلــغ وقــدره الــف ريــال ثــم ذهــب بالســيارة وال يعلــم‬\n                                                                   ‫مصيرهــا بعــد ذلــك ‪.‬‬\n      ‫‪-6‬بعــد ذلــك بأســبوعني تقريبــا احضــر لــه ‪ ......‬ســيارة مســروقة نــوع ‪.....‬‬\n      ‫لونهــا ابيــض موديــل ‪2011‬م ال يعــرف مــن ايــن او كيــف ســرقها واخذها‬\n      ‫منــه مقابــل مبلــغ مالــي وقــدره عشــرة االف ريــال وكان يوجــد لديــه‬\n      ‫ســيارة مصدومــة اشــتراها مــن التشــليح مطابقــة ملواصفاتهــا فقــام بقــص‬\n      ‫رقــم الهيــكل الســيارة املصدومــة وتركيبــه مــكان هيــكل الســيارة‬\n                                                             ‫املســروقة ثــم قــام ببيعهــا ‪.‬‬\n      ‫‪-7‬يف نهايــة شــهر شــوال لعــام ‪1432‬ه ـ احضــر لــه ‪ ......‬ســيارة نــوع ‪.....‬‬\n      ‫لونهــا ابيــض موديــل ‪2010‬م ال يذكــر رقــم لوحتهــا وطلــب منــه تغييــر‬\n      ‫رقــم هيكلهــا وقــام بذلــك مقابــل مبلــغ الــف ريــال ثــم ذهــب بالســيارة وال‬\n                                                            ‫يعلــم مصيرهــا بعــد ذلــك ‪.‬‬\n      ‫‪-8‬بعــد ذلــك بعشــرة ايــام تقريبــا احضــر لــه ‪ ......‬ســيارة مســروقة نــوع‬\n      ‫‪ .....‬لونهــا ازرق فــاحت موديــل ‪2009‬م ال يذكــر رقــم لوحتهــا ولــم يخبــره‬\n      ‫مــن ايــن او كيــف ســرقها وطلــب منــه تغييــر رقــم هيكلهــا فقــام بذلــك‬\n      ‫مقابــل مبلــغ الــف ريــال ثــم ذهــب بالســيارة وال يعلــم مصيرهــا بعــد ذلــك ‪.‬‬\n      ‫‪-9‬يف نهايــة شــهر ذي القعــدة لعــام ‪1432‬ه ـ احضــر لــه ‪ ......‬ســيارة‬\n\n\n‫‪173‬‬\n\f‫مســروقة نــوع ‪.....‬لونهــا ابيــض موديــل ‪2010‬م ال يذكــر رقــم لوحتهــا‬\n‫ولــم يخبــره ايــن او كيــف ســرقها واخذهــا منــه مقابــل مبلــغ مالــي وقــدره‬\n             ‫ســتة االف ريــال وقــام بقــص الســيارة وبيعهــا كقطــع غيــار ‪.‬‬\n‫‪-10‬يف نهايــة عــام ‪1432‬ه ـ احضــر لــه ‪ ......‬ســيارة مســروقة نــوع ‪.....‬‬\n‫لونهــا فضــي موديــل ‪2011‬م ال يذكــر رقــم لوحتهــا ولــم يخبــره مــن ايــن‬\n‫او كيــف ســرقها وقــام بأخذهــا منــه مقابــل مبلــغ وقــدره عشــرة االف‬\n                ‫ريــال وظلــت الســيارة يف الورشــة الــى ان مت القبــض عليــه ‪.‬‬\n‫‪-11‬يف نهايــة عــام ‪1432‬ه ـ حضــر لــه يف الورشــة زبــون ‪ .......‬امريكــي‬\n‫اجلنســية وبقيادتــه ســيارة نــوع ‪ .....‬لونهــا ابيــض موديــل ‪2011‬م ال يذكــر‬\n‫رقــم لوحتهــا وكان بهــا صدمــه يف الرفــرف وطلــب اصالحهــا فطلــب‬\n‫منــه ان يحضــر بعــد يومــن الســتالمها وعندمــا ذهب قام بنســخ مفتاحها‬\n‫وكان يوجــد بهــا جهــاز تتبــع اخــذ رقمــه ويف اليــوم الثانــي حضــر الزبــون‬\n‫واســتلم ســيارته وذهــب وبعدهــا بحوالــي عشــرة ايــام حــدد موقعهــا عــن‬\n‫طريــق جهــاز التتبــع وكلــف ‪ ......‬بإحضارهــا وبالفعــل احضرهــا واعطــاه‬\n‫مقابــل ذلــك مبلــغ وقــدره ثمانيــة االف ريــال وظلــت الســيارة لديــه الــى ان‬\n                                                               ‫مت القبــض عليــه ‪.‬‬\n‫‪-12‬يف منتصــف شــهر محــرم لعــام ‪1433‬ه ـ احضــر لــه ‪ ......‬ســيارة‬\n‫مســروقة نــوع ‪ .....‬لونــا بيــج موديــل ‪2009‬م ال يذكــر رقــم لوحتهــا ولــم‬\n‫يخبــره مــن ايــن او كيــف ســرقها واخذهــا منــه واوقفهــا بحــي ‪ .......‬ولــم‬\n          ‫يدفــع لــه مقابلهــا أي مبلــغ كونــه مت القبــض عليــه قبــل ذلــك ‪.‬‬\n‫‪-13‬بعــد ذلــك بثالثــة ايــام تقريبــا احضــر لــه ‪ ......‬ســيارة مســروقة نــوع‬\n‫‪ .....‬لونهــا ابيــض موديــل ‪2010‬م ال يذكــر رقــم لوحتهــا ولــم يخبــره مــن‬\n‫ايــن او كيــف ســرقها واخذهــا منــه ولــم يدفــع لــه مقابلهــا شــيء كونــه‬\n\n\n                                                                                     ‫‪174‬‬\n\f                                                 ‫مت القبــض عليــه وهــي يف الورشــة ‪.‬‬\n      ‫واضــاف ان املدعــو ‪ ......‬احضــر لــه يف فتــرات مختلفــة مكائــن ســيارات‬\n      ‫مــن نــوع ‪ ..... .....‬وعددهــا ســبع مكائــن ال يعــرف مصدرهــا قام بشــرائها‬\n      ‫منــه ‪.‬كمــا اضــاف انــه طلــب مــن كفيلــه ‪ ...... /‬منــذ مــدة صــورة‬\n      ‫بطاقــة احوالــه وقــام بنســخها عــدة نســخ واســتخدمها يف عمليــة بيــع‬\n      ‫وشــراء الســيارات كمــا اقــر ان املدعــو ‪ ........ /‬اجلنســية واملدعــو ‪/‬‬\n      ‫‪ .......‬ســوري اجلنســية واملدعــو ‪ ....... /‬ســوري اجلنســية لــم يكــن لديهــم‬\n      ‫أي علــم مبــا يقــوم بــه او بالســيارات املســروقة التــي كانــت لديــه وقــد‬\n      ‫صــادق علــى اعترافاتــه شــرعا ومبناقشــته عــن عبوتــي املســكر التــي‬\n      ‫عثــر عليهــا بالورشــة افــاد انــه عثــر عليهــا يف احــدى الســيارات التــي‬\n                                                                  ‫اشــتراها مــن املــزاد ‪.‬‬\n      ‫وباســتجواب الثانــي ‪ ......... /‬صاحــب الورشــة وكفيــل االول ‪ ..... /‬وزوج‬\n      ‫شــقيقته افــاد ان الورشــة التــي يعمــل بهــا مكفولــه ‪ ......‬عائــدة لــه وقــام‬\n      ‫بفتــح الورشــة بنــاء ًا علــى طلــب مــن ‪ .....‬كونــه شــقيق زوجتــه وانــه هــو‬\n      ‫املســئول عنهــا بشــكل كامــل (فــرزت اوراق خاصــة بالتســتر التجــاري‬\n                                                       ‫واحيلــت الــى اجلهــة املختصــة) ‪.‬‬\n      ‫ومبناقشــته عن عدد تســعة وخمســون ســيارة نقلت من اســمه ألشــخاص‬\n      ‫اخريــن افــاد بانــه علــى علــم ببعضهــا حيــث انــه يشــرف علــى الورشــة مــن‬\n      ‫فتــرة ألخــرى والبعــض االخــر يتــم نقلــه مــن قبــل ‪ .....‬واضــاف ان ‪.....‬كان‬\n      ‫يقــوم بشــراء الســيارات املصدومــة مــن املــزاد ويقــوم بإصالحهــا ومــن‬\n      ‫ثــم بيعهــا ومبناقشــته عــن كيفيــة نقلهــا افــاد انــه يف بدايــات افتتاحــه‬\n            ‫للورشــة طلــب منــه ‪ ....‬صــورة البطاقــة إلبرازهــا للجهــات الرســمية ‪.‬‬\n      ‫وباســتجواب ‪ 21 ...........‬ســنة ســوري اجلنســية اقامــة رقــم (‪ )........‬يعمــل‬\n\n\n‫‪175‬‬\n\f‫حتــت كفالــة ‪ .......‬افــاد انــه يقــوم بتحميــل ســيارات بطلــب مــن االول‬\n‫‪ .....‬علــى الســطحة التــي يعمــل بهــا ويقــوم بإحضارهــا مــن التشــاليح‬\n‫وايصالهــا للورشــة التــي يعمــل بهــا ‪ ....‬يف صناعيــة النســيم ومبناقشــته‬\n‫عــن عــدد الســيارات التــي قــام بتحميلهــا افــاد بانــه ال ميكنــه احصائهــا‬\n‫كونــه يعمــل منــذ وقــت طويــل مع ‪ ....‬حوالي الســنة والنصف ومبناقشــته‬\n‫عــن نوعيــة الســيارات التــي يقــوم بتحميلهــا افــاد انــه مختلفــة االنــواع‬\n                                                             ‫ومعظمهــا مصدومــة‪.‬‬\n‫وببعــث زجاجتــي املســكر التــي مت ضبطهــا داخــل الورشــة ملركــز‬\n‫الســموم والكيميــاء الشــرعية للكشــف عــن ايجابيتهــا ملــادة الكحــول‬\n‫االيثيلــي مــن عدمــه ثبتــت ايجابيتهــا ملــادة الكحــول بنســبة ‪ %36‬العينــة‬\n                      ‫الثانيــة ثبتــت ايجابيتهــا ملــادة الكحــول بنســبة ‪. %34‬‬\n‫وقــد اســفر التحقيــق عــن توجيــه االتهــام لــأول ‪ .......‬باالشــتراك مــع ‪......‬‬\n‫يف تكويــن عصابــه لســرقة الســيارات واجزائهــا وتصريــف املســروقات‬\n‫وقيامــه بســرقة عــدد (ســبعة عشــر ســيارة) واســتغالل عملــه يف الورشــة‬\n‫التــي يعمــل بهــا ثــم احضارهــا للورشــة وحتريــف ارقــام هياكلهــا‬\n‫وتركيبهــا علــى ســيارات اخــرى وبيعهــا واكل ثمنهــا وحيازتــه‬\n‫للمســكر بقصــد تعاطيــه وهروبــه مــن الفرقــة القابضــة وتســتر الثانــي‬\n‫علــى االول ممــا جعــل االول يوغــل يف اعمالــه اإلجراميــة وذلــك لألدلــة‬\n                                                                  ‫والقرائــن التاليــة‪:‬‬\n‫‪-1‬مــا جــاء يف اعتــراف املــدون علــى الصفحــات رقــم (‪ 1‬ـ ـ ‪ )5‬مــن ملــف‬\n‫التحقيــق رقــم (‪ )2‬لفــة (‪ )2‬املتضمــن لفــة (‪ )14‬الدوســية رقــم (‪)1‬‬\n‫املتضمــن قيامــه باالشــتراك مــع املتهــم الهــارب ‪ ......‬بســرقة الســيارات‬\n           ‫وحتريــف هياكلهــا واالســتفادة مــن ثمنهــا واملصــدق شــرع ًا ‪.‬‬\n\n\n                                                                                          ‫‪176‬‬\n\f      ‫‪ -2‬مــا جــاء يف محضــر القبــض املتضمــن العثــور علــى ثــاث ســيارات‬\n      ‫داخــل الورشــة التــي يعمــل بهــا والتــي اتضــح أنهــا مســروقة والعثــور علــى‬\n      ‫ثــاث ســيارات هيــاكل لســيارات بــدون لوحــات وال أرقــام هيــكل‬\n      ‫وعــدد أربــع عشــرة اســتمارة ســيارات متنوعــة وتســع عشــرة لوحــة‬\n      ‫ســيارات متنوعــة وثالثــة وثالثــن شــريحة هيــكل معدنيــة وجهــاز لســبك‬\n      ‫هيــاكل الســيارات وســاح نــاري نــوع مســدس املرفــق لفــة (‪ )16‬مــن‬\n                                                                      ‫الدوســية رقــم (‪)1‬‬\n      ‫‪-3‬مــا جــاء يف اقــوال الثانــي ‪ ........‬انــه املســئول عــن الورشــة وتطابــق ذلــك‬\n      ‫مــع مــا ذكــره االول املــدون علــى صفحــة (‪ 1‬ـ ـ ‪ )5‬مــن دفتــر التحقيــق‬\n                           ‫رقــم (‪ )7‬املرفــق لفــة رقــم (‪ )7‬مــن الدوســية رقــم (‪. )1‬‬\n      ‫‪-4‬مــا جــاء يف نتيجــة فحــص الســيارات التــي عثــر عليهــا بالورشــة التــي‬\n      ‫يعمــل بهــا مــن قبــل األدلــة اجلنائيــة املتضمــن وجــود ثــاث ســيارات مت‬\n                                            ‫فحصهــا اتضــح ان هياكلهــا محرفــه ‪.‬‬\n      ‫‪-5‬مــا جــاء يف محضــر االنتقــال واملعاينــة املتضمــن العثــور علــى ثــاث‬\n      ‫هيــاكل ســيارات مفككــة والعثــور علــى عدد مــن قصاصات هياكل‬\n                       ‫ســيارات متنوعــة ولوحــات ســيارات وزجاجتــي املســكر‪.‬‬\n      ‫‪-6‬قيامــه بشــراء مائــة وســبعة وعشــرين ســيارة ومــن ثــم بيعهــا كمــا‬\n      ‫يتضــح جلهــة التحقيــق بعــد االستفســار عنــه ممــا يــدل علــى متاجرتــه‬\n                                                  ‫بالســيارات بطريقــة غيــر نظاميــة‪.‬‬\n      ‫‪-7‬مــا جــاء يف محضــر دوريــات األمــن الســرية املتضمــن هروبــه مــن‬\n      ‫الفرقــة اثنــاء اســتدعائه مــن الورشــة ممــا يــدل علــى تورطــه بتلــك‬\n                   ‫الســرقات املرفــق لفــة رقــم (‪ )16‬مــن الدوســية رقــم (‪.)1‬‬\n      ‫‪-8‬ما جاء يف اقوال ‪ ..... /‬ســوري اجلنســية قائد ســيارة (ســطحة) ســحب‬\n\n\n‫‪177‬‬\n\f‫ســيارات بقيامــه بنقــل ســيارات مصدومــة مــن الورشــة التــي يعمــل بهــا ‪/‬‬\n‫‪ ....‬وارســاله للتشــاليح بأمــر وبشــكل مســتمر ممــا يــدل علــى مترســه‬\n‫لعمليــات تشــليح الســيارات واالســتفادة مــن أجزائهــا وال يســتبعد جلهــة‬\n‫التحقيــق أن تكــون تلــك الســيارات مســروقة املدونــة علــى صفحــة رقــم‬\n‫(‪ 1‬ـ ـ ‪ )8‬مــن دفتــر التحقيــق رقــم (‪ )14‬املرفــق لفــة رقــم (‪ )2‬مــن الدوســية‬\n‫رقــم (‪- )1‬مــا جــاء يف اقــوال الثانــي املتضمنــة قيامــه باســتئجار الورشــة‬\n‫ملكفولــة ‪ ..... /‬طوعـ ًا منــه واعطائــه الصالحيــات الكاملــة بالتصــرف‬\n‫بهــا املدونــة علــى الصفحــة رقــم (‪ 1‬ـ ـ ‪ )5‬من الدفتر رقم (‪ )7‬من الدوســية‬\n                                                                          ‫رقــم (‪. )1‬‬\n‫‪-10‬مــا جــاء يف اعتــراف ‪ ..... /‬املتضمــن العمــل يف الورشــة العائــدة‬\n‫لكفليــه دون معرفــة كفيلــة نشــاط الورشــة او مــا يحــدث بهــا املدونــة‬\n ‫علــى الصفحــة (‪ 1‬ـ ـ ‪ )5‬مــن الدفتــر رقــم (‪ )2‬مــن الدوســية رقــم (‪. )1‬‬\n‫‪-11‬مــا جــاء يف اقــوال الثانــي املتضمنــة تســليمه صــورة هويتــه ملكفولــة‬\n‫املتهــم ‪ .... /‬دون ابــداء مبــرر لذلــك صفحــة رقــم (‪ 1‬ـ ـ ‪ )5‬مــن دفتــر‬\n                                       ‫التحقيــق رقــم (‪ )7‬الدوســية رقــم (‪. )1‬‬\n‫وببحــث ســوابقهما تبــن عــدم وجــود ســوابق مســجله عليهمــا حتــى‬\n                                                                           ‫تاريخــه ‪.‬‬\n‫وحيــث ان مــا اقــدم عليــه املدعــى عليهمــا فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا اطلــب اثبــات مــا اســند اليهمــا واحلكــم بتعزيرهمــا مبــا يردعهمــا‬\n‫والتشــديد علــى االول لقــاء مــا اقــدم عليــه مــن جــرم يعــد انتهــاك ًا ألمــن‬\n‫البــاد (علمــا بــان احلــق اخلــاص مــا زال قائم ـاً) هــذه دعــواي وبعــرض‬\n‫ذلــك علــى املدعــى عليــه طلــب صــورة مــن الئحــة الدعــوى لإلجابــة عــن‬\n‫الدعــوى يف اجللســة القادمــة ثــم رفعــت اجللســة لذلــك وبــاهلل التوفيــق‪،‬‬\n\n\n                                                                                        ‫‪178‬‬\n\f      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪ 1433/10/18‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1433/11/13‬ه ـ‬\n      ‫افتتحت اجللسة الساعة ‪ 11.30‬وفيها حضر املدعي العام واملدعى عليه‬\n      ‫وبعــرض مــا ورد يف الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره‬\n      ‫املدعــي العــام غيــر صحيــح ألنــي ال أســتلم ســيارات بــل أنــا ميكانيكــي‬\n      ‫وال عالقــة لــي بالســمكرة وقــص الهيــاكل وجميــع االعترافــات الواردة‬\n      ‫يف الالئحــة أخــذت منــي علــى ســبيل اإلكــراه وبالقــوة والضــرب والســب‬\n      ‫والتهديــد هكــذا أجــاب ثــم رفعــت اجللســة لالطــاع علــى االعترافــات‬\n      ‫وتأمــل مــا جــاء فيهــا ويف يــوم اإلثنــن املوافــق‪ 1434/01/19‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11.30‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n      ‫وبســؤال املدعــي العــام عــن ســبب عــدم إحضــار الســجني وقــد مت طلبــه‬\n      ‫أكثــر مــن مــرة ســابقا فأجــاب بأنــه مت طلبــه عــن طريــق املســؤول عــن‬\n      ‫إحضــار الســجناء حســب إفــادة احملضــر إال أنــه لــم يحضــر وقــد جــرى‬\n      ‫االطــاع علــى إقــراره املدعــى عليــه املصــادق عليهــا شــرعا املدونــة مبلــف‬\n      ‫التحقيــق الثانــي التــي تتضمــن إقــراره مبــا جاء مفصــا يف الئحة االدعاء‬\n      ‫العــام وبعــرض ذلــك علــى املدعــى عليــه أجــاب بــأن كل ذلــك حصــل‬\n      ‫عــن طريــق اإلكــراه بالضــرب بكيابــل الكهربــاء والعصــي واملســاومة‬\n      ‫بــأن جميــع مــن ســجن بســبب هــذه القضيــة لــن يخــرج إال بعــد أن أقــر‬\n      ‫مبــا أســند إلــي ويصــدق اعتــرايف مــن قبــل احملكمــة هكــذا أجــاب‬\n      ‫وبســؤاله البينــة علــى اإلكــراه قــال لــدي بينــة وهــم ‪ ..........‬و‪......‬و‪......‬‬\n      ‫وســوف أحضرهــا يف اجللســة القادمــة ثــم رفعــت اجللســة إلحضــار البينــة‬\n      ‫وذلــك حتــى يــوم الغــد املوافــق ‪1434/1/20‬ه ـ ويف املوعــد احملــدد‬\n\n\n‫‪179‬‬\n\f‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر حلضــوره ‪............‬‬\n‫الســعودي بالســجل رقــم ‪ ...........‬وبســؤاله عمــا لديــه أجــاب بقولــه بأنــي‬\n‫نســيب للمدعــى عليــه والورشــة كانــت باســمي وقــد ســجنت بســبب هذه‬\n‫القضيــة ملــدة شــهرين وأشــهد أن أحــد الضبــاط ال أذكــر اســمه أحضــر‬\n‫املدعــى عليــه عندمــا كنــت ســجينا وقــال لــه هــذا رحيمــك إن أردت أن‬\n‫نطلقــه فاعتــرف باالتهامــات املوجهــة ضــدك هكــذا شــهد كمــا حضــر‬\n‫‪ ......‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪ ...........‬وبســؤاله عمــا لديــه‬\n‫قــال انــي ســجنت بســبب هــذه القضيــة ملــدة شــهر بســبب تعامالتــي مــع‬\n‫املدعــى عليــه حيــث انــي أعمــل يف مكتــب للخدمــات العامــة وأســتلم‬\n‫منــه أوراقــا لكــي يقــوم صاحــب املكتــب مبراجعــة املــرور ويقــوم‬\n‫بنقــل ملكيــة الســيارات اخلاصــة باملدعــى عليــه وأشــهد أن الضابــط‬\n‫الــذي يحقــق يف القضيــة يقــول للمدعــى عليــه امامــي لــن يخــرج زميلــك‬\n‫وكان يقصدنــي إال إذا اعترفــت وصدقــت اعترافاتــك مــن احملكمــة‬\n‫هكــذا شــهد ثــم رفعــت اجللســة إلحضــار املدعــى عليــه ويف يــوم الثالثــاء‬\n‫املوافــق‪ 1434/02/19‬ه ـ افتتحــت اجللســة الســاعة ‪ 11.55‬وفيهــا حضر‬\n‫املدعــى العــام واملدعــى عليــه األول وبســؤال املدعــى عليــه عــن الســيارة‬\n‫املنزوعــة هياكلهــا املوجــودة يف الورشــة التــي يشــرف عليهــا أجــاب‬\n‫بقولــه بأنــي ميكانيكــي وال عالقــة لــي بهــذا األمــر فهــو مــن اختصاص‬\n‫الســمكري هكــذا أجــاب وبتأمــل مــا ســبق وحيــث أن هنــاك طرفــا‬\n‫لــم يتــم القبــض عليــه ليتــم أخــذ أقوالــه وهــو الهــارب ‪ ......‬حتــى يتضــح‬\n‫حقيقــة األمــر وحيــث أن إفــادة املذكوريــن تطعــن يف صحــة اإلقــرار مــع‬\n‫أن أحدهمــا وهــو املدعــى عليــه الثانــي ‪ .......‬متهمــا يف نفــس القضيــة إال‬\n‫أنــه يعضــد أقوالــه مــا جــاء يف أمــر اإلفــراج الصــادر بعــد املصادقــة علــى‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫إقــرار املدعــى عليــه األول وملــا قــرره الفقهــاء رحمهــم اهلل مــن أن الســجن‬\n      ‫حــال التحقيــق وســيلة مــن وســائل اإلكــراه إال أن إقــراره بأنــه املشــرف‬\n      ‫علــى الورشــة ولوجــود أكثــر مــن ســيارة مســروقة منزوعــة الهيــكل يف‬\n      ‫الورشــة مــع إقــراره وإن كان فيــه مــا فيــه قرائــن تســتوجب توجــه التهمــه‬\n      ‫ضــده يف املشــاركة يف ســرقة الســيارات املذكــورة لذلــك كلــه فقــد‬\n      ‫حكمــت بــرد دعــوى املدعــى العــام يف مطالبتــه بإثبــات إدانــة املدعــى‬\n      ‫عليــه األول ‪.......‬احلاضــر وحكمــت بتعزيــره لقــاء توجــه التهمــة ضــده‬\n      ‫يف املشــاركة بســرقة الســيارات املذكــورة بســجنه ملــدة ســنة وثالثــة‬\n      ‫أشــهر اعتبــارا مــن تاريــخ إيقافــه وجلــده مائــة وخمســون جلــده علــى أن‬\n      ‫تكــون كل دفعــة خمســون جلــدة ومــا بــن كل دفعــة واألخــرى مــدة ال‬\n      ‫تقــل عــن اســبوعني وأفهمــت املدعــي العــام أن لــه إقامــة الدعــوى علــى‬\n      ‫املدعــى عليــه الثانــي حــال حضــوره وبعــرض ذلــك علــى الطرفــن قــرر‬\n      ‫الطرفــان عــدم القناعــة وطلبــا متييــز احلكــم بــدون الئحــة اعتراضيــة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                             ‫حــرر يف ‪ 1434/02/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/05/07‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪1.45‬وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالريــاض وبرفقهــا قــرار الدائــرة اجلزائيــة الثانيــة رقــم ‪......‬‬\n      ‫يف ‪1434/4/20‬ه ـ املتضمــن أن صــورة ضبــط القــرار ناقصــة ويتعــذر‬\n      ‫دراســتها أ‪.‬ه ـ عليــه فقــد مت إكمــال الــازم حيــال ذلــك وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                     ‫‪ 1434/05/07‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n\n\n‫‪181‬‬\n\f‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم ‪......‬‬\n‫وتاريــخ ‪1434/5/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ ......‬املســجل برقــم ‪ ........‬وتاريــخ ‪1434/2/23‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪( ...... /1‬ســوري اجلنســية)‬\n‫‪ ...... / 2‬التهامهــم بســرقة ســيارة علــى النحــو املوضــح بالقــرار املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى‬\n‫قــرار الدائــرة رقــم‪ ........‬وتاريــخ ‪1434/4/20‬ه ـ قررنــا املصادقــة علــى‬\n‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى الــه‬\n                                                           ‫وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n                                                                                   ‫‪182‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":166,"source_page_end":182,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"41fa01f8b1683f7933c18e345a95237d5bb7cfc19414b01ff1e45bd802a15d6c","normalized_text_hash":"fe3a2cf0b87cc714e29b715be647dc84392dc253720906b640551b0ca61166a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p166-3444627"},{"id":"727fa880-9bae-54d9-ae17-b5f7f86a6535","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -إحداث تلفيات يف سيارة مسروقة -تصرف يف بضاعة مسروقة -توجيه تهمة بالقرائن -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملا اتهم به.","document_number":"3344793","case_number":"33601903","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/08","year":"1434","subject":"سرقة -سرقة سيارة -إحداث تلفيات يف سيارة مسروقة -تصرف يف بضاعة مسروقة -توجيه تهمة بالقرائن -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملا اتهم به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3344793:‬تاريخه ‪1434/11/08:‬هـ‬\n                          ‫رقم الدعوى ‪33601903:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3422526‬تاريخه‪1434/01/25 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬إحــداث تلفيــات يف ســيارة مســروقة‪ -‬تصــرف يف‬\n      ‫بضاعــة مســروقة‪ -‬توجيــه تهمــة بالقرائــن‪ -‬تعزيــر بالســجن واجللــد‬\n                                       ‫وأخــذ تعهــد بعــدم العــودة ملــا اتهــم بــه‪.‬‬\n\n\n\n                   ‫‪-1‬قول اهلل تعالى ( وال تفسدوا يف األرض بعد إصالحها )‬\n                          ‫‪-2‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين)‬\n      ‫‪-3‬قولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه‬\n                                                                   ‫ومالــه وعرضــه )‬\n      ‫‪-4‬قولــه صلــى اهلل عليــه وســلم فــإن دماءكــم وأموالكــم وإعراضكــم‬\n      ‫عليكــم حــرام كحرمــة يومكــم هــذا يف شــهركم هــذا يف بلدكــم هــذا )‬\n      ‫‪-5‬قولــه صلــى اهلل عليــه وســلم (إن املســلم أخــو املســلم فليــس املســلم‬\n                            ‫يحــل مــن أخيــه شــيء إال مــا حــل لــه مــن نفســه )‪.‬‬\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه ‪ .......‬مواطــن ‪ .......‬بطلــب‬\n      ‫إثبــات إدانتــه بســرقة ســيارة وإحــداث تلفيــات بهــا والتصــرف مبــا‬\n      ‫كانــت حتتويــه مــن بضاعــة عبــارة عــن كماليــات وطلــب احلكــم‬\n      ‫بعقوبــة تعزيريــة‪ ،‬حيــث مت القبــض علــى املدعــى عليــه بعــد بــاغ مفــاده‬\n      ‫تعــرض ســيارة أحــد األشــخاص للســرقة وبهــا بضاعــة معــدة للبيــع‬\n‫‪183‬‬\n\f‫وقــد شــاهد أحــد أقــارب ســائق الســيارة املتهــم يف أحــد احملــات يقــوم‬\n‫بعــرض البضاعــة حيــث تعــرف عليهــا الشــاهد وبعــد البحــث والتحــري‬\n‫مت القبــض علــى املدعــى عليــه إال أنــه أنكــر وذكــر أنــه اشــترى مــن‬\n‫أخيــه بعــض الكماليــات‪ ،‬وذكــر املدعــي العــام بيناتــه وهــي موجــودة‬\n‫يف لفــات املعاملــة منهــا شــهادة شــاهد‪ ،‬ومحضــري عــرض‪ ،‬وتقريــر‬\n‫مــن شــعبة التحريــات والبحــث اجلنائــي ومضمونــه أن املدعــى عليــه‬\n‫ســيء الســلوك وكثيــر للتجــوال آخــر الليــل وكذلــك محاولــة تضليــل‬\n‫جهــة التحقيــق واملراوغــة‪ ،‬وقــد تقــرر عــدم ثبــوت إدانــة املدعــى عليــه‬\n‫وتوجيــه التعزيــر ألجــل التهمــة‪ ،‬وحكمــت احملكمــة بتعزيــر املدعــى‬\n‫عليــه بالســجن واجللــد وأخــذ التعهــد‪ ،‬مت تصديــق احلكــم مــن محكمــة‬\n                                                                  ‫االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‬\n‫ـاء علــى‬‫ـدي أنــا ‪ ............‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬   ‫فلـ َّ‬\n‫املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫األحســاء برقــم ‪ ........‬وتاريخ‪..........‬واملقيــدة بهــذه احملكمــة برقــم‪..........‬‬\n‫وتاريخ‪.........‬واحملالــة إلينــا مــن فضيلــة الرئيــس برقم‪........‬وتاريــخ‪.........‬‬\n‫فتحــت اجللســة األولــى يــوم األربعــاء ‪......‬الســاعة العاشــرة والنصف وفيها‬\n‫حضــر املدعــي العــام ‪ ........‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫وقرر دعواه‬   ‫األحســاء ذي الرقم هـ ق‪ 137/2/2‬والتاريخ ‪1431/1/5‬هـ ّ‬\n‫ا ‪ :‬بصفتــي مدعيـ ًا عامـ ًا يف دائــرة االدعــاء العام مبحافظة األحســاء‬           ‫قائـ ً‬\n\n                                                                                             ‫‪184‬‬\n\f      ‫أدعــي علــى‪ ، ......... :‬البالــغ مــن العمــر (‪ )29‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ).........‬أعــزب ‪ ،‬متســبب ‪ ،‬قبــض عليــه‬\n      ‫بتاريــخ ‪........‬وأحيــل إلــى شــعبة ســجن محافظــة األحســاء مبوجــب القــرار‬\n      ‫الــوزاري رقــم (‪ )1900‬الفقــرة اخلامســة‪ ،‬وســجل نزيــل لديهــم برقــم(‪.)....‬‬\n      ‫انــه بتاريــخ ‪........‬ه ـ قبــض عليــه مــن قبــل إحــدى فــرق الدوريــات األمنيــة‬\n      ‫مبحافظــه اإلحســاء اثــر البــاغ املقــدم مــن الوافــد ‪ .......‬هنــدي اجلنســية‬\n      ‫عــن تعــرض ســيارة كفيلــه التــي بقيادتــه مــن نــوع موديــل (‪ )..‬لوحــة‬\n      ‫رقــم (‪ )......‬للســرقة أثنــاء وقوفهــا أمــام مقــر ســكنه بحــي ‪ ، .......‬حيــث‬\n      ‫قــام بإيقــاف ســيارة كفيلــه أمــام مقــر ســكنه بحــي يف متــام الســاعة‬\n      ‫الثانيــة عشــر صباح ـ ًا مــن يــوم األحــد املوافــق‪.........‬ويف متامــا الســاعة‬\n      ‫الثامنــة صباحـ ًا مــن نفــس اليــوم وعنــد خروجــه مــن منزلــه ملزاولــة عملــه‬\n      ‫لــم يعثــر عليهــا واتضــح لــه بأنهــا قــد تعرضــت للســرقة مضيف ـ ًا بأنهــا‬\n      ‫حتتــوي علــى بضاعــة عبــارة عــن مجموعــة مــن املســتلزمات الكماليــة‬\n      ‫(شــامبو ؟ وألعــاب أطفــال ؟ معجــون أســنان) تقــدر قيمتهــا بحوالــي‬\n      ‫ســتة وخمســون ألــف ريــال وال يتهــم أحــد ًا بتلــك الســرقة‪ .‬وباالنتقــال‬\n      ‫ومعاينــة الســيارة بعــد العثــور عليهــا اتضــح وجــود تلفيــات بهــا قــدرت‬\n      ‫مببلــغ ثمانيــة آالف وثمامنائــة وخمســون ريــال وســلمت لصاحبهــا بحالتهــا‬\n      ‫الراهنــة‪ .‬وبضبــط أقــوال الشــاهد املدعــو‪ )43( ........ /‬ســنة هنــدي‬\n      ‫اجلنســية والــذي أفــاد بوجــود صلــة قرابــة بينــه وبــن‪ ....... /‬املذكــور‬\n      ‫ويعلــم عــن تعــرض ســيارته املشــار إليهــا للســرقة ويعلــم عــن مواصفــات‬\n      ‫البضاعــة التــي بالســيارة عنــد الســرقة كونهمــا يعمــان ســوي ًا بنقــل‬\n      ‫البضائــع وذكــر بأنــه بتاريــخ ‪........‬ه ـ يف متــام الســاعة احلاديــة عشــر‬\n      ‫صباح ـ ًا وأثنــاء ذهابــه ألحــد البقــاالت ال يعــرف اســمها ‪ ............‬شــاهد‬\n\n\n‫‪185‬‬\n\f‫شــخص ســعودي اجلنســية خــارج مــن تلــك البقالــة وبحوزتــه كيــس أزرق‬\n‫اللــون وبــه مجموعــة مــن املقصــات والســكاكني وأغــراض أخــرى قــام‬\n‫بعرضهــا عليــه للبيــع وعندمــا شــاهد تلــك البضاعــة مــن قبــل الشــاهد‬\n‫املذكــور تعــرف عليهــا بأنهــا البضاعــة املســروقة والتــي كانــت بســيارة‬\n‫املبلــغ املذكــور وقــت الســرقة وعندمــا شــعر ذلــك الشــخص بأنــه علــم‬\n‫عــن مصــدر تلــك البضاعــة تراجــع عــن البيــع وقــام بالركــوب بســيارته‬\n‫التــي مــن نــوع ‪ .......‬اللــون فضــي لوحــة رقــم (‪ ).....‬وذهــب جلهــة غيــر‬\n‫معلومــة وأقــر بأنــه يســتطيع التعــرف علــى ذلــك الشــخص عنــد عرضــه‬\n‫عليــه‪ .‬وبعــرض صــورة املدعــى عليــه‪ .......... /‬علــى الشــاهد املذكــور‬\n‫واســتطاع التعــرف عليــه بنســبة (‪ )%100‬وذكــر بأنــه الشــخص الــذي‬\n‫قــام بعــرض البضاعــة عليــه‪ .‬وبعــرض املدعــى عليــه‪ .... /‬املذكــور علــى‬\n‫الشــاهد‪ ..... /‬املذكــور عرضـ ًا قانونيـ ًا واســتطاع التعــرف عليــه بنســبة‬\n‫(‪ )%100‬وذكــر بأنــه الشــخص الــذي قــام بعــرض البضاعــة املســروقة‬\n‫ا قــام‬\n      ‫عليــه‪ .‬وبضبــط أقــوال املدعــى عليــه األولى‪/‬أعتــرف بأنــه فع ـ ً‬\n‫بعــرض بضاعــة علــى الوافــد‪ . ..../‬ومبواجهــة الشــاهد‪ ..... /‬املذكــور‬\n‫باملدعــى عليــه وأفــاد الشــاهد مبثــل مــا أفــاد بــه بشــهادته وباســتجوابه‬\n‫ا قــام بعــرض تلــك البضاعــة علــى الشــاهد‬    ‫املدعــى عليــه‪ /‬أقــر بأنــه فعـ ً‬\n‫لشــرائها ولكنــه أفــاد بأنــه حصــل عليهــا مــن شــقيقه‪ ........ /‬حيــث قــام‬\n‫بشــرائها منــه بقيمــة مائــة وثمانيــة وســبعني ريــال واتضــح مــن املواجهــة‬\n‫ارتبــاك املدعــى عليــه وخوفــه وتخبطــه يف الــكالم‪ .‬ومبواجهــه املدعــى‬\n‫عليــه‪ .... /‬بشــقيقه املدعــو‪ .... /‬وذلــك داخــل ســجن محافظــة األحســاء‬\n‫وأفــاد املدعــى عليــه ‪ ............‬بأنــه حصــل علــى تلــك البضاعــة املســروقة‬\n‫مــن شــقيقه‪ ... /‬حيــث قــام بشــرائها مببلــغ مائــة وثمانيــة وســبعني‬\n\n\n                                                                                       ‫‪186‬‬\n\f      ‫ا وذكــر بأنــه‬    ‫ريــال وبســماع شــقيقه‪ ... /‬ذلــك أنكــره جملــة وتفصي ـ ً‬\n      ‫شــقيقه‪ .... /‬مــراوغ ويريــد تبرئــه نفســه خوف ـ ًا مــن العقوبــة وتبــن مــن‬\n      ‫املواجهــة ضعــف موقــف املدعــى عليــه‪ .... /‬وعــدم اســتطاعته إكمــال‬\n      ‫املواجهــة‪ .‬وباالطــاع علــى فواتيــر مــن قبــل املبلــغ موضح ـ ًا بهــا قيمــة‬\n      ‫البضاعــة املســروقة واتضــح مببلــغ وقــدره ســتة وخمســون ألــف وســتمائة‬\n      ‫وثالثــة وعشــرون (‪ )56623‬ريــال كذلــك مت إحضــار فواتيــر موضح ـ ًا‬\n      ‫بهــا قيمــة إصــاح املركبــة بعــد العثــور عليهــا واتضــح بــأن التكلفــة‬\n      ‫اإلجماليــة مببلــغ وقــدره ثمانيــة آالف وثمامنائــة وخمســون (‪ )8850‬ريــال‬\n      ‫وذلــك حســب الفواتيــر املرفقــة بــاألوراق‪ .‬وقــد أســفر التحقيــق معــه عــن‬\n      ‫توجيــه االتهــام لــه بســرقة ســيارة الوافــد‪....... /‬و ‪ ......‬هنــدي اجلنســية‬\n      ‫التــي مــن نــوع (‪ )0000 000‬وأحــداث تلفيــات بهــا تقــدر مببلــغ وقــدره‬\n      ‫ثمانيــة آالف وثمامنائــة وخمســون (‪ )8850‬ريــال كذلــك التصــرف‬\n      ‫مبــا كانــت حتتويــه مــن بضاعــة عبــارة عــن كماليــات تقــدر قيمتهــا‬\n      ‫بســتة وخمســن ألــف وســتمائة وثالثــة وعشــرين ريــا ًال ‪ ،‬وذلــك لألدلــة‬\n                                                                  ‫والقرائــن التاليــة‪-:‬‬\n      ‫‪-1‬ماجــاء يف أقــوال الشــاهد‪ ....../‬املنــوه عنــه واملــدون علــى الصفحــة‬\n                                              ‫رقم(‪)11‬مــن دفتــر التحقيــق رقــم(‪)2‬‬\n      ‫‪-2‬محضــر عــرض صــورة املدعــى عليــه علــى أنظــار الشــاهد والــذي‬\n      ‫اســتطاع بــه التعــرف علــى املدعــى عليــه‪ ..... /‬بنســبة (‪ )%100‬وذكــر‬\n      ‫بأنــه مــن قــام بعــرض البضاعــة املســروقة عليــه املنــوه عنــه واملــدون علــى‬\n                                 ‫الصفحــة رقم(‪)16‬مــن ملــف االســتدالل رقــم(‪.)2‬‬\n      ‫‪-3‬محضــر عــرض املدعــى عليــه علــى أنظــار الشــاهد عرضــا قانونيــا‬\n      ‫والــذي اســتطاع التعــرف عليــه بنســبة (‪ )%100‬وذكــر بأنــه مــن قــام‬\n\n\n‫‪187‬‬\n\f‫بعــرض البضاعــة املســروقة عليــه املنــوه عنــه واملــدون علــى الصفحــة‬\n                                         ‫رقم(‪)9‬مــن ملــف االســتدالل رقــم(‪.)1‬‬\n‫‪ -4‬كتــاب شــعبة التحريــات والبحــث اجلنائــي رقــم (‪822/9/21‬س)‬\n                                  ‫وتاريــخ ‪........‬ه ـ املرفقــة علــى اللفــة رقــم(‪)27‬‬\n‫‪-5‬محاضــر املواجهــة والــذي تبــن منهــا قــوة حجــة الشــاهد‪ ..... /‬كذلك‬\n‫قــوة حجــة شــقيقه املدعــو‪ ... /‬وضعــف موقــف املدعــى عليــه املنــوه عنهــا‬\n     ‫واملدونــة علــى الصفحتــن رقم(‪)16-13‬مــن ملــف االســتدالل رقــم(‪)1‬‬\n‫‪-6‬مــا جــاء بالفواتيــر التــي احضرهــا املبلــغ والتــي تثبــت قيمــة البضاعــة‬\n‫وكذلــك فواتيــر إصــاح الســيارة املســروقة بعــد العثــور عليهــا املرفقــة‬\n                                                       ‫علــى اللفــات رقــم(‪)63-41‬‬\n‫ا وتراجعــه عــن ذلــك‬      ‫‪ -7‬إنــكاره الشــديد ملــا نســب إليــه جملــة وتفصيـ ً‬\n‫ا عــرض عليــه‬      ‫اإلنــكار بعــد مواجهتــه بالشــاهد واعترافــه بأنــه فع ـ ً‬\n‫تلــك البضاعــة حيــث قــام بشــرائها مــن شــقيقه‪ ..../‬مببلــغ وقــدره مائــة‬\n‫وثمانيــة وســبعني (‪ )178‬ريــا ًال دليــل علــى قيامــه بالســرقة ومراوغتــه‬\n                       ‫محــاو ًال تضليــل جهــة التحقيــق لإلفــات مــن العقوبــة‪.‬‬\n‫‪-8‬كــون مقــر ســكن املدعــى عليــه املذكــور قريــب جــد ًا مــن ســكن‬\n‫املبلــغ ممــا ال يســتبعد قيامــه بالســرقة كونــه وأشــقائه مــن املشــبوهني‬\n‫لدينــا بالســرقات‪ .‬وبالبحــث عمــا إذا كان لــه ســوابقه اتضــح خلــو‬\n‫ســجله مــن الســوابق ‪.‬وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــم بكامــل‬\n‫أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب‬\n                                                              ‫إثبــات مــا أســند إليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة تزجرهــم وتــردع غيرهــم‪ .‬علمـ ًا بــأن احلــق‬\n‫اخلــاص ال يــزال قائم ـ ًا عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد‬\n\n\n                                                                                           ‫‪188‬‬\n\f      ‫ا ‪ :‬مــا‬ ‫مــن أهليتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـ ً‬\n      ‫ذكــره املدعــي العــام مــن اتهامــي بســرقة ســيارة الوافــد ‪ ........‬مــن نــوع‬\n      ‫وإحــداث تلفيــات بهــا تقــدر مببلــغ ثمانيــة آالف وثمامنائــة وخمســن ريــا ًال‬\n      ‫والتصــرف مبــا كانــت حتويــه مــن بضاعــة كماليــات تقــدر قيمتهــا‬\n      ‫بســتة وخمســن ألــف وســتمائة وثالثــة وعشــرين ريــا ًال كل ذلــك غيــر‬\n      ‫صحيــح فلــم أقــم بســرقة أي ســيارة وال أعــرف مــن ســرقها وإمنــا اشــتريت‬\n      ‫مــن أخــي بعــض الكماليــات وأردت بيعهــا كعادتــي وتفاجــأت بذلــك‬\n      ‫العامــل يقــول إن هــذه البضاعــة مســروقة وأنــا ال علــم لــي بســرقتها وإمنــا‬\n      ‫أخذتهــا مــن أخــي هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام علــى‬\n      ‫ـدي ســوى مــا يف أوراق املعاملــة وأطلــب الرجــوع إليهــا‬   ‫دعــواه قــال ليــس لـ َّ‬\n      ‫هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪:‬‬\n      ‫أقــوال الشــاهد ‪ .......‬املدونــة علــى الصحيفــة(‪ )11‬مــن دفتــر التحقيــق‬\n      ‫نصــه ‪ :‬أقـ ُّـر أنــا املوقــع أدنــاه ‪43 .....‬ســنة هنــدي‬\n                                                                ‫رقــم(‪ )2‬املتضمــن مــا ُّ‬\n      ‫اجلنســية إقامــة رقــم(‪ )......‬أقـ ُّـر وأنــا بكامــل قــواي العقليــة املعتبــرة‬\n      ‫شــرع ًا وبطوعــي واختيــاري بأننــي أعمــل ســائق لســيارة نقــل بضائــع مــن‬\n      ‫نــوع ‪ ......‬مــع ابــن أخــي بنقــل البضائــع للمحــات التجاريــة وأفيدكم بأن‬\n      ‫ســيارة ابــن أخــي مــن نــوع‪ .......‬تعرضــت للســرقة وبهــا بضاعــة كماليــات‬\n      ‫تقــدر قيمتهــا بخمســن ألــف ريــال وال نعلــم مــن الــذي قــام بســرقتها‬\n      ‫لكــن يف يــوم أمــس وأثنــاء ذهابــي إلحــدى البقــاالت شــاهدت شــخص‬\n      ‫ســعودي اجلنســية ‪-‬وذكــر أوصافــه‪ -‬خــارج مــن البقالــة وبيــده أغــراض‬\n      ‫وبعــد رؤيتهــا اتضــح أنهــا مــن البضاعــة املســروقة ا‪.‬ه ـ نــص احلاجــة‬\n      ‫ا ‪ :‬مــا ذكــره الشــاهد‬      ‫منــه وبعرضــه علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫يف شــهادته صحيــح وقــد أخــذت البضاعــة مــن أخــي وال عــن ســرقتها‬\n\n\n‫‪189‬‬\n\f‫شــيئ ًا هكــذا قــرر كمــا جــرى االطــاع علــى كتــاب شــعبة التحريــات‬\n‫والبحــث اجلنائــي رقــم(‪ ).......‬وتاريخ‪........‬ه ـ املتضمــن أن املدعــى عليــه‬\n‫ســيء الســلوك وكثيــر التجــول يف آخــر الليــل ا‪.‬ه ـ وبعرضــه علــى املدعى‬\n‫ا ‪ :‬مــا ذكــر يف التقريــر غير صحيح فأنــا أعمل أعمال‬           ‫عليــه أجــاب قائـ ً‬\n‫حــرة أتــرزق مــن ورائهــا وعنــد الســاعة الثانيــة عشــرة أكــون يف املنــزل‬\n‫هكــذا قــرر كمــا جــرى االطــاع علــى محاضــر املواجهــة بــن املدعــى‬\n‫عليــه وبــن صاحــب احلــق اخلــاص وشــاهده املتضمنــة ظهــور قــوة موقــف‬\n‫األخيريــن وضعــف جانــب املدعــى عليــه وبعــرض ذلــك علــى املدعــى عليــه‬\n‫ا ‪ :‬مــا ذكــر يف احملاضــر غيــر صحيــح فأنــا لــم أخــف مــن‬        ‫أجــاب قائ ـ ً‬\n‫أي شــيء وإذا كان أخــي قــد ســرق البضاعــة فــا علــم‬        ‫أحــد ولــم أســرق َّ‬\n               ‫ـأن أخــي صاحــب ســوابق هكــذا قــرر‬    ‫لــي بذلــك مــع علمــه بـ َّ‬\n‫كمــا جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمــن عــدم‬\n‫وجــود ســوابق علــى املدعــى عليــه كمــا جــرى االطــاع علــى مذكــرة‬\n‫ـاء علــى‬‫إيقــاف املدعــى عليــه املتضمنــة أنــه أوقــف بتاريــخ‪ ......‬ه ـ فبنـ ً‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه‬\n‫أن‬\n ‫والتأكــد مــن أهليتــه وبعــد دراســة أوراق املعاملــة ودراســتها ومبــا َّ‬\n‫املدعــى عليــه أنكــر دعــوى املدعــي العــام باتهامــه بســرقة ســيارة الوافــد‬\n‫‪ .......‬مــن نــوع وإحــداث تلفيــات بهــا تقــدر مببلــغ ثمانيــة آالف وثمامنائــة‬\n‫وخمســن ريــا ًال والتصــرف مبــا كانــت حتويــه مــن بضاعــة كماليــات‬\n‫تقــدر قيمتهــا بســتة وخمســن ألــف وســتمائة وثالثــة وعشــرين ريــا ًال وال‬\n‫بينــة للمدعــي العــام علــى ذلــك ممــا يســتوجب عــدم إثبــات إدانــة املدعــى‬\n‫عليــه بذلــك ومبــا أ َّنــه يتهــم بذلــك ويــدلُّ لــه وجــود البضاعــة املســروقة‬\n‫معــه وأخذهــا مــن أخيــه مــع علمــه بأ َّنــه صاحــب ســوابق وشــهادة الشــاهد‬\n\n\n                                                                                        ‫‪190‬‬\n\f      ‫أن مــا‬    ‫املذكــورة ومحاضــر املواجهــة وتقريــر البحــث اجلنائــي ومبــا َّ‬\n      ‫ض َب ْعـ َـد‬  ‫ال ْر ِ‬‫{و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬      ‫يتهــم بــه مــن احملــرم شــرع ًا قــال تعالــى ‪َ :‬‬\n      ‫الل ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن } وقــال‬    ‫{وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n                                                                                        ‫ِإ ْص َلحِ َهــا } وقــال تعالــى ‪َ :‬‬\n      ‫دم ـ ُه وما ُل ـ ُه‬ ‫ـرام ُ‬\n                               ‫صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم حـ ٌ‬\n      ‫َكـ ْـم‬  ‫كـ ْـم َو َأ ْم َوال ُ‬\n                                    ‫‪((:‬فـ ِإ َّن د َِم َاء ُ‬\n                                                        ‫وعرضــه)) وقــال عليــه الصــاة والســام َ‬                              ‫ُ‬\n      ‫ك ْم‬    ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬        ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬  ‫كـ ْـم َ‬ ‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬‫اض ُ‬  ‫َو َأ ْع َر َ‬\n      ‫كـ ْـم َهـ َـذا )) وقــال عليــه الصــاة والســام ‪َ (( :‬أال ِإ َّن‬                                       ‫َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬\n      ‫ـس َي ِحــلُّ لِ ُْسـل ٍِم مِ ــنْ َأخِ يـ ِه َشـ ْـي ٌء ِإال َمــا َحــلَّ َلـ ُه‬  ‫ْال ُْسـل َِم َأ ُخــو ْال ُْسـل ِِم ‪َ ،‬ف َل ْيـ َ‬\n      ‫مِ ــنْ ن َْف ِسـ ِه )) ممــا يســتوجب تعزيــر املدعــى عليــه لــذا كلــه وألجــل احلــق‬\n      ‫ـدي إدانــة‬    ‫العــام حكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬أو ًال ‪ /‬لــم يثبــت لـ َّ‬\n      ‫املدعــى عليــه بســرقة ســيارة الوافــد ‪ ......‬مــن نــوع‪ .......‬وإحــداث تلفيــات‬\n      ‫بهــا تقــدر مببلــغ ثمانيــة آالف وثمامنائــة وخمســون ريــال والتصــرف مبــا‬\n      ‫كانــت حتويــه مــن بضاعــة كماليــات تقــدر قيمتهــا بســتة وخمســن‬\n                                      ‫ألــف وســتمائة وثالثــة وعشــرين ريــا ًال وقـ ُ‬\n      ‫ـررت ر َّد دعــوى املدعــي العــام‬\n      ‫بإثبــات إدانــة املدعــى عليــه بذلــك ‪ .‬ثاني ـ ًا ‪ /‬يعــزر ألجــل التهمــة بســجنه‬\n      ‫ملــدة ســبعة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة وبجلــده مائــة‬\n      ‫مفرقــة علــى ثــاث دفعــات كل دفعــة خمســون جلــدة‬         ‫وخمســن جلــدة َّ‬\n      ‫وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام‪ .‬ثالثـ ًا ‪ /‬يؤخــذ عليه‬\n      ‫التعهــد بعــدم العــودة ملثــل مــا يتهــم بــه وبتــاوة احلكــم علــى الطرفــن‬\n      ‫وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر القناعــة بــه وطلــب‬\n      ‫املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف دون‬\n      ‫الئحــة اعتراضيــة مكتفيـ ًا مبــا ورد يف الئحــة الدعــوى وأقفلــت اجللســة‬\n      ‫الســاعة احلاديــة عشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد‬\n\n\n‫‪191‬‬\n\f                    ‫وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1433/11/21‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء برقــم ‪........‬‬\n‫وتاريــخ ‪.......‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪ ......‬وتاريــخ ‪.......‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪...........‬‬\n‫املســجل برقــم ‪ .........‬وتاريــخ ‪.........‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n‫ضــد‪ .............../‬يف قضيــة ســرقة وقــد تضمــن القــرار حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                             ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪ .....‬ه ـ‬\n\n\n\n\n                                                                                           ‫‪192‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":183,"source_page_end":192,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f490f597a1dcf47106383663695a001551885baee45a290152614454217e7332","normalized_text_hash":"a32849798432aad2ef105c18ee98f021f441fbcf9dd9efa310b771cc92f56e33","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p183-3344793"},{"id":"27d0e83d-75fe-518c-bdbc-ef9c51076f57","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -مشاركة آخر يف السرقة -تستر على أحد اجلناة -تعزير بالقرائن -تغيير لوحة سيارة مسروقة -مشروعية التعزير بالقرائن -تعزير بالسجن واجللد -التوصية باإلبعاد.","document_number":"3433183","case_number":"33604661","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"سرقة -سرقة سيارة -مشاركة آخر يف السرقة -تستر على أحد اجلناة -تعزير بالقرائن -تغيير لوحة سيارة مسروقة -مشروعية التعزير بالقرائن -تعزير بالسجن واجللد -التوصية باإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"          ‫رقم الصك ‪ 3433183:‬تاريخه ‪1434/2/9:‬هـ‬\n                          ‫رقم الدعوى ‪33604661:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34201241‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬مشــاركة آخــر يف الســرقة ‪ -‬تســتر علــى أحــد‬\n      ‫اجلنــاة ‪ -‬تعزيــر بالقرائــن ‪ -‬تغييــر لوحــة ســيارة مســروقة ‪ -‬مشــروعية‬\n         ‫التعزيــر بالقرائــن ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬التوصيــة باإلبعــاد‪.‬‬\n\n\n\n\n      ‫ا يف تهمــة رواه أبــو داود‬\n                                ‫‪-1‬حبــس النبــي صلــى اهلل عليــه وســلم رج ـ ً‬\n                                            ‫والترمــذي وقــال حديــث صحيــح‪.‬‬\n                                                 ‫‪-2‬مشروعية التعزير بالقرائن‪.‬‬\n                                                               ‫‪-3‬األصل البراءة‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد مقيــم يعمــل يف ورشــة بســرقة ســيارتني مت‬\n      ‫وصفهــا‪ ،‬وســرقة لوحــة ســيارة مبشــاركة أشــخاص آخريــن تســتر‬\n      ‫عليهــم‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكم عليــه بعقوبة‬\n      ‫تعزيريــة‪ ،‬وقــد قبــض علــى املدعــى عليــه بعــد بالغــات بســرقة ســيارات‬\n      ‫عثــر عليهــا يف ورشــة يعمــل بهــا املدعــى عليــه‪ ،‬لكــن أنكــر املدعــى‬\n      ‫عليــه وذكــر أنــه مت القبــض عليــه لوجــود ســيارة يف الورشــة التــي يعمــل‬\n      ‫بهــا أحضرهــا لــه شــخص آخــر لــم يكــن يعلــم أن الســيارة مســروقة إال‬\n      ‫بعــد القبــض عليــه‪ ،‬ونظــر ًا لوجــود القرائــن الدالــة علــى صحــة الدعــوى‬\n\n‫‪193‬‬\n\f‫ومنهــا أن الورشــة خاصــة بإصــاح ســيارات الشــركة التــي يعمــل‬\n‫بهــا املدعــى عليــه وتناقــض أقــوال املدعــى عليــه لــدى جهــة التحقيــق‬\n‫ومخالفــة العــرف‪ ،‬وملشــروعية التعزيــر بالقرائــن فقــد مت احلكــم عليــه‬\n‫بالســجن واجللــد والتوصيــة باإلبعــاد عــن البــاد ومت تصديــق احلكــم مــن‬\n                                                      ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ 1433/10/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ ........‬وتاريــخ ‪ 1433/10/16‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق‪ 1434/01/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 15‬وفيهــا قــدم‬\n‫املدعــي العــام الئحــة دعــوى عامــة ضــد ‪ 22 ....‬ســنة أفغانــي اجلنســية‬\n‫مبوجــب رخصــة اإلقامــة رقــم (‪ )...‬أوقــف بتاريــخ ‪1433/6/17‬ه ـ وأحيــل‬\n‫إلــى الســجن العــام مبوجــب أمــر اإلحالــة رقــم ‪ ....‬وتاريــخ ‪1433/6/30‬ه ـ‬\n‫اســتناد ًا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة حيــث أنــه‬\n‫بتاريــخ ‪1433/6/17‬ه ـ أبلــغ املواطــن ‪ ........‬مالــك مؤسســة ‪ ......‬لتأجيــر‬\n‫الســيارات مركــز شــرطة ‪ ....‬عــن تعــرض الســيارة التابعــة ملؤسســته مــن‬\n‫نــوع ‪ ......‬حتمــل اللوحــة رقــم (‪ ).... ...‬للســرقة مــن أمــام املؤسســة بحــي‬\n‫الــ‪ .....‬وبتاريــخ ‪1433/6/17‬ه ـ ورد ملركــز شــرطة ‪ .....‬خطــاب مديــر‬\n‫مركــز شــرطة ‪ ....‬رقــم ‪ ....‬يف ‪1433/6/17‬ه ـ املتضمــن بــاغ‪..........‬‬\n‫الوكيــل الشــرعي عــن مؤسســة ‪ .....‬لتأجيــر الســيارة عــن تعــرض ســيارة‬\n‫املؤسســة مــن نــوع ‪ .....‬لوحــة رقــم (‪ ).... ...‬للســرقة مــن أمــام مكتــب‬\n\n                                                                                     ‫‪194‬‬\n\f      ‫املؤسســة الواقــع بحــي الــ‪ ....‬وبعــد تتبعهــا مــن قبــل منــدوب املؤسســة‬\n      ‫بواســطة شــريحة تتبــع ســبق أن مت وضعهــا يف الســيارة قبــل ســرقتها‬\n      ‫مت العثــور عليهــا يف إحــدى الــورش اخلاصــة بســيارات األجــرة العامــة‬\n      ‫بحــي ‪ .....‬فتــم التنســيق مــع دوريــات األمــن والقبــض علــى املدعــى عليــه‬\n      ‫والــذي يعمــل بنفــس الورشــة وهــو يقــوم بفــك بعــض القطــع مــن املركبــة‬\n      ‫املســتبدل لوحاتهــا بلوحــات غيــر عائــدة لهــا حتمــل رقــم (‪ ).......‬وبتاريــخ‬\n      ‫ا عــن‬ ‫‪1432/4/28‬ه ـ حضــر ملركــز شــرطة ‪ ........ /.....‬بصفتــه وكيـ ً‬\n      ‫شــركة الــ‪ ....‬مبلغــا عــن فقــدان لوحــة ســيارة ‪ .......‬حتمــل الرقــم (‪).......‬‬\n      ‫وباســتجواب املدعــى عليــه أفــاد أن الســيارة ‪ ...‬ذات الرقــم (‪ ).......‬عثــر‬\n      ‫عليهــا داخــل الورشــة التــي يعمــل بهــا وأن شــخص ســوداني ال يعرفــه‬\n      ‫أحضرهــا لــه وطلــب منــه إصالحهــا وقــد أســفر التحقيــق عــن توجيــه‬\n      ‫االتهــام للمدعــى عليــه بســرقة ســيارتني األولــى مــن نــوع ‪ ....‬لوحــة رقــم‬\n      ‫(‪ ).......‬والثانيــة مــن نــوع ‪ ......‬رقــم (‪ ).......‬وســرقة لوحــة حتمــل الرقــم‬\n      ‫‪ .......‬مبشــاركة أشــخاص تســتر عليهــم وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                             ‫‪1‬ـ اعترافه املصدق شرع ًا املدون لفة رقم (‪ )9‬ص (‪.)8‬‬\n                                  ‫‪2‬ـ ما جاء يف محضر القبض املرفق لفة رقم (‪.)7‬‬\n      ‫‪3‬ـ تبريــر املدعــى عليــه بــأن الســيارة مت إحضارهــا لــه مــن قبــل شــخص‬\n                                  ‫ســوداني دون أي عنــوان أو اســم أو الداللــة عليــه‪.‬‬\n      ‫‪4‬ـ العثــور علــى الســيارة الثانيــة املســروقة بجــوار الورشــة التــي يعمــل بهــا‬\n                                         ‫املدعــى عليــه يــدل علــى ضلوعــه يف ســرقتها‪.‬‬\n      ‫‪5‬ـ العثــور علــى لوحــة مســروقة مركبــة علــى الســيارة املســروقة يــدل‬\n      ‫علــى ضلــوع املدعــى عليــه يف ســرقة اللوحــة‪ .‬وبالبحــث عــن ســوابقه لــم‬\n                                                  ‫يعثــر لــه علــى ســوابق حتــى تاريخــه‪.‬‬\n\n\n‫‪195‬‬\n\f‫وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫اطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره‬\n‫وتــردع غيــره‪ .‬وبــاهلل التوفيــق وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n‫قائــا إن مــا ذكــره املدعــي العــام مــن وجــود ســيارة ‪ ...‬داخــل الورشــة‬\n‫التــي أعمــل فيهــا صحيــح وقــد مت القبــض علــي وعلمــت بعــد القبــض أن‬\n‫هــذه الســيارة مســروقة وقــد أحضرهــا لــي شــخص ســوداني زبــون عنــدي‬\n‫ولــم أكــن موجــود ًا حــن أحضرهــا وقــام بإدخالهــا للورشــة ثــم حضــر لي‬\n‫بعــد ذلــك وطلــب منــي إصــاح الســيارة ولــم أكــن أعلــم أنهــا مســروقة‬\n‫ولــم أشــترك يف ســرقتها هكــذا أجــاب وباالطــاع علــى إقــراره املصــدق‬\n‫شــرع ًا املــدون علــى ص ‪ 8‬لفــة ( ‪ ) 9‬ألفيــت متضمن ـ ًا قولــه إن شــخص ًا‬\n‫ســوداني ًا أحضــر لــه الســيارة ‪ ....‬لوحــة ( ‪ ).... ...‬وأن املدعــى عليــه قــام‬\n‫بإدخالهــا الورشــة دون علــم صاحــب الورشــة إلصالحهــا وأن لــم يفــك‬\n‫الســيارة ولــم ينــزل لوحتهــا أ ‪ .‬ه ـ بتصــرف وبعــرض عليــه قــال الصحيــح‬\n‫مــا ذكــرت يف مجلــس احلكــم علم ـ ًا أن أحــد لوحتــي الســيارة مفقــودة‬\n‫ثــم جــرى ســؤاله هــل الورشــة خاصــة فقــال نعــم هــي خاصــة مبكتــب‬\n‫ال‪ ...‬لتأجيــر الســيارات وال تصلــح فيهــا غيــر ســيارات املكتــب ثــم جــرى‬\n‫عــرض قولــه املــدون علــى ص ‪ 13‬لفــة ( ‪ ) 1‬أنــه ال يعــرف الســوداني بينمــا‬\n‫ذكــر يف مجلــس احلكــم أنــه مــن زبائنــه فقــال ال هــو زبــون هكــذا‬\n‫أجــاب فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n‫بعلمــه بســرقة الســيارة التــي يف ورشــته بعــد القبــض عليــه وألن األصــل‬\n‫البــراءة ولقيــام القرائــن الدالــة علــى تعاونــه يف الســرقة إمــا مشــاركة أو‬\n‫تواطــؤ ًا بالتســتر وهــي وجــود الســيارة يف ورشــته التــي أقــر أنهــا خاصــة‬\n‫بســيارات الشــركة التــي وتناقضــه يف معرفــة مــن يدعــي أنــه أحضرهــا‬\n\n\n                                                                                      ‫‪196‬‬\n\f      ‫وتناقضــه يف ذكــر مــن أدخلهــا الورشــة وإقــراره بعــدم وجــود أحــد‬\n      ‫لوحتيهــا ومخالفــة العــرف يف عــدم معرفــة عنــوان مــن يحضــر الســيارة‬\n      ‫لإلصــاح وملشــروعية التعزيــر بالقرائــن كمــا حبــس النبــي صلــى اهلل‬\n      ‫ا يف تهمــة رواه أبــو داود والترمــذي وقــال حســن صحيــح‬       ‫عليــه وســلم رجـ ً‬\n      ‫وألن محضــر القبــض املذكــور لــم يتضمــن إال وجــود ســيارة واحــدة‬\n      ‫فإنــه لــم يثبــت لــدي إدانــة املدعــى عليــه مبــا جــاء يف الدعــوى وإمنــا قامــت‬\n      ‫القرائــن علــى اتهامــه بســرقة ســيارة وتغييــر لوحتهــا وحكمــت عليــه‬\n      ‫لقــاء ذلــك بســجنه ثمانيــة أشــهر تبــدأ مــن تاريــخ اإليقــاف وجلــده مائــة‬\n      ‫وعشــرين جلــدة أمــام النــاس مفرقــة علــى دفعتــن كل دفعة ســتون جلدة‬\n      ‫وبينهمــا عشــرة أيــام وأوصــي بإبعــاده عــن البــاد بعــد تصفيــة مــا لــه ومــا‬\n      ‫عليــه مــن حقــوق وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة واملدعــي‬\n      ‫العــام االعتــراض مكتفيــا بالئحــة الدعــوى وكان النطــق باحلكــم يف‬\n      ‫‪ 1434 / 1 / 25‬ه ـ وأغلقــت اجللســة الســاعة احلاديــة عشــرة وعليــه جــرى‬\n             ‫التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده ‪...‬وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ ..........‬وتاريــخ ‪/4/1‬‬\n      ‫‪1434‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n      ‫الشــيخ ‪ ......... /‬املســجل برقــم‪ .......‬وتاريــخ ‪1434/2/9‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪( ...../‬أفغانــي اجلنســية) يف قضيــة ســرقة‬\n      ‫ســيارة علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل بــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قــررت الدائــرة باألكثريــة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه‬\n\n\n‫‪197‬‬\n\f‫إلــى إضافــة أن املدعــى عليــه يتحــدث العربيــة بالضبــط والقــرار قبــل‬\n‫بعــث املعاملــة جلهــة التنفيــذ ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                 ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪198‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":193,"source_page_end":198,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e46151ef4a35f4b447ed13ce80ede122b1bb4cb2f1b8efcbb4aac418b3fed132","normalized_text_hash":"3d815496c5fda2e9a989ac715ada8e723d111e0cabdaf6aac47857cc0b2c8e4b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p193-3433183"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
